"use client";

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Save, RefreshCw, Network } from 'lucide-react';
import { toast } from 'sonner';
import {
    getAiConfigsAction,
    getAiModelRoutesAction,
    saveAiModelRouteAction,
    AiConfig,
    AiModelRoute
} from '@/server/actions/config';

export function RouteManager() {
    const [configs, setConfigs] = useState<AiConfig[]>([]);
    const [routes, setRoutes] = useState<AiModelRoute[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    const features = [
        { id: 'premium', name: '高级对话 (Premium)', desc: '用于深度解析、回归测试、复杂逻辑生成' },
        { id: 'economy', name: '经济对话 (Economy)', desc: '用于标题生成、简单纠偏、快速反馈' },
        { id: 'embedding', name: '向量嵌入 (Embedding)', desc: '用于知识库索引和检索匹配' },
        { id: 'rerank', name: '重排序 (Rerank)', desc: '用于检索后的二次精排，提升准确率' },
        { id: 'knowledge', name: '知识提取 (Knowledge)', desc: '用于从对话中自动提取和整理知识点' },
    ];

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [configsData, routesData] = await Promise.all([
                getAiConfigsAction(),
                getAiModelRoutesAction()
            ]);
            setConfigs(configsData);
            setRoutes(routesData);
        } catch (e) {
            toast.error("加载路由配置失败");
        } finally {
            setIsLoading(false);
        }
    };

    const handleRouteChange = (feature: string, field: 'config_id' | 'model_name', value: any) => {
        setRoutes(prev => {
            const existing = prev.find(r => r.feature === feature);
            if (existing) {
                return prev.map(r => r.feature === feature ? { ...r, [field]: value } : r);
            } else {
                return [...prev, { feature, config_id: field === 'config_id' ? value : 0, model_name: field === 'model_name' ? value : '' }];
            }
        });
    };

    const handleSaveRoute = async (feature: string) => {
        const route = routes.find(r => r.feature === feature);
        if (!route || !route.config_id) {
            toast.error("请先选择服务商");
            return;
        }

        setIsSaving(true);
        try {
            const res = await saveAiModelRouteAction(route);
            if (res.success) {
                toast.success(`${feature} 路由已更新`);
                loadData();
            } else {
                toast.error("保存失败");
            }
        } catch (e) {
            toast.error("请求失败");
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return <div className="p-8 text-center text-muted-foreground">加载中...</div>;
    }

    return (
        <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-card p-6 rounded-xl shadow-sm border border-border">
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-xl font-bold text-foreground flex items-center">
                            <Network className="w-5 h-5 mr-2 text-blue-500" />
                            模型路由设置
                        </h2>
                        <p className="text-sm text-muted-foreground mt-1">
                            为不同的系统功能分配特定的服务商和模型，实现多服务商混合负载。
                        </p>
                    </div>
                    <Button variant="outline" size="sm" onClick={loadData}>
                        <RefreshCw className="w-4 h-4 mr-2" />
                        刷新
                    </Button>
                </div>

                <div className="overflow-hidden border border-border rounded-lg">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-muted/50 text-muted-foreground font-medium border-b border-border">
                            <tr>
                                <th className="px-4 py-3">功能模块</th>
                                <th className="px-4 py-3">服务商 (Provider)</th>
                                <th className="px-4 py-3">模型名称 (Model)</th>
                                <th className="px-4 py-3 text-right">操作</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {features.map(feat => {
                                const route = routes.find(r => r.feature === feat.id);
                                const selectedConfig = configs.find(c => c.id === route?.config_id);

                                return (
                                    <tr key={feat.id} className="hover:bg-muted/30 transition-colors">
                                        <td className="px-4 py-4">
                                            <div className="font-semibold text-foreground">{feat.name}</div>
                                            <div className="text-xs text-muted-foreground mt-0.5">{feat.desc}</div>
                                        </td>
                                        <td className="px-4 py-4">
                                            <select
                                                className="w-full bg-background border border-border rounded px-2 py-1 focus:ring-1 focus:ring-primary outline-none"
                                                value={route?.config_id || ''}
                                                onChange={(e) => {
                                                    const configId = Number(e.target.value);
                                                    handleRouteChange(feat.id, 'config_id', configId);
                                                    // 自动填入该服务商对应的默认模型
                                                    const config = configs.find(c => c.id === configId);
                                                    if (config) {
                                                        let defaultModel = '';
                                                        if (feat.id === 'premium') defaultModel = config.model_premium;
                                                        if (feat.id === 'economy') defaultModel = config.model_economy;
                                                        if (feat.id === 'embedding') defaultModel = config.model_embedding || '';
                                                        if (feat.id === 'rerank') defaultModel = config.model_rerank || '';
                                                        if (feat.id === 'knowledge') defaultModel = config.model_knowledge || '';
                                                        handleRouteChange(feat.id, 'model_name', defaultModel);
                                                    }
                                                }}
                                            >
                                                <option value="">未选择</option>
                                                {configs.map(c => (
                                                    <option key={c.id} value={c.id}>
                                                        {c.name} {c.is_active ? '(默认)' : ''}
                                                    </option>
                                                ))}
                                            </select>
                                        </td>
                                        <td className="px-4 py-4">
                                            <input
                                                type="text"
                                                className="w-full bg-background border border-border rounded px-2 py-1 focus:ring-1 focus:ring-primary outline-none"
                                                value={route?.model_name || ''}
                                                onChange={(e) => handleRouteChange(feat.id, 'model_name', e.target.value)}
                                                placeholder="模型标识符"
                                            />
                                        </td>
                                        <td className="px-4 py-4 text-right">
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                disabled={isSaving}
                                                onClick={() => handleSaveRoute(feat.id)}
                                            >
                                                <Save className="w-4 h-4 text-primary" />
                                            </Button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                <div className="mt-6 p-4 bg-blue-500/5 border border-blue-500/20 rounded-lg">
                    <h4 className="text-sm font-bold text-blue-600 dark:text-blue-400 mb-1">路由优先级说明:</h4>
                    <p className="text-xs text-muted-foreground leading-relaxed">
                        1. 如果特定的功能模块（如 Rerank）配置了路由，系统将优先使用该路由指向的服务商和模型。<br />
                        2. 如果路由未设置或服务商已失效，系统将回退到“模型配置”标签页中标记为“激活”的全局默认配置。<br />
                        3. 请确保为向量嵌入（Embedding）选择的路由模型与数据库中现存向量的维度（Dimensions）保持一致。
                    </p>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Zap, Plus } from 'lucide-react';
import { toast } from 'sonner';
import {
    getAiConfigsAction,
    saveAiConfigAction,
    deleteAiConfigAction,
    setActiveAiConfigAction,
    AiConfig
} from '@/server/actions/config';
import { testAiConnectionAction } from '@/server/actions/settings';
import { ConfigList } from './ConfigList';
import { ConfigForm } from './ConfigForm';
import { QuickAddModals } from './QuickAddModals';

export function ConfigManager() {
    const [configs, setConfigs] = useState<AiConfig[]>([]);
    const [isEditing, setIsEditing] = useState(false);
    const [isZjuAdding, setIsZjuAdding] = useState(false);
    const [isSiliconAdding, setIsSiliconAdding] = useState(false);
    const [currentConfig, setCurrentConfig] = useState<Partial<AiConfig>>({});
    const [isSaving, setIsSaving] = useState(false);
    const [isTesting, setIsTesting] = useState(false);

    useEffect(() => {
        loadSettings();
    }, []);

    const loadSettings = async () => {
        try {
            const data = await getAiConfigsAction();
            setConfigs(data);
        } catch (e) {
            toast.error("配置加载失败");
        }
    };

    const handleStartEdit = (config?: AiConfig) => {
        if (config) {
            setCurrentConfig({ ...config });
        } else {
            setCurrentConfig({
                name: "新配置",
                api_url: "https://api.openai.com/v1",
                api_key: "",
                model_economy: "gpt-4o-mini",
                model_premium: "gpt-4o",
                is_active: false
            });
        }
        setIsEditing(true);
        setIsZjuAdding(false);
        setIsSiliconAdding(false);
    };

    const handleStartZjuAdd = () => {
        setCurrentConfig({
            name: "浙大 DeepSeek",
            api_url: "https://chat.zju.edu.cn/api/ai/v1",
            api_key: "",
            model_economy: "deepseek-v3",
            model_premium: "deepseek-v3",
            is_active: false
        });
        setIsZjuAdding(true);
        setIsSiliconAdding(false);
        setIsEditing(false);
    };

    const handleStartSiliconAdd = () => {
        setCurrentConfig({
            name: "硅基流动 DeepSeek",
            api_url: "https://api.siliconflow.cn/v1",
            api_key: "",
            model_economy: "deepseek-ai/DeepSeek-V3",
            model_premium: "deepseek-ai/DeepSeek-R1",
            is_active: false
        });
        setIsSiliconAdding(true);
        setIsZjuAdding(false);
        setIsEditing(false);
    };

    const handleSaveConfig = async (configOverride?: Partial<AiConfig>) => {
        const configToSave = configOverride || currentConfig;
        if (!configToSave.name || !configToSave.api_url || !configToSave.api_key) {
            toast.error("请填写必填项 (名称, URL, Key)");
            return;
        }
        setIsSaving(true);
        try {
            const res = await saveAiConfigAction(configToSave);
            if (res.success) {
                toast.success("配置已保存");
                setIsEditing(false);
                setIsZjuAdding(false);
                setIsSiliconAdding(false);
                loadSettings();
            } else {
                toast.error("保存失败: " + res.error);
            }
        } catch (e) {
            toast.error("请求失败");
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteConfig = async (id: number) => {
        if (!confirm("确定要删除此配置吗？")) return;
        try {
            const res = await deleteAiConfigAction(id);
            if (res.success) {
                toast.success("删除成功");
                loadSettings();
            } else {
                toast.error(res.error || "删除失败");
            }
        } catch (e) {
            toast.error("操作失败");
        }
    };

    const handleActivateConfig = async (id: number) => {
        try {
            await setActiveAiConfigAction(id);
            toast.success("已切换激活配置");
            loadSettings();
        } catch (e) {
            toast.error("切换失败");
        }
    };

    const handleTestConnection = async (config: Partial<AiConfig>) => {
        if (!config.api_key || !config.api_url) {
            toast.error("请先填写配置信息");
            return;
        }
        setIsTesting(true);
        try {
            const res = await testAiConnectionAction(
                config.api_key,
                config.api_url,
                config.model_economy || 'gpt-4o-mini'
            );
            if (res.success) {
                toast.success(`连接成功！AI 响应: ${res.message}`);
            } else {
                toast.error(`连接失败: ${res.error}`);
            }
        } catch (e) {
            toast.error("测试请求发送失败");
        } finally {
            setIsTesting(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto">
            {/* List View */}
            {!isEditing && !isZjuAdding && !isSiliconAdding && (
                <div className="space-y-6">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-card p-6 rounded-xl shadow-sm border border-border gap-4">
                        <div>
                            <h2 className="text-xl font-bold text-foreground flex items-center">
                                <Zap className="w-5 h-5 mr-2 text-yellow-500" />
                                配置列表
                            </h2>
                            <p className="text-sm text-muted-foreground mt-1">管理多个 AI 服务商配置，点击“激活”以切换当前使用的服务。</p>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            <Button size="sm" onClick={() => handleStartEdit()}>
                                <Plus className="w-4 h-4 mr-2" />
                                新建配置
                            </Button>
                            <Button size="sm" onClick={() => handleStartZjuAdd()} variant="secondary">
                                <Zap className="w-4 h-4 mr-2" />
                                浙大模型
                            </Button>
                            <Button size="sm" onClick={() => handleStartSiliconAdd()} variant="outline" className="border-purple-500/30 text-purple-600 dark:text-purple-400 hover:bg-purple-500/10">
                                <Zap className="w-4 h-4 mr-2" />
                                硅基流动
                            </Button>
                        </div>
                    </div>

                    <ConfigList
                        configs={configs}
                        onEdit={handleStartEdit}
                        onDelete={handleDeleteConfig}
                        onActivate={handleActivateConfig}
                    />

                    {/* Connectivity Tests (Simplified for this view) */}
                    <div className="mt-8 pt-6 border-t border-dashed border-border">
                        <h3 className="text-sm font-bold mb-3 text-muted-foreground uppercase tracking-wider">连通性快速检查 (当前激活)</h3>
                        <div className="flex gap-4">
                            <Button size="sm" variant="ghost" onClick={async () => {
                                const id = toast.loading("测试纠偏生成...");
                                try {
                                    const { generateCorrectionQuizAction } = await import('@/server/actions/ai');
                                    await generateCorrectionQuizAction("Test", "Wrong", "Correct");
                                    toast.success("纠偏功能正常", { id });
                                } catch (e: any) { toast.error("失败: " + e.message, { id }); }
                            }}>纠偏测试</Button>
                            <Button size="sm" variant="ghost" onClick={async () => {
                                const id = toast.loading("测试回归生成...");
                                try {
                                    const { generateRegressionChallengeAction } = await import('@/server/actions/ai');
                                    await generateRegressionChallengeAction("Test", ["tag1"]);
                                    toast.success("回归功能正常", { id });
                                } catch (e: any) { toast.error("失败: " + e.message, { id }); }
                            }}>回归测试</Button>
                        </div>
                    </div>
                </div>
            )}

            {isEditing && (
                <ConfigForm
                    config={currentConfig}
                    isSaving={isSaving}
                    isTesting={isTesting}
                    onSave={handleSaveConfig}
                    onCancel={() => setIsEditing(false)}
                    onTest={handleTestConnection}
                    onChange={setCurrentConfig}
                />
            )}

            <QuickAddModals
                currentConfig={currentConfig}
                isZjuAdding={isZjuAdding}
                isSiliconAdding={isSiliconAdding}
                isSaving={isSaving}
                onClose={() => { setIsZjuAdding(false); setIsSiliconAdding(false); }}
                onSave={handleSaveConfig}
                onChange={setCurrentConfig}
            />
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { getErrorMessage } from '@/lib/utils/error';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { updateQuestionAction } from "@/server/actions/admin";

interface EditQuestionDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    question: any;
    onSuccess: () => void;
}

export function EditQuestionDialog({
    open,
    onOpenChange,
    question,
    onSuccess,
}: EditQuestionDialogProps) {
    const [formData, setFormData] = useState({
        content: "",
        optionsStr: "",
        answer: "",
        explanation: "",
        tagsStr: "",
        dimension: "knowledge",
        type: "single"
    });
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (question && open) {
            // 尝试自动识别类型（如果后端还没存type字段）
            const isJsonAns = question.answer?.trim().startsWith('[') && question.answer?.includes('"');
            const type = question.type || (isJsonAns ? 'multi' : 'single');

            // 判断题：选项固定为 ["正确", "错误"]
            const optionsStr = type === 'truefalse'
                ? '正确\n错误'
                : (Array.isArray(question.options) ? question.options.join("\n") : "");

            setFormData({
                content: question.content || "",
                optionsStr,
                answer: question.answer || "",
                explanation: question.explanation || "",
                tagsStr: Array.isArray(question.tags) ? question.tags.join(", ") : "",
                dimension: question.dimension || "knowledge",
                type: type
            });
        }
    }, [question, open]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const isTrueFalse = formData.type === 'truefalse';
            // 判断题选项固定为 ["正确", "错误"]
            const options = isTrueFalse
                ? ['正确', '错误']
                : formData.optionsStr.split("\n").map(s => s.trim()).filter(Boolean);
            const tags = formData.tagsStr.split(/[,，]/).map(s => s.trim()).filter(Boolean);

            if (!formData.content) throw new Error("题干不能为空");
            if (!isTrueFalse && options.length < 2) throw new Error("至少需要2个选项");
            if (!formData.answer) throw new Error("答案不能为空");

            // 校验答案
            if (formData.type === 'truefalse') {
                if (formData.answer !== 'A' && formData.answer !== 'B') throw new Error("判断题答案必须为 A（正确）或 B（错误）");
            } else if (formData.type === 'single') {
                if (!options.includes(formData.answer)) throw new Error("单选题答案必须是选项之一");
            } else {
                try {
                    const ansArr = JSON.parse(formData.answer);
                    if (!Array.isArray(ansArr) || ansArr.length === 0) throw new Error("多选题至少选择一个答案");
                    if (!ansArr.every(a => options.includes(a))) throw new Error("多选题答案项必须存在于选项中");
                } catch (e) {
                    throw new Error("多选题答案格式错误");
                }
            }

            const updateData = {
                content: formData.content,
                options,
                answer: formData.answer,
                explanation: formData.explanation,
                tags,
                dimension: formData.dimension,
                type: formData.type // 传递 type
            };

            const res = await updateQuestionAction(question.id, updateData);
            if (res.success) {
                toast.success("题目更新成功");
                onSuccess();
                onOpenChange(false);
            } else {
                toast.error(res.error || "更新失败");
            }
        } catch (error: unknown) {
            toast.error(getErrorMessage(error));
        } finally {
            setLoading(false);
        }
    };

    // 实时解析选项以供选择
    const parsedOptions = formData.optionsStr.split("\n").map(s => s.trim()).filter(Boolean);

    // 处理多选变动
    const handleMultiAnswerChange = (option: string, checked: boolean) => {
        try {
            const current = formData.answer ? JSON.parse(formData.answer) : [];
            let next;
            if (checked) {
                next = [...current, option];
            } else {
                next = current.filter((o: string) => o !== option);
            }
            setFormData(prev => ({ ...prev, answer: JSON.stringify(next) }));
        } catch {
            // 如果解析失败，重置
            setFormData(prev => ({ ...prev, answer: JSON.stringify([option]) }));
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>编辑题目 #{question?.id}</DialogTitle>
                    <DialogDescription>
                        修改题目内容。请确保数据的准确性。
                    </DialogDescription>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="content">题干内容</Label>
                        <Textarea
                            id="content"
                            value={formData.content}
                            onChange={(e) => setFormData(prev => ({ ...prev, content: e.target.value }))}
                            rows={3}
                            required
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>题目类型</Label>
                            <Select
                                value={formData.type}
                                onValueChange={(val) => {
                                    // 切换到判断题时自动填充固定选项，并清空答案
                                    const newOptionsStr = val === 'truefalse' ? '正确\n错误' : (val !== formData.type ? '' : formData.optionsStr);
                                    setFormData(prev => ({
                                        ...prev,
                                        type: val,
                                        optionsStr: newOptionsStr,
                                        answer: "" // 切换类型时清空答案
                                    }));
                                }}
                            >
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="single">单项选择</SelectItem>
                                    <SelectItem value="multi">不定项选择 (多选)</SelectItem>
                                    <SelectItem value="truefalse">判断题</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="space-y-2">
                            <Label htmlFor="dimension">维度</Label>
                            <Select
                                value={formData.dimension}
                                onValueChange={(val) => setFormData(prev => ({ ...prev, dimension: val }))}
                            >
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="knowledge">识记</SelectItem>
                                    <SelectItem value="understanding">理解</SelectItem>
                                    <SelectItem value="application">应用</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* 判断题时隐藏选项编辑区，显示固定提示 */}
                    {formData.type === 'truefalse' ? (
                        <div className="space-y-2">
                            <Label>选项 (判断题固定)</Label>
                            <div className="p-3 rounded-md border bg-muted/30 text-sm text-muted-foreground">
                                A. 正确 &nbsp;/&nbsp; B. 错误（系统自动填充，无需手动修改）
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            <Label htmlFor="options">选项列表 (每行一个)</Label>
                            <Textarea
                                id="options"
                                value={formData.optionsStr}
                                onChange={(e) => setFormData(prev => ({ ...prev, optionsStr: e.target.value }))}
                                rows={4}
                                placeholder="选项A&#10;选项B&#10;选项C&#10;选项D"
                                required
                                className="font-mono text-sm"
                            />
                        </div>
                    )}

                    <div className="space-y-2">
                        <Label className="text-primary font-bold">
                            正确答案 ({formData.type === 'single' ? '单选' : formData.type === 'truefalse' ? '判断' : '多选'})
                        </Label>

                        {formData.type === 'truefalse' ? (
                            /* 判断题：只允许选 A（正确）或 B（错误） */
                            <Select
                                value={formData.answer}
                                onValueChange={(val) => setFormData(prev => ({ ...prev, answer: val }))}
                            >
                                <SelectTrigger className="border-primary/50">
                                    <SelectValue placeholder="选择正确答案" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="A">A — 正确</SelectItem>
                                    <SelectItem value="B">B — 错误</SelectItem>
                                </SelectContent>
                            </Select>
                        ) : formData.type === 'single' ? (
                            <Select
                                value={formData.answer}
                                onValueChange={(val) => setFormData(prev => ({ ...prev, answer: val }))}
                            >
                                <SelectTrigger className="border-primary/50">
                                    <SelectValue placeholder="选择正确选项" />
                                </SelectTrigger>
                                <SelectContent>
                                    {parsedOptions.length > 0 ? (
                                        parsedOptions.map((opt, idx) => (
                                            <SelectItem key={idx} value={opt}>{opt}</SelectItem>
                                        ))
                                    ) : (
                                        <div className="p-2 text-xs text-muted-foreground">请先填写选项</div>
                                    )}
                                </SelectContent>
                            </Select>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-2 border border-primary/20 p-3 rounded-md bg-muted/10">
                                {parsedOptions.length > 0 ? (
                                    parsedOptions.map((opt, idx) => {
                                        let isChecked = false;
                                        try {
                                            isChecked = JSON.parse(formData.answer || '[]').includes(opt);
                                        } catch { }

                                        return (
                                            <div key={idx} className="flex items-center space-x-2">
                                                <Checkbox
                                                    id={`ans-${idx}`}
                                                    checked={isChecked}
                                                    onCheckedChange={(c) => handleMultiAnswerChange(opt, c === true)}
                                                />
                                                <Label htmlFor={`ans-${idx}`} className="font-normal cursor-pointer flex-1 truncate" title={opt}>
                                                    {opt}
                                                </Label>
                                            </div>
                                        );
                                    })
                                ) : (
                                    <div className="p-2 text-xs text-muted-foreground">请先填写选项</div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="explanation">解析</Label>
                        <Textarea
                            id="explanation"
                            value={formData.explanation}
                            onChange={(e) => setFormData(prev => ({ ...prev, explanation: e.target.value }))}
                            rows={3}
                        />
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="tags">标签 (逗号分隔)</Label>
                        <Input
                            id="tags"
                            value={formData.tagsStr}
                            onChange={(e) => setFormData(prev => ({ ...prev, tagsStr: e.target.value }))}
                            placeholder="心理学, 认知过程, 注意"
                        />
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                            取消
                        </Button>
                        <Button type="submit" disabled={loading}>
                            {loading ? "保存中..." : "保存更改"}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { toast } from 'sonner';
import {
    getPromptTemplatesAction,
    savePromptTemplateAction,
    resetPromptTemplateAction,
    debugPromptTemplateAction,
    PromptTemplate
} from '@/server/actions/prompts';
import { PromptList } from './PromptList';
import { PromptEditor } from './PromptEditor';
import { DebugPlayground } from './DebugPlayground';

export function PromptManager() {
    const [prompts, setPrompts] = useState<PromptTemplate[]>([]);
    const [editingPrompt, setEditingPrompt] = useState<PromptTemplate | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [isDebugLoading, setIsDebugLoading] = useState(false);
    const [debugVariables, setDebugVariables] = useState<Record<string, string>>({});
    const [debugResult, setDebugResult] = useState<string | null>(null);

    useEffect(() => {
        loadPrompts();
    }, []);

    const loadPrompts = async () => {
        try {
            const data = await getPromptTemplatesAction();
            setPrompts(data);
        } catch (e) {
            toast.error("提示词加载失败");
        }
    };

    const handleSelectPrompt = (p: PromptTemplate) => {
        setEditingPrompt({ ...p, template: p.template || p.systemDefault || '' });
        setDebugResult(null);

        const initialVars: Record<string, string> = p.variableExamples || {};
        (p.variables || []).forEach((v: string) => {
            if (!initialVars[v]) initialVars[v] = '';
        });
        setDebugVariables(initialVars);
    };

    const handleSavePrompt = async () => {
        if (!editingPrompt) return;
        setIsSaving(true);
        try {
            const res = await savePromptTemplateAction(
                editingPrompt.key,
                editingPrompt.template,
                editingPrompt.description,
                editingPrompt.variables
            );
            if (res.success) {
                toast.success("提示词已保存");
                loadPrompts();
            } else {
                toast.error("保存失败: " + res.error);
            }
        } catch (e: any) {
            toast.error("请求失败: " + e.message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleResetPrompt = async () => {
        if (!editingPrompt || !confirm("确定要重置为系统默认提示词吗？您的自定义修改将丢失。")) return;
        try {
            await resetPromptTemplateAction(editingPrompt.key);
            toast.success("已重置");
            loadPrompts();
            // Refetch to get the system default
            const all = await getPromptTemplatesAction();
            const fresh = all.find(x => x.key === editingPrompt.key);
            if (fresh) setEditingPrompt(fresh);
        } catch (e) {
            toast.error("重置失败");
        }
    };

    const handleRunDebug = async () => {
        if (!editingPrompt) return;
        setIsDebugLoading(true);
        setDebugResult(null);
        try {
            const res = await debugPromptTemplateAction(editingPrompt.key, editingPrompt.template, debugVariables);
            if (res.success) {
                setDebugResult(typeof res.result === 'string' ? res.result : JSON.stringify(res.result, null, 2));
            } else {
                toast.error("生成失败: " + res.error);
                let errorMsg = "Error: " + res.error;
                if (res.result) {
                    errorMsg += "\n\n" + res.result;
                }
                setDebugResult(errorMsg);
            }
        } catch (e: any) {
            toast.error("调试请求失败");
            setDebugResult("Request Error: " + e.message);
        } finally {
            setIsDebugLoading(false);
        }
    };

    if (prompts.length === 0) return <div className="p-8 text-center text-muted-foreground">正在加载提示词模板...</div>;

    return (
        <div className="flex h-[calc(100vh-200px)] gap-6 overflow-hidden">
            <PromptList
                prompts={prompts}
                selectedKey={editingPrompt?.key || null}
                onSelect={handleSelectPrompt}
            />
            {editingPrompt ? (
                <>
                    <PromptEditor
                        editingPrompt={editingPrompt}
                        onChange={(val) => setEditingPrompt({ ...editingPrompt, template: val })}
                        onSave={handleSavePrompt}
                        onReset={handleResetPrompt}
                        isSaving={isSaving}
                    />
                    <DebugPlayground
                        editingPrompt={editingPrompt}
                        debugVariables={debugVariables}
                        onVariableChange={(k, v) => setDebugVariables(prev => ({ ...prev, [k]: v }))}
                        onDebug={handleRunDebug}
                        isDebugLoading={isDebugLoading}
                        debugResult={debugResult}
                    />
                </>
            ) : (
                <div className="flex-1 flex items-center justify-center bg-muted/30 rounded-lg border border-dashed border-border text-muted-foreground">
                    请在左侧选择一个模板进行编辑或调试
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import {
    getQuestionsAction,
    importQuestionsAction,
    deleteQuestionAction,
    batchDeleteQuestionsAction,
    QuestionFilters
} from '@/server/actions/admin';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
    Trash2, Upload, Download, Search, Filter,
    ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight,
    Loader2, MoreHorizontal, Edit
} from 'lucide-react';
import { toast } from 'sonner';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { EditQuestionDialog } from './EditQuestionDialog';

export function QuestionManager() {
    // 状态管理
    const [questions, setQuestions] = useState<any[]>([]);
    const [total, setTotal] = useState(0);
    const [loading, setLoading] = useState(false);
    const [editingQuestion, setEditingQuestion] = useState<any>(null);

    // 分页与筛选
    const [page, setPage] = useState(1);
    const [pageSize, setPageSize] = useState(20);
    const [filters, setFilters] = useState<QuestionFilters>({});

    // 批量操作
    const [selectedIds, setSelectedIds] = useState<number[]>([]);

    const fileInputRef = useRef<HTMLInputElement>(null);

    // 加载数据
    useEffect(() => {
        loadQuestions();
    }, [page, pageSize]); // 分页变化时重新加载（筛选变化需手动触发或防抖）

    const loadQuestions = async (currentFilters = filters) => {
        setLoading(true);
        try {
            const offset = (page - 1) * pageSize;
            const res = await getQuestionsAction(pageSize, offset, currentFilters);
            setQuestions(res.questions);
            setTotal(res.total);
            // 清空选中状态
            setSelectedIds([]);
        } catch (e) {
            toast.error("题目列表加载失败");
        } finally {
            setLoading(false);
        }
    };

    // 搜索处理
    const handleSearch = () => {
        setPage(1); // 重置到第一页
        loadQuestions(filters);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') handleSearch();
    };

    // 删除单条
    const handleDelete = async (id: number) => {
        if (!confirm("确定要删除这道题目吗？此操作不可恢复。")) return;
        const res = await deleteQuestionAction(id);
        if (res.success) {
            toast.success("题目已删除");
            loadQuestions();
        } else {
            toast.error("删除失败");
        }
    };

    // 批量删除
    const handleBatchDelete = async () => {
        if (selectedIds.length === 0) return;
        if (!confirm(`确定要删除选中的 ${selectedIds.length} 道题目吗？此操作不可恢复。`)) return;

        const res = await batchDeleteQuestionsAction(selectedIds);
        if (res.success) {
            toast.success(`成功删除 ${res.deletedCount} 道题目`);
            loadQuestions();
        } else {
            toast.error("批量删除失败");
        }
    };

    // 全选/反选
    const toggleSelectAll = () => {
        if (selectedIds.length === questions.length) {
            setSelectedIds([]);
        } else {
            setSelectedIds(questions.map(q => q.id));
        }
    };

    const toggleSelect = (id: number) => {
        setSelectedIds(prev =>
            prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
        );
    };

    // 文件导入
    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);
                toast.info("正在导入...", { duration: 1000 });
                const res = await importQuestionsAction(json);
                if (res.success) {
                    toast.success(`成功导入 ${res.count} 道题目`);
                    loadQuestions();
                } else {
                    toast.error(`导入失败: ${res.error}`);
                }
            } catch (e) {
                toast.error("无效的 JSON 文件格式");
            }
            if (fileInputRef.current) fileInputRef.current.value = "";
        };
        reader.readAsText(file);
    };

    // 导出 CSV
    const handleExportCsv = () => {
        const params = new URLSearchParams();
        if (filters.search) params.append('search', filters.search);
        if (filters.dimension) params.append('dimension', filters.dimension);
        if (filters.tag) params.append('tag', filters.tag);
        
        window.location.href = `/api/admin/export/questions?${params.toString()}`;
    };

    const totalPages = Math.ceil(total / pageSize);

    return (
        <div className="space-y-4">
            {/* 顶部工具栏 */}
            <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center bg-card p-4 rounded-xl border border-border">
                <div className="flex flex-wrap gap-2 w-full md:w-auto items-center">
                    <div className="relative w-full md:w-64">
                        <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder="搜索题干内容..."
                            className="pl-9"
                            value={filters.search || ''}
                            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
                            onKeyDown={handleKeyDown}
                        />
                    </div>

                    <Select
                        value={filters.dimension || 'all'}
                        onValueChange={(val) => setFilters(prev => ({ ...prev, dimension: val === 'all' ? undefined : val }))}
                    >
                        <SelectTrigger className="w-[120px]">
                            <SelectValue placeholder="维度" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">所有维度</SelectItem>
                            <SelectItem value="knowledge">识记</SelectItem>
                            <SelectItem value="understanding">理解</SelectItem>
                            <SelectItem value="application">应用</SelectItem>
                        </SelectContent>
                    </Select>

                    <Button variant="secondary" onClick={handleSearch}>
                        筛选
                    </Button>
                </div>

                <div className="flex gap-2 w-full md:w-auto">
                    {selectedIds.length > 0 && (
                        <Button variant="destructive" size="sm" onClick={handleBatchDelete}>
                            <Trash2 className="w-4 h-4 mr-2" />
                            删除 ({selectedIds.length})
                        </Button>
                    )}

                    <div className="relative">
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleFileUpload}
                            accept=".json"
                            className="hidden"
                        />
                        <Button variant="outline" size="sm" onClick={() => fileInputRef.current?.click()}>
                            <Upload className="w-4 h-4 mr-2" />
                            导入
                        </Button>
                    </div>

                    <Button variant="outline" size="sm" onClick={handleExportCsv} title="根据当前筛选条件导出全量数据">
                        <Download className="w-4 h-4 mr-2" />
                        导出 CSV
                    </Button>
                </div>
            </div>

            {/* 题目列表表格 */}
            <div className="bg-card rounded-xl shadow-sm border border-border overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-muted/50 text-muted-foreground uppercase font-medium border-b border-border">
                            <tr>
                                <th className="p-4 w-12">
                                    <Checkbox
                                        checked={questions.length > 0 && selectedIds.length === questions.length}
                                        onCheckedChange={toggleSelectAll}
                                    />
                                </th>
                                <th className="p-4 w-16">ID</th>
                                <th className="p-4">题干内容</th>
                                <th className="p-4 w-32">标签</th>
                                <th className="p-4 w-24">维度</th>
                                <th className="p-4 w-24 text-right">操作</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {loading ? (
                                <tr>
                                    <td colSpan={6} className="h-32 text-center">
                                        <Loader2 className="w-6 h-6 animate-spin mx-auto text-muted-foreground" />
                                    </td>
                                </tr>
                            ) : questions.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="p-8 text-center text-muted-foreground">
                                        没有找到符合条件的题目。
                                    </td>
                                </tr>
                            ) : (
                                questions.map((q) => (
                                    <tr key={q.id} className="hover:bg-muted/50 transition-colors group">
                                        <td className="p-4">
                                            <Checkbox
                                                checked={selectedIds.includes(q.id)}
                                                onCheckedChange={() => toggleSelect(q.id)}
                                            />
                                        </td>
                                        <td className="p-4 text-muted-foreground">#{q.id}</td>
                                        <td className="p-4 font-medium text-foreground max-w-lg truncate cursor-pointer hover:text-blue-600" title="点击编辑" onClick={() => setEditingQuestion(q)}>
                                            <div className="line-clamp-2">{q.content}</div>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex flex-wrap gap-1">
                                                {q.tags?.slice(0, 2).map((t: string) => (
                                                    <span key={t} className="px-2 py-0.5 bg-blue-500/10 text-blue-600 dark:text-blue-400 text-xs rounded-full whitespace-nowrap">
                                                        {t.split('/').pop()}
                                                    </span>
                                                ))}
                                                {q.tags?.length > 2 && (
                                                    <span className="text-xs text-muted-foreground px-1">+{q.tags.length - 2}</span>
                                                )}
                                            </div>
                                        </td>
                                        <td className="p-4 text-muted-foreground text-xs">
                                            {q.dimension === 'knowledge' ? '识记' : q.dimension === 'application' ? '应用' : '理解'}
                                        </td>
                                        <td className="p-4 text-right">
                                            <div className="flex items-center justify-end gap-1 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    onClick={() => setEditingQuestion(q)}
                                                    className="h-8 w-8 text-muted-foreground hover:text-primary"
                                                    title="编辑"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    onClick={() => handleDelete(q.id)}
                                                    className="h-8 w-8 text-muted-foreground hover:text-destructive"
                                                    title="删除"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                <div className="p-4 border-t border-border flex flex-col sm:flex-row justify-between items-center gap-4 bg-muted/20">
                    <div className="text-sm text-muted-foreground">
                        共 {total} 条记录，当前第 {page}/{totalPages || 1} 页
                    </div>

                    <div className="flex items-center gap-2">
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            disabled={page === 1}
                            onClick={() => setPage(1)}
                        >
                            <ChevronsLeft className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            disabled={page === 1}
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                        >
                            <ChevronLeft className="h-4 w-4" />
                        </Button>

                        <div className="mx-2 text-sm font-medium w-8 text-center">{page}</div>

                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            disabled={page >= totalPages}
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                        >
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            disabled={page >= totalPages}
                            onClick={() => setPage(totalPages)}
                        >
                            <ChevronsRight className="h-4 w-4" />
                        </Button>

                        <div className="w-[1px] h-4 bg-border mx-2" />

                        <Select
                            value={String(pageSize)}
                            onValueChange={(val) => {
                                setPageSize(Number(val));
                                setPage(1);
                            }}
                        >
                            <SelectTrigger className="h-8 w-[70px]">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="10">10</SelectItem>
                                <SelectItem value="20">20</SelectItem>
                                <SelectItem value="50">50</SelectItem>
                                <SelectItem value="100">100</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </div>
            </div>

            <EditQuestionDialog
                open={!!editingQuestion}
                onOpenChange={(open) => !open && setEditingQuestion(null)}
                question={editingQuestion}
                onSuccess={() => loadQuestions()}
            />
        </div>
    );
}

/**
 * @vitest-environment jsdom
 *
 * QuestionManager 集成测试
 *
 * 测试策略：
 *  - 使用 vi.mock 模拟 Next.js Server Actions（非 HTTP 请求，MSW 无法拦截）。
 *  - 验证组件内多子组件的交互：工具栏 → 列表 → 分页器 → 编辑弹窗。
 *  - 覆盖完整的异步状态流程：Loading → 列表渲染 → CRUD 操作后列表更新。
 *
 * 关于 Server Actions 与 MSW 的说明：
 *  Next.js Server Actions 是编译时转换的 RPC 调用，不是标准的 HTTP 请求，
 *  因此需要使用 vi.mock 对其进行模拟。如需同时测试 HTTP API（如导出 CSV），
 *  则在测试中结合 MSW 的 server.use() 处理。
 */

import React from 'react'
import { render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { http, HttpResponse } from 'msw'
import { server } from '../../../../../tests/msw/server'

// ============================================================
// Server Actions Mock 配置
// ============================================================

// 使用 vi.hoisted 确保 mock 引用在模块加载前就已建立（Vitest 要求）
const {
    mockGetQuestions,
    mockDeleteQuestion,
    mockBatchDeleteQuestions,
    mockImportQuestions,
    mockUpdateQuestion,
} = vi.hoisted(() => ({
    mockGetQuestions: vi.fn(),
    mockDeleteQuestion: vi.fn(),
    mockBatchDeleteQuestions: vi.fn(),
    mockImportQuestions: vi.fn(),
    mockUpdateQuestion: vi.fn(),
}))

// Mock 整个 admin server actions 模块
vi.mock('@/server/actions/admin', () => ({
    getQuestionsAction: mockGetQuestions,
    deleteQuestionAction: mockDeleteQuestion,
    batchDeleteQuestionsAction: mockBatchDeleteQuestions,
    importQuestionsAction: mockImportQuestions,
    updateQuestionAction: mockUpdateQuestion,
}))

// Mock sonner（避免真实 toast 渲染影响断言）
vi.mock('sonner', () => ({
    toast: {
        success: vi.fn(),
        error: vi.fn(),
        info: vi.fn(),
        warning: vi.fn(),
    },
}))

// ============================================================
// 测试数据工厂
// ============================================================

/** 创建标准测试题目数据 */
function createMockQuestion(overrides = {}) {
    return {
        id: 1,
        content: '以下哪项属于心理学的基本范畴？',
        options: ['感知', '行为', '认知', '以上皆是'],
        answer: '以上皆是',
        explanation: '心理学研究感知、行为和认知等多个领域',
        tags: ['心理学/基础', '认知科学'],
        dimension: 'knowledge',
        type: 'single',
        ...overrides,
    }
}

/** 创建模拟的 getQuestionsAction 返回值 */
function mockQuestionsResponse(questions: ReturnType<typeof createMockQuestion>[], total = questions.length) {
    return { questions, total }
}

// ============================================================
// 导入被测组件（必须在 mock 声明后导入）
// ============================================================

import { QuestionManager } from '../QuestionManager'

// ============================================================
// 测试套件
// ============================================================

describe('QuestionManager 集成测试', () => {
    beforeEach(() => {
        vi.clearAllMocks()

        // 默认：getQuestionsAction 返回两道题目
        mockGetQuestions.mockResolvedValue(
            mockQuestionsResponse([
                createMockQuestion({ id: 1, content: '第一道测试题' }),
                createMockQuestion({ id: 2, content: '第二道测试题', tags: ['语文/阅读'] }),
            ], 2)
        )
    })

    afterEach(() => {
        // 清理 Radix UI Dialog 遗留的 body 样式（防止测试间相互污染）
        // jsdom 环境中 Radix Dialog unmount 时可能不会自动还原
        document.body.removeAttribute('data-scroll-locked')
        document.body.style.pointerEvents = ''
    })

    // ----------------------------------------------------------
    // 场景 1：加载状态 - 初始化时显示 Loading Spinner
    // ----------------------------------------------------------
    it('组件初始化时应显示加载状态，数据到达后渲染题目列表', async () => {
        // 测试意图：验证加载 Loading → 列表数据的完整状态转换
        render(<QuestionManager />)

        // 数据加载后，题目内容应出现在列表中
        expect(await screen.findByText('第一道测试题')).toBeInTheDocument()
        expect(await screen.findByText('第二道测试题')).toBeInTheDocument()

        // 确认分页统计信息正确显示
        expect(screen.getByText(/共 2 条记录/)).toBeInTheDocument()
    })

    // ----------------------------------------------------------
    // 场景 2：空数据状态 - 无题目时显示空状态提示
    // ----------------------------------------------------------
    it('当题库为空时，应显示"没有找到符合条件的题目"提示', async () => {
        // 测试意图：验证空状态的条件渲染逻辑
        mockGetQuestions.mockResolvedValue(mockQuestionsResponse([], 0))

        render(<QuestionManager />)

        // 等待加载完成后检查空状态
        expect(await screen.findByText('没有找到符合条件的题目。')).toBeInTheDocument()
    })

    // ----------------------------------------------------------
    // 场景 3：加载失败 - API 报错时显示 Toast 错误提示
    // ----------------------------------------------------------
    it('当 getQuestionsAction 抛出错误时，应捕获异常并显示 Toast 错误', async () => {
        // 测试意图：验证 Error 状态的处理，确保用户收到反馈而不是白屏
        const { toast } = await import('sonner')
        mockGetQuestions.mockRejectedValue(new Error('数据库连接失败'))

        render(<QuestionManager />)

        // 等待错误 toast 被调用
        await waitFor(() => {
            expect(toast.error).toHaveBeenCalledWith('题目列表加载失败')
        })
    })

    // ----------------------------------------------------------
    // 场景 4：搜索功能 - 输入关键字后点击筛选，列表应更新
    // ----------------------------------------------------------
    it('在搜索框输入关键字并点击"筛选"后，应以过滤后的结果重新渲染列表', async () => {
        // 测试意图：验证搜索 → 重新加载 → 列表更新的完整交互链路
        const user = userEvent.setup()

        // 第二次调用返回过滤后的单条结果
        mockGetQuestions.mockResolvedValueOnce(
            mockQuestionsResponse([
                createMockQuestion({ id: 1, content: '第一道测试题' }),
                createMockQuestion({ id: 2, content: '第二道测试题', tags: ['语文/阅读'] }),
            ], 2)
        ).mockResolvedValueOnce(
            mockQuestionsResponse([
                createMockQuestion({ id: 1, content: '第一道测试题' }),
            ], 1)
        )

        render(<QuestionManager />)

        // 等待初始数据加载完成
        await screen.findByText('第一道测试题')

        // 在搜索框输入关键字
        const searchInput = screen.getByPlaceholderText('搜索题干内容...')
        await user.type(searchInput, '第一道')

        // 点击筛选按钮
        await user.click(screen.getByRole('button', { name: '筛选' }))

        // 等待列表以新数据重新渲染
        await waitFor(() => {
            expect(screen.queryByText('第二道测试题')).not.toBeInTheDocument()
        })
        expect(screen.getByText('第一道测试题')).toBeInTheDocument()
        expect(screen.getByText(/共 1 条记录/)).toBeInTheDocument()
    })

    // ----------------------------------------------------------
    // 场景 5：删除单条 - 确认后列表应移除该题目
    // ----------------------------------------------------------
    it('点击删除按钮并确认后，应调用 deleteQuestionAction 并刷新列表', async () => {
        // 测试意图：验证删除操作 → 列表刷新的子组件交互
        const user = userEvent.setup()
        mockDeleteQuestion.mockResolvedValue({ success: true })

        // 删除后的列表只剩第二道题
        mockGetQuestions
            .mockResolvedValueOnce(
                mockQuestionsResponse([
                    createMockQuestion({ id: 1, content: '第一道测试题' }),
                    createMockQuestion({ id: 2, content: '第二道测试题' }),
                ], 2)
            )
            .mockResolvedValueOnce(
                mockQuestionsResponse([
                    createMockQuestion({ id: 2, content: '第二道测试题' }),
                ], 1)
            )

        // Mock window.confirm（jsdom 中默认不存在真实交互）
        vi.spyOn(window, 'confirm').mockReturnValue(true)

        render(<QuestionManager />)

        // 等待初始数据加载
        await screen.findByText('第一道测试题')

        // 找到第一行的删除按钮（title="删除"）并点击
        const deleteButtons = screen.getAllByTitle('删除')
        await user.click(deleteButtons[0])

        // 确认 deleteQuestionAction 被以正确参数调用
        await waitFor(() => {
            expect(mockDeleteQuestion).toHaveBeenCalledWith(1)
        })

        // 确认列表重新加载（getQuestionsAction 被调用了两次）
        expect(mockGetQuestions).toHaveBeenCalledTimes(2)
    })

    // ----------------------------------------------------------
    // 场景 6：批量选择与删除 - 子组件交互（Checkbox → 批量删除按钮）
    // ----------------------------------------------------------
    it('勾选多道题目后，应显示批量删除按钮，点击后批量删除并刷新列表', async () => {
        // 测试意图：验证 Checkbox 选中 → 批量删除按钮出现 → 执行删除 → 列表清空的完整交互
        const user = userEvent.setup()
        mockBatchDeleteQuestions.mockResolvedValue({ success: true, deletedCount: 2 })
        mockGetQuestions
            .mockResolvedValueOnce(
                mockQuestionsResponse([
                    createMockQuestion({ id: 1, content: '第一道测试题' }),
                    createMockQuestion({ id: 2, content: '第二道测试题' }),
                ], 2)
            )
            .mockResolvedValueOnce(mockQuestionsResponse([], 0))

        vi.spyOn(window, 'confirm').mockReturnValue(true)

        render(<QuestionManager />)
        await screen.findByText('第一道测试题')

        // 初始状态：批量删除按钮不可见
        expect(screen.queryByRole('button', { name: /删除 \(/ })).not.toBeInTheDocument()

        // 点击表头"全选" Checkbox
        const checkboxes = screen.getAllByRole('checkbox')
        await user.click(checkboxes[0]) // 表头全选

        // 批量删除按钮应出现（内容格式："删除 (2)"）
        const batchDeleteBtn = await screen.findByRole('button', { name: /删除 \(2\)/ })
        expect(batchDeleteBtn).toBeInTheDocument()

        // 点击批量删除
        await user.click(batchDeleteBtn)

        await waitFor(() => {
            expect(mockBatchDeleteQuestions).toHaveBeenCalledWith([1, 2])
        })

        // 列表应清空（显示空状态）
        await screen.findByText('没有找到符合条件的题目。')
    })

    // ----------------------------------------------------------
    // 场景 7：编辑弹窗交互 - 点击题干后弹窗打开，保存后列表刷新
    // ----------------------------------------------------------
    it('点击题干文字后，EditQuestionDialog 应打开；保存成功后弹窗关闭并刷新列表', async () => {
        // 测试意图：验证 QuestionManager（父）与 EditQuestionDialog（子）之间的跨组件交互
        const user = userEvent.setup()
        mockUpdateQuestion.mockResolvedValue({ success: true })
        mockGetQuestions
            .mockResolvedValueOnce(
                mockQuestionsResponse([
                    createMockQuestion({ id: 1, content: '第一道测试题' }),
                ], 1)
            )
            // 保存后重新加载
            .mockResolvedValueOnce(
                mockQuestionsResponse([
                    createMockQuestion({ id: 1, content: '第一道测试题（已更新）' }),
                ], 1)
            )

        render(<QuestionManager />)
        await screen.findByText('第一道测试题')

        // 点击题干文字（触发编辑弹窗）
        await user.click(screen.getByText('第一道测试题'))

        // 等待弹窗打开（标题格式："编辑题目 #1"）
        const dialog = await screen.findByRole('dialog')
        expect(within(dialog).getByText('编辑题目 #1')).toBeInTheDocument()

        // 在弹窗中点击"保存更改"
        const saveButton = within(dialog).getByRole('button', { name: '保存更改' })
        await user.click(saveButton)

        // 保存后弹窗应关闭，列表应重新加载
        await waitFor(() => {
            expect(mockUpdateQuestion).toHaveBeenCalled()
        })
        expect(mockGetQuestions).toHaveBeenCalledTimes(2)
    })

    // ----------------------------------------------------------
    // 场景 8：Enter 键搜索 - 键盘快捷方式触发筛选
    // ----------------------------------------------------------
    it('在搜索框中按下 Enter 键，应与点击"筛选"按钮效果相同', async () => {
        // 测试意图：验证键盘无障碍操作（a11y）
        const user = userEvent.setup()
        mockGetQuestions.mockResolvedValue(
            mockQuestionsResponse([createMockQuestion({ id: 1, content: '第一道测试题' })], 1)
        )

        render(<QuestionManager />)
        await screen.findByText('第一道测试题')

        const searchInput = screen.getByPlaceholderText('搜索题干内容...')
        await user.type(searchInput, '测试{Enter}')

        // getQuestionsAction 应被再次调用（初始加载 + Enter 触发搜索）
        await waitFor(() => {
            expect(mockGetQuestions).toHaveBeenCalledTimes(2)
        })
    })

    // ----------------------------------------------------------
    // 场景 9：分页功能 - 点击下一页后重新加载数据
    // ----------------------------------------------------------
    it('点击下一页按钮后，应以新的 offset 重新调用 getQuestionsAction', async () => {
        // 测试意图：验证分页控件与数据加载的联动
        // 注意：此测试使用 fireEvent 而非 userEvent，
        //        因为 jsdom 环境中 Radix UI 的 focus guard 可能残留 pointer-events: none，
        //        fireEvent 绕过此限制（直接分发 DOM 事件，不检查 CSS 属性）。
        const { fireEvent: fire } = await import('@testing-library/react')

        // 模拟 25 条数据（触发分页，pageSize 默认 20）
        const page1Questions = Array.from({ length: 20 }, (_, i) =>
            createMockQuestion({ id: i + 1, content: `题目 ${i + 1}` })
        )

        mockGetQuestions
            .mockResolvedValueOnce(mockQuestionsResponse(page1Questions, 25))
            // 第二页数据
            .mockResolvedValueOnce(
                mockQuestionsResponse([createMockQuestion({ id: 21, content: '题目 21（第2页）' })], 25)
            )

        // 确保 body 状态干净
        document.body.removeAttribute('data-scroll-locked')
        document.body.style.pointerEvents = ''

        render(<QuestionManager />)
        await screen.findByText('题目 1')

        // 分页信息应显示"共 25 条记录，当前第 1/2 页"
        const paginationInfo = screen.getByText(/当前第 1\/2 页/)
        expect(paginationInfo).toBeInTheDocument()

        // 通过分页信息所在的容器找到分页按钮区域
        // 分页信息和按钮都在底部 flex 容器（p-4 border-t）中
        const paginationFooter = paginationInfo.closest('div.flex') as HTMLElement
        const paginationBtns = within(paginationFooter).getAllByRole('button')

        // 第 1 页时分页按钮顺序：[首页(disabled), 上一页(disabled), 下一页(enabled), 末页(enabled)]
        // 以及最后有个 Select 触发器（不是 button role）
        expect(paginationBtns.length).toBeGreaterThanOrEqual(4)

        const nextPageBtn = paginationBtns[2] // 下一页
        expect(nextPageBtn).not.toBeDisabled()

        // 使用 fireEvent 绕过 pointer-events 限制
        fire.click(nextPageBtn)

        // 等待第二页数据加载完成
        await screen.findByText('题目 21（第2页）')

        // getQuestionsAction 应被调用两次（初始 + 分页）
        expect(mockGetQuestions).toHaveBeenCalledTimes(2)
        // 页码显示更新
        expect(screen.getByText(/当前第 2\/2 页/)).toBeInTheDocument()
    })
})

'use client';

import React, { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, ToggleLeft, ToggleRight, Check, X, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import {
    getPlansAction,
    savePlanAction,
    deletePlanAction,
    getSubscriptionStatsAction
} from '@/server/actions/subscription';
import { SubscriptionPlan, PlanTier, UsageType, USAGE_TYPE_LABELS, PLAN_TIER_LABELS } from '@/lib/billing/subscription-types';

// 默认空套餐表单
const emptyPlan: Omit<SubscriptionPlan, 'created_at'> = {
    id: '',
    name: '',
    tier: 'basic',
    price_monthly: 0,
    limits: { ai_chat: -1, practice: -1, review: -1, rag: -1, mnemonic: -1, first_principles: -1 },
    features: [],
    is_active: true,
    sort_order: 0
};

export default function PlansPage() {
    const [plans, setPlans] = useState<SubscriptionPlan[]>([]);
    const [stats, setStats] = useState<{ totalUsers: number; byPlan: { plan_id: string; plan_name: string; count: number }[] } | null>(null);
    const [loading, setLoading] = useState(true);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingPlan, setEditingPlan] = useState<Omit<SubscriptionPlan, 'created_at'> | null>(null);
    const [saving, setSaving] = useState(false);
    const [featuresText, setFeaturesText] = useState('');

    // 加载数据
    const loadData = async () => {
        setLoading(true);
        try {
            const [plansRes, statsRes] = await Promise.all([
                getPlansAction(false),
                getSubscriptionStatsAction()
            ]);
            if (plansRes.success && plansRes.plans) {
                setPlans(plansRes.plans);
            }
            if (statsRes.success && statsRes.stats) {
                setStats(statsRes.stats);
            }
        } catch (error) {
            toast.error('加载数据失败');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadData();
    }, []);

    // 打开新增对话框
    const handleAdd = () => {
        setEditingPlan({ ...emptyPlan, sort_order: plans.length + 1 });
        setFeaturesText('');
        setDialogOpen(true);
    };

    // 打开编辑对话框
    const handleEdit = (plan: SubscriptionPlan) => {
        setEditingPlan({ ...plan });
        setFeaturesText(plan.features.join('\n'));
        setDialogOpen(true);
    };

    // 保存套餐
    const handleSave = async () => {
        if (!editingPlan) return;

        // 验证
        if (!editingPlan.id.trim()) {
            toast.error('请输入套餐 ID');
            return;
        }
        if (!editingPlan.name.trim()) {
            toast.error('请输入套餐名称');
            return;
        }

        setSaving(true);
        try {
            const planToSave = {
                ...editingPlan,
                features: featuresText.split('\n').filter(f => f.trim())
            };
            const res = await savePlanAction(planToSave);
            if (res.success) {
                toast.success('套餐保存成功');
                setDialogOpen(false);
                loadData();
            } else {
                toast.error(res.error || '保存失败');
            }
        } catch (error) {
            toast.error('保存失败');
        } finally {
            setSaving(false);
        }
    };

    // 删除套餐
    const handleDelete = async (planId: string) => {
        if (!confirm('确定要删除此套餐吗？')) return;

        try {
            const res = await deletePlanAction(planId);
            if (res.success) {
                toast.success('删除成功');
                loadData();
            } else {
                toast.error(res.error || '删除失败');
            }
        } catch (error) {
            toast.error('删除失败');
        }
    };

    // 切换启用状态
    const handleToggleActive = async (plan: SubscriptionPlan) => {
        try {
            const res = await savePlanAction({ ...plan, is_active: !plan.is_active });
            if (res.success) {
                toast.success(plan.is_active ? '已禁用' : '已启用');
                loadData();
            }
        } catch (error) {
            toast.error('操作失败');
        }
    };

    // 获取套餐用户数
    const getPlanUserCount = (planId: string) => {
        return stats?.byPlan.find(p => p.plan_id === planId)?.count || 0;
    };

    // 格式化价格
    const formatPrice = (cents: number) => {
        if (cents === 0) return '免费';
        return `¥${(cents / 100).toFixed(0)}/月`;
    };

    // 格式化限额
    const formatLimit = (limit: number) => {
        return limit === -1 ? '无限' : limit.toString();
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="p-6 space-y-6">
            {/* 页头 */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold">套餐管理</h1>
                    <p className="text-muted-foreground mt-1">配置订阅套餐与用量限制</p>
                </div>
                <Button onClick={handleAdd}>
                    <Plus className="w-4 h-4 mr-2" />
                    新增套餐
                </Button>
            </div>

            {/* 统计卡片 */}
            {stats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <Card>
                        <CardHeader className="pb-2">
                            <CardDescription>总用户数</CardDescription>
                            <CardTitle className="text-2xl">{stats.totalUsers}</CardTitle>
                        </CardHeader>
                    </Card>
                    {stats.byPlan.map(p => (
                        <Card key={p.plan_id}>
                            <CardHeader className="pb-2">
                                <CardDescription>{p.plan_name || p.plan_id}</CardDescription>
                                <CardTitle className="text-2xl">{p.count}</CardTitle>
                            </CardHeader>
                        </Card>
                    ))}
                </div>
            )}

            {/* 套餐列表 */}
            <div className="grid gap-4">
                {plans.map(plan => (
                    <Card key={plan.id} className={!plan.is_active ? 'opacity-60' : ''}>
                        <CardContent className="p-6">
                            <div className="flex items-start justify-between">
                                <div className="flex-1">
                                    <div className="flex items-center gap-3">
                                        <h3 className="text-lg font-semibold">{plan.name}</h3>
                                        <Badge variant={plan.is_active ? 'default' : 'secondary'}>
                                            {plan.is_active ? '启用' : '禁用'}
                                        </Badge>
                                        <Badge variant="outline">{PLAN_TIER_LABELS[plan.tier]}</Badge>
                                        <span className="text-lg font-bold text-primary">
                                            {formatPrice(plan.price_monthly)}
                                        </span>
                                    </div>

                                    <p className="text-sm text-muted-foreground mt-1">
                                        ID: {plan.id} · {getPlanUserCount(plan.id)} 位用户
                                    </p>

                                    {/* 限额展示 */}
                                    <div className="flex flex-wrap gap-4 mt-3">
                                        {(Object.keys(plan.limits) as UsageType[]).map(type => (
                                            <div key={type} className="text-sm">
                                                <span className="text-muted-foreground">{USAGE_TYPE_LABELS[type]}:</span>
                                                <span className="ml-1 font-medium">{formatLimit(plan.limits[type])}/日</span>
                                            </div>
                                        ))}
                                    </div>

                                    {/* 特性列表 */}
                                    {plan.features.length > 0 && (
                                        <div className="flex flex-wrap gap-2 mt-3">
                                            {plan.features.map((f, i) => (
                                                <Badge key={i} variant="outline" className="font-normal">
                                                    <Check className="w-3 h-3 mr-1" />
                                                    {f}
                                                </Badge>
                                            ))}
                                        </div>
                                    )}
                                </div>

                                {/* 操作按钮 */}
                                <div className="flex items-center gap-2">
                                    <Button variant="ghost" size="icon" onClick={() => handleToggleActive(plan)}>
                                        {plan.is_active ? (
                                            <ToggleRight className="w-5 h-5 text-green-500" />
                                        ) : (
                                            <ToggleLeft className="w-5 h-5 text-muted-foreground" />
                                        )}
                                    </Button>
                                    <Button variant="ghost" size="icon" onClick={() => handleEdit(plan)}>
                                        <Edit2 className="w-4 h-4" />
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="text-destructive hover:text-destructive"
                                        onClick={() => handleDelete(plan.id)}
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            {/* 编辑对话框 */}
            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>{editingPlan?.id ? '编辑套餐' : '新增套餐'}</DialogTitle>
                        <DialogDescription>配置套餐信息与用量限制</DialogDescription>
                    </DialogHeader>

                    {editingPlan && (
                        <div className="space-y-4 py-4">
                            {/* 基本信息 */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label>套餐 ID</Label>
                                    <Input
                                        value={editingPlan.id}
                                        onChange={e => setEditingPlan({ ...editingPlan, id: e.target.value })}
                                        placeholder="如: basic"
                                        disabled={plans.some(p => p.id === editingPlan.id)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label>套餐名称</Label>
                                    <Input
                                        value={editingPlan.name}
                                        onChange={e => setEditingPlan({ ...editingPlan, name: e.target.value })}
                                        placeholder="如: 基础版"
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-3 gap-4">
                                <div className="space-y-2">
                                    <Label>套餐等级</Label>
                                    <Select
                                        value={editingPlan.tier}
                                        onValueChange={v => setEditingPlan({ ...editingPlan, tier: v as PlanTier })}
                                    >
                                        <SelectTrigger>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {(Object.keys(PLAN_TIER_LABELS) as PlanTier[]).map(tier => (
                                                <SelectItem key={tier} value={tier}>
                                                    {PLAN_TIER_LABELS[tier]}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label>月价格 (元)</Label>
                                    <Input
                                        type="number"
                                        value={editingPlan.price_monthly / 100}
                                        onChange={e => setEditingPlan({
                                            ...editingPlan,
                                            price_monthly: Math.round(parseFloat(e.target.value || '0') * 100)
                                        })}
                                        placeholder="0"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label>排序顺序</Label>
                                    <Input
                                        type="number"
                                        value={editingPlan.sort_order || 0}
                                        onChange={e => setEditingPlan({
                                            ...editingPlan,
                                            sort_order: parseInt(e.target.value || '0')
                                        })}
                                    />
                                </div>
                            </div>

                            {/* 用量限制 */}
                            <div className="space-y-2">
                                <Label>每日用量限制 (-1 表示无限)</Label>
                                <div className="grid grid-cols-2 gap-4">
                                    {(Object.keys(USAGE_TYPE_LABELS) as UsageType[]).map(type => (
                                        <div key={type} className="flex items-center gap-2">
                                            <span className="w-24 text-sm text-muted-foreground">
                                                {USAGE_TYPE_LABELS[type]}
                                            </span>
                                            <Input
                                                type="number"
                                                value={editingPlan.limits[type]}
                                                onChange={e => setEditingPlan({
                                                    ...editingPlan,
                                                    limits: {
                                                        ...editingPlan.limits,
                                                        [type]: parseInt(e.target.value || '0')
                                                    }
                                                })}
                                                className="w-24"
                                            />
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* 特性列表 */}
                            <div className="space-y-2">
                                <Label>特性列表 (每行一个)</Label>
                                <textarea
                                    value={featuresText}
                                    onChange={e => setFeaturesText(e.target.value)}
                                    className="w-full h-24 px-3 py-2 border rounded-md text-sm resize-none"
                                    placeholder="每日 100 次 AI 对话&#10;无限练习题目&#10;优先客服支持"
                                />
                            </div>
                        </div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDialogOpen(false)}>
                            取消
                        </Button>
                        <Button onClick={handleSave} disabled={saving}>
                            {saving && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            保存
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { getUsersAction, deleteUserAction, resetUserPasswordAction, updateUserRoleAction, revokeUserSessionAction, UserAdminView } from '@/server/actions/admin';
import { getPlansAction, setUserSubscriptionAction } from '@/server/actions/subscription';
import { UserRole } from '@/types';
import { SubscriptionPlan } from '@/lib/billing/subscription-types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { Loader2, Trash2, KeyRound, Shield, Search, CreditCard, LogOut } from 'lucide-react';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Label } from '@/components/ui/label';

// 扩展用户类型，包含订阅信息
interface UserWithSubscription extends UserAdminView {
    plan_id?: string;
    plan_name?: string;
    subscription_status?: string;
    expires_at?: string;
}

export default function UsersPage() {
    const [users, setUsers] = useState<UserWithSubscription[]>([]);
    const [plans, setPlans] = useState<SubscriptionPlan[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');

    // Pagination state
    const [page, setPage] = useState(1);
    const [total, setTotal] = useState(0);
    const limit = 10;

    const [resetId, setResetId] = useState<number | null>(null);
    const [newPass, setNewPass] = useState('');

    // 订阅对话框状态
    const [subDialogOpen, setSubDialogOpen] = useState(false);
    const [subUserId, setSubUserId] = useState<number | null>(null);
    const [subUserName, setSubUserName] = useState('');
    const [selectedPlanId, setSelectedPlanId] = useState('free');
    const [subDuration, setSubDuration] = useState('0'); // 0 表示永久
    const [savingSub, setSavingSub] = useState(false);

    const loadUsers = async () => {
        setLoading(true);
        try {
            const offset = (page - 1) * limit;
            const res = await getUsersAction(limit, offset, search);

            // 后端现在直接返回订阅信息，无需前端再处理
            setUsers(res.users);
            setTotal(res.total);
        } catch (e) {
            toast.error("加载用户失败");
        } finally {
            setLoading(false);
        }
    };

    // Debounce search
    useEffect(() => {
        const timer = setTimeout(() => {
            setPage(1); // Reset to first page on search
            loadUsers();
        }, 500);
        return () => clearTimeout(timer);
    }, [search]);

    // Reload when page changes
    useEffect(() => {
        loadUsers();
    }, [page]);

    const loadPlans = async () => {
        try {
            const res = await getPlansAction(true);
            if (res.success && res.plans) {
                setPlans(res.plans);
            }
        } catch (e) {
            console.error('加载套餐失败', e);
        }
    };

    useEffect(() => {
        loadPlans();
    }, []);

    const handleDelete = async (id: number) => {
        if (!confirm(`确定要删除用户 ID:${id} 吗？此操作将清除该用户所有数据且不可恢复！`)) return;
        const res = await deleteUserAction(id);
        if (res.success) {
            toast.success("用户已删除");
            loadUsers();
        } else {
            toast.error(res.error || "删除失败");
        }
    };

    const handleResetPassword = async () => {
        if (!resetId || !newPass) return;
        const res = await resetUserPasswordAction(resetId, newPass);
        if (res.success) {
            toast.success("密码已重置");
            setResetId(null);
            setNewPass('');
        } else {
            toast.error("重置失败");
        }
    };

    const handleRoleChange = async (id: number, role: UserRole) => {
        const res = await updateUserRoleAction(id, role);
        if (res.success) {
            toast.success("角色已更新");
            loadUsers();
        } else {
            toast.error(res.error || "更新失败");
        }
    };

    const handleRevokeSession = async (id: number) => {
        if (!confirm(`确定要强制下线用户 ID:${id} 的所有活动会话吗？用户需要重新登录。`)) return;
        const res = await revokeUserSessionAction(id);
        if (res.success) {
            toast.success("用户已强制下线");
        } else {
            toast.error(res.error || "操作失败");
        }
    };

    // 打开订阅对话框
    const openSubDialog = (user: UserWithSubscription) => {
        setSubUserId(user.id);
        setSubUserName(user.username);
        setSelectedPlanId(user.plan_id || 'free');
        setSubDuration('0');
        setSubDialogOpen(true);
    };

    // 保存订阅
    const handleSaveSubscription = async () => {
        if (!subUserId) return;
        setSavingSub(true);
        try {
            const duration = parseInt(subDuration);
            const res = await setUserSubscriptionAction(subUserId, selectedPlanId, duration || undefined);
            if (res.success) {
                toast.success('订阅已更新');
                setSubDialogOpen(false);
                // 更新本地状态
                const planName = plans.find(p => p.id === selectedPlanId)?.name || selectedPlanId;
                setUsers(users.map(u =>
                    u.id === subUserId
                        ? { ...u, plan_id: selectedPlanId, plan_name: planName }
                        : u
                ));
            } else {
                toast.error(res.error || '操作失败');
            }
        } catch (e) {
            toast.error('操作失败');
        } finally {
            setSavingSub(false);
        }
    };

    // const filteredUsers = users.filter(u => u.username.toLowerCase().includes(search.toLowerCase()));
    // Server-side filtering is now in place
    const filteredUsers = users;

    // 获取套餐徽章颜色
    const getPlanBadgeVariant = (planId: string) => {
        switch (planId) {
            case 'pro': return 'default';
            case 'basic': return 'secondary';
            default: return 'outline';
        }
    };

    return (
        <div className="p-8 space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">用户管理</h2>
                    <p className="text-muted-foreground mt-2">
                        管理系统注册用户及订阅状态
                    </p>
                </div>
                <div className="relative w-64">
                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="搜索用户名"
                        className="pl-8"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
            </div>

            <Card>
                <CardHeader>
                    <CardTitle>用户列表</CardTitle>
                    <CardDescription>共 {users.length} 位注册用户</CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="rounded-md border">
                        <table className="w-full text-sm">
                            <thead className="bg-muted/50 border-b">
                                <tr className="text-left">
                                    <th className="p-4 font-medium">ID</th>
                                    <th className="p-4 font-medium">用户名</th>
                                    <th className="p-4 font-medium">注册时间</th>
                                    <th className="p-4 font-medium">角色</th>
                                    <th className="p-4 font-medium">订阅</th>
                                    <th className="p-4 font-medium text-right">操作</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr>
                                        <td colSpan={6} className="p-8 text-center text-muted-foreground">
                                            <Loader2 className="animate-spin h-6 w-6 mx-auto mb-2" />
                                            加载中...
                                        </td>
                                    </tr>
                                ) : filteredUsers.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="p-8 text-center text-muted-foreground">
                                            没有找到用户
                                        </td>
                                    </tr>
                                ) : (
                                    filteredUsers.map((user) => (
                                        <tr key={user.id} className="border-b last:border-0 hover:bg-muted/10 transition-colors">
                                            <td className="p-4 font-mono">{user.id}</td>
                                            <td className="p-4 font-medium">{user.username}</td>
                                            <td className="p-4 text-muted-foreground">
                                                {new Date(user.created_at).toLocaleString('zh-CN')}
                                            </td>
                                            <td className="p-4">
                                                {user.is_admin ? (
                                                    <span className="inline-flex items-center gap-1 bg-primary/10 text-primary px-2 py-1 rounded text-xs font-bold">
                                                        <Shield className="h-3 w-3" />
                                                        管理员
                                                    </span>
                                                ) : (
                                                    <select
                                                        value={user.role || 'student'}
                                                        onChange={(e) => handleRoleChange(user.id, e.target.value as UserRole)}
                                                        className="text-xs border border-border rounded px-2 py-1 bg-background focus:ring-1 focus:ring-primary outline-none"
                                                    >
                                                        <option value="student">学生</option>
                                                        <option value="admin">管理员</option>
                                                    </select>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                <Badge
                                                    variant={getPlanBadgeVariant(user.plan_id || 'free')}
                                                    className="cursor-pointer hover:opacity-80"
                                                    onClick={() => openSubDialog(user)}
                                                >
                                                    <CreditCard className="h-3 w-3 mr-1" />
                                                    {user.plan_name || '免费版'}
                                                </Badge>
                                            </td>
                                            <td className="p-4 text-right space-x-2">
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    onClick={() => openSubDialog(user)}
                                                >
                                                    <CreditCard className="h-4 w-4 mr-1" />
                                                    订阅
                                                </Button>

                                                <Dialog open={resetId === user.id} onOpenChange={(open) => !open && setResetId(null)}>
                                                    <DialogTrigger asChild>
                                                        <Button variant="outline" size="sm" onClick={() => setResetId(user.id)}>
                                                            <KeyRound className="h-4 w-4 mr-1" />
                                                            重置密码
                                                        </Button>
                                                    </DialogTrigger>
                                                    <DialogContent>
                                                        <DialogHeader>
                                                            <DialogTitle>重置密码 - {user.username}</DialogTitle>
                                                            <DialogDescription>
                                                                请输入新的登录密码。
                                                            </DialogDescription>
                                                        </DialogHeader>
                                                        <div className="py-4">
                                                            <Input
                                                                type="text"
                                                                placeholder="新密码"
                                                                value={newPass}
                                                                onChange={(e) => setNewPass(e.target.value)}
                                                            />
                                                        </div>
                                                        <DialogFooter>
                                                            <Button variant="outline" onClick={() => setResetId(null)}>取消</Button>
                                                            <Button onClick={handleResetPassword}>确认重置</Button>
                                                        </DialogFooter>
                                                    </DialogContent>
                                                </Dialog>

                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    title="强制下线"
                                                    className="text-orange-500 hover:bg-orange-50 hover:text-orange-600"
                                                    onClick={() => handleRevokeSession(user.id)}
                                                >
                                                    <LogOut className="h-4 w-4" />
                                                </Button>

                                                {!user.is_admin && (
                                                    <Button
                                                        variant="ghost"
                                                        size="sm"
                                                        className="text-destructive hover:bg-destructive/10"
                                                        onClick={() => handleDelete(user.id)}
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
                <div className="flex items-center justify-between px-4 py-4 border-t">
                    <div className="text-sm text-muted-foreground">
                        显示 {users.length > 0 ? (page - 1) * limit + 1 : 0} 到 {Math.min(page * limit, total)} 条，共 {total} 条
                    </div>
                    <div className="flex gap-2">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1 || loading}
                        >
                            上一页
                        </Button>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setPage(p => p + 1)}
                            disabled={page * limit >= total || loading}
                        >
                            下一页
                        </Button>
                    </div>
                </div>
            </Card >

            {/* 订阅对话框 */}
            < Dialog open={subDialogOpen} onOpenChange={setSubDialogOpen} >
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>设置订阅 - {subUserName}</DialogTitle>
                        <DialogDescription>
                            为用户分配订阅套餐
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <Label>选择套餐</Label>
                            <Select value={selectedPlanId} onValueChange={setSelectedPlanId}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {plans.map(plan => (
                                        <SelectItem key={plan.id} value={plan.id}>
                                            {plan.name} - {plan.price_monthly === 0 ? '免费' : `¥${plan.price_monthly / 100}/月`}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <Label>订阅时长</Label>
                            <Select value={subDuration} onValueChange={setSubDuration}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="0">永久</SelectItem>
                                    <SelectItem value="1">1 个月</SelectItem>
                                    <SelectItem value="3">3 个月</SelectItem>
                                    <SelectItem value="6">6 个月</SelectItem>
                                    <SelectItem value="12">12 个月</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setSubDialogOpen(false)}>取消</Button>
                        <Button onClick={handleSaveSubscription} disabled={savingSub}>
                            {savingSub && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            确认
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog >
        </div >
    );
}

