import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, waitFor, act } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import React from 'react';
import { useKnowledgeCards } from '../useKnowledgeCards';

// Mock fetch
const mockFetch = vi.fn();
vi.stubGlobal('fetch', mockFetch);

// Mock window.confirm
vi.stubGlobal('confirm', vi.fn(() => true));

/** 每个测试用例创建独立的 QueryClient wrapper */
function createWrapper() {
    const queryClient = new QueryClient({
        defaultOptions: {
            queries: { retry: false, staleTime: 0 },
        },
    });
    return ({ children }: { children: React.ReactNode }) =>
        React.createElement(QueryClientProvider, { client: queryClient }, children);
}

// 模拟 API 返回数据
const mockApiResponse = {
    cards: [
        { id: 1, title: '测试卡片1', front: '正面1', back: '背面1', tags: ['标签1'] },
        { id: 2, title: '测试卡片2', front: '正面2', back: '背面2', tags: ['标签2'] },
    ],
    categories: ['分类A', '分类B'],
    stats: { total: 2, byCategory: [{ category: '分类A', count: 1 }] },
};

describe('useKnowledgeCards', () => {
    beforeEach(() => {
        mockFetch.mockReset();
        // 默认返回成功响应
        mockFetch.mockResolvedValue(new Response(JSON.stringify(mockApiResponse), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        }));
    });

    it('应该自动加载知识卡片列表', async () => {
        const { result } = renderHook(() => useKnowledgeCards(), { wrapper: createWrapper() });

        // 初始状态为 loading
        expect(result.current.loading).toBe(true);

        await waitFor(() => expect(result.current.loading).toBe(false));

        expect(result.current.cards).toHaveLength(2);
        expect(result.current.categories).toEqual(['分类A', '分类B']);
        expect(result.current.stats.total).toBe(2);
    });

    it('应该支持按搜索关键词过滤卡片', async () => {
        const { result } = renderHook(() => useKnowledgeCards(), { wrapper: createWrapper() });

        await waitFor(() => expect(result.current.loading).toBe(false));

        act(() => {
            result.current.setSearchQuery('卡片1');
        });

        expect(result.current.filteredCards).toHaveLength(1);
        expect(result.current.filteredCards[0].title).toBe('测试卡片1');
    });

    it('删除卡片后应重新获取列表', async () => {
        const { result } = renderHook(() => useKnowledgeCards(), { wrapper: createWrapper() });

        await waitFor(() => expect(result.current.loading).toBe(false));

        // 模拟删除 API 调用
        mockFetch.mockResolvedValueOnce(new Response('ok', { status: 200 }));
        // 模拟删除后的重新获取
        mockFetch.mockResolvedValueOnce(new Response(JSON.stringify({
            ...mockApiResponse,
            cards: [mockApiResponse.cards[1]],
            stats: { total: 1, byCategory: [] },
        }), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        }));

        await act(async () => {
            result.current.handleDelete(1);
        });

        // 验证"删除"请求发送了
        await waitFor(() => {
            const deleteCalls = mockFetch.mock.calls.filter(
                (call: any[]) => call[1]?.method === 'DELETE'
            );
            expect(deleteCalls.length).toBeGreaterThanOrEqual(1);
        });
    });

    it('保存卡片后应重新获取列表并关闭编辑态', async () => {
        const { result } = renderHook(() => useKnowledgeCards(), { wrapper: createWrapper() });

        await waitFor(() => expect(result.current.loading).toBe(false));

        // 设置编辑状态
        act(() => {
            result.current.setEditingCard({ title: '新卡片', front: 'Q', back: 'A' });
            result.current.setIsCreateModal(true);
        });

        expect(result.current.editingCard).not.toBeNull();

        // 模拟保存 API
        mockFetch.mockResolvedValueOnce(new Response('ok', { status: 200 }));
        // 模拟刷新
        mockFetch.mockResolvedValueOnce(new Response(JSON.stringify(mockApiResponse), {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
        }));

        await act(async () => {
            result.current.handleSave();
        });

        // 保存成功后编辑态应关闭
        await waitFor(() => {
            expect(result.current.editingCard).toBeNull();
            expect(result.current.isCreateModal).toBe(false);
        });
    });

    it('API 失败时应显示错误 toast', async () => {
        // 首次加载正常
        const { result } = renderHook(() => useKnowledgeCards(), { wrapper: createWrapper() });
        await waitFor(() => expect(result.current.loading).toBe(false));

        // 模拟保存失败
        mockFetch.mockResolvedValueOnce(new Response('error', { status: 500, statusText: 'ISE' }));

        act(() => {
            result.current.setEditingCard({ title: '失败卡片' });
        });

        await act(async () => {
            result.current.handleSave();
        });

        await waitFor(() => {
            expect(result.current.toast?.type).toBe('error');
        });
    });
});

'use client';

import { useState, useCallback, useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { KnowledgeCard } from '@/lib/services/knowledge';
import { fetchJson } from '@/lib/utils/api-client';

/** React Query 的 Query Key 常量 */
const KNOWLEDGE_CARDS_KEY = 'knowledge-cards';

/**
 * 知识卡片的数据获取与操作 Hook（React Query 版本）。
 * 利用 useQuery 自动缓存卡片列表，useMutation 处理增删改后自动刷新。
 */
export function useKnowledgeCards() {
    const queryClient = useQueryClient();
    const [selectedCategory, setSelectedCategory] = useState<string>('');
    const [searchQuery, setSearchQuery] = useState('');
    const [editingCard, setEditingCard] = useState<Partial<KnowledgeCard> | null>(null);
    const [isCreateModal, setIsCreateModal] = useState(false);
    const [exporting, setExporting] = useState(false);
    const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

    const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    }, []);

    // ---- 查询：使用 useQuery 自动缓存 ----
    const { data, isLoading: loading } = useQuery({
        queryKey: [KNOWLEDGE_CARDS_KEY, selectedCategory],
        queryFn: async () => {
            const params = new URLSearchParams();
            if (selectedCategory) params.set('category', selectedCategory);
            return fetchJson<{
                cards: KnowledgeCard[];
                categories: string[];
                stats: { total: number; byCategory: { category: string; count: number }[] };
            }>(`/api/knowledge/cards?${params.toString()}`);
        },
    });

    const cards = data?.cards ?? [];
    const categories = data?.categories ?? [];
    const stats = data?.stats ?? { total: 0, byCategory: [] };

    // ---- 客户端搜索过滤 ----
    const filteredCards = useMemo(() => {
        if (!cards) return [];
        return cards.filter(card => {
            if (!searchQuery) return true;
            const query = searchQuery.toLowerCase();
            const titleMatch = (card.title || '').toLowerCase().includes(query);
            const frontMatch = (card.front || '').toLowerCase().includes(query);
            const backMatch = (card.back || '').toLowerCase().includes(query);
            const tagMatch = Array.isArray(card.tags) && card.tags.some(t => String(t).toLowerCase().includes(query));
            return titleMatch || frontMatch || backMatch || tagMatch;
        });
    }, [cards, searchQuery]);

    // ---- 删除：useMutation + 自动刷新 ----
    const deleteMutation = useMutation({
        mutationFn: async (id: number) => {
            const resp = await fetch(`/api/knowledge/cards/${id}`, { method: 'DELETE' });
            if (!resp.ok) throw new Error('删除失败');
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [KNOWLEDGE_CARDS_KEY] });
            showToast('已删除知识卡片');
        },
        onError: (error) => {
            console.error('删除失败:', error);
            showToast('删除失败', 'error');
        },
    });

    const handleDelete = async (id: number) => {
        if (!confirm('确定删除这张知识卡片吗？')) return;
        deleteMutation.mutate(id);
    };

    // ---- 保存（创建/更新）：useMutation + 自动刷新 ----
    const saveMutation = useMutation({
        mutationFn: async (card: Partial<KnowledgeCard>) => {
            const isUpdate = !!card.id;
            const url = isUpdate ? `/api/knowledge/cards/${card.id}` : `/api/knowledge/cards`;
            const method = isUpdate ? 'PUT' : 'POST';

            const resp = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(card),
            });
            if (!resp.ok) throw new Error('保存失败');
        },
        onSuccess: (_, card) => {
            const isUpdate = !!card.id;
            showToast(isUpdate ? '卡片更新成功' : '卡片创建成功');
            setEditingCard(null);
            setIsCreateModal(false);
            queryClient.invalidateQueries({ queryKey: [KNOWLEDGE_CARDS_KEY] });
        },
        onError: (error) => {
            console.error('保存失败:', error);
            showToast('保存失败', 'error');
        },
    });

    const handleSave = async () => {
        if (!editingCard) return;
        saveMutation.mutate(editingCard);
    };

    // ---- 导出（保持原逻辑，非缓存相关） ----
    const handleExport = async () => {
        setExporting(true);
        try {
            const params = new URLSearchParams();
            params.set('format', 'anki');
            if (selectedCategory) params.set('category', selectedCategory);

            const response = await fetch(`/api/knowledge/cards?${params.toString()}`);
            if (!response.ok) throw new Error('导出失败');

            const blob = await response.blob();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `knowledge_cards_${Date.now()}.txt`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);

            showToast('导出成功！已保存为 Anki 格式');
        } catch (error) {
            console.error('导出失败:', error);
            showToast('导出失败，请重试', 'error');
        } finally {
            setExporting(false);
        }
    };

    // 提供给外部手动刷新的方法（完全兼容原有 API）
    const loadCards = useCallback(() => {
        queryClient.invalidateQueries({ queryKey: [KNOWLEDGE_CARDS_KEY] });
    }, [queryClient]);

    return {
        cards,
        filteredCards,
        categories,
        stats,
        loading,
        selectedCategory,
        setSelectedCategory,
        searchQuery,
        setSearchQuery,
        editingCard,
        setEditingCard,
        isCreateModal,
        setIsCreateModal,
        exporting,
        toast,
        handleDelete,
        handleSave,
        handleExport,
        loadCards
    };
}

'use client';

import React, { useState } from 'react';
import { BookOpen, Loader2, CheckCircle2, AlertCircle, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { getCategoryColor } from '@/lib/utils/category-colors';
import { APPLE_SPRING } from '@/lib/configs/motion-config';

// Hooks
import { useKnowledgeCards } from './hooks/useKnowledgeCards';
import { useStudyMode } from './hooks/useStudyMode';

// Components
import { KnowledgeHeader } from './components/KnowledgeHeader';
import { KnowledgeCardItem } from './components/KnowledgeCardItem';
import { StudyModeOverlay } from './components/StudyModeOverlay';
import { KnowledgeModal } from './components/KnowledgeModal';
import { AIGenerateModal } from './components/AIGenerateModal';
import { KnowledgeCardExpanded } from './components/KnowledgeCardExpanded';
import MarkdownViewer from '@/components/chat/MarkdownViewer';

export default function KnowledgePage() {
    const [selectedCard, setSelectedCard] = useState<any>(null);
    const {
        filteredCards,
        categories,
        stats,
        loading,
        selectedCategory,
        setSelectedCategory,
        searchQuery,
        setSearchQuery,
        editingCard,
        setEditingCard,
        isCreateModal,
        setIsCreateModal,
        exporting,
        toast,
        handleDelete,
        handleSave,
        handleExport,
        loadCards
    } = useKnowledgeCards();

    // AI 生成弹窗状态
    const [showAIModal, setShowAIModal] = useState(false);

    // AI 生成保存处理
    const handleAISave = async (card: Partial<typeof filteredCards[number]>) => {
        try {
            const resp = await fetch('/api/knowledge/cards', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(card),
            });
            if (!resp.ok) throw new Error('保存失败');
            loadCards(); // 刷新卡片列表
        } catch (error) {
            console.error('AI 生成保存失败:', error);
        }
    };

    const {
        studyMode,
        studyIndex,
        studyFlipped,
        toggleStudyFlip,
        startStudy,
        exitStudy,
        nextCard,
        prevCard
    } = useStudyMode(filteredCards);

    const [flippedCards, setFlippedCards] = useState<Set<number>>(new Set());

    const toggleFlip = (id: number) => {
        setFlippedCards(prev => {
            const newSet = new Set(prev);
            if (newSet.has(id)) newSet.delete(id);
            else newSet.add(id);
            return newSet;
        });
    };

    // 获取分类对应的颜色 (保持逻辑一致)
    // 获取分类对应的颜色 (保持逻辑一致)
    // 逻辑已移至 src/lib/utils/category-colors.ts

    return (
        <div className="min-h-screen bg-background">
            <KnowledgeHeader
                stats={stats}
                categories={categories}
                selectedCategory={selectedCategory}
                setSelectedCategory={setSelectedCategory}
                searchQuery={searchQuery}
                setSearchQuery={setSearchQuery}
                onAdd={() => {
                    setEditingCard({ title: '', category: '', tags: [], front: '', back: '', key_points: [] });
                    setIsCreateModal(true);
                }}
                onAIGenerate={() => setShowAIModal(true)}
                onStudy={startStudy}
                onExport={handleExport}
                exporting={exporting}
                filteredCount={filteredCards.length}
            />

            <main className="max-w-7xl mx-auto px-4 py-8 pb-32">
                {loading ? (
                    <div className="flex flex-col items-center justify-center py-20">
                        <Loader2 className="w-10 h-10 animate-spin text-primary" />
                        <p className="mt-4 text-muted-foreground font-medium tracking-wide">加载知识库中...</p>
                    </div>
                ) : filteredCards.length === 0 ? (
                    <div className="text-center py-24 bg-card/40 backdrop-blur-sm rounded-3xl border-2 border-dashed border-border">
                        <div className="w-24 h-24 mx-auto mb-6 bg-muted rounded-full flex items-center justify-center shadow-inner">
                            <BookOpen className="w-12 h-12 text-muted-foreground" />
                        </div>
                        <h3 className="text-xl font-bold text-foreground mb-2">未找到匹配的卡片</h3>
                        <p className="text-muted-foreground max-w-sm mx-auto">尝试改变搜索词或切换分类。</p>
                    </div>
                ) : (
                    <div className="grid gap-6 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
                        {filteredCards.map((card: any, index: number) => (
                            <motion.div 
                                key={card.id} 
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.05, duration: 0.5 }}
                            >
                                <KnowledgeCardItem
                                    card={card}
                                    onExpand={setSelectedCard}
                                    onEdit={setEditingCard}
                                    categoryColor={getCategoryColor(card.category || '默认')}
                                />
                            </motion.div>
                        ))}
                    </div>
                )}
            </main>

            {/* SHARED LAYOUT OVERLAY */}
            <AnimatePresence>
                {selectedCard && (
                    <KnowledgeCardExpanded 
                        card={selectedCard} 
                        onClose={() => setSelectedCard(null)} 
                    />
                )}
            </AnimatePresence>

            <KnowledgeModal
                isOpen={!!editingCard || isCreateModal}
                isCreate={isCreateModal}
                card={editingCard}
                onClose={() => { setEditingCard(null); setIsCreateModal(false); }}
                onSave={handleSave}
                onChange={setEditingCard}
            />

            <AIGenerateModal
                isOpen={showAIModal}
                onClose={() => setShowAIModal(false)}
                onSave={handleAISave}
            />

            {studyMode && (
                <StudyModeOverlay
                    cards={filteredCards}
                    studyIndex={studyIndex}
                    studyFlipped={studyFlipped}
                    toggleFlip={toggleStudyFlip}
                    onNext={nextCard}
                    onPrev={prevCard}
                    onExit={exitStudy}
                />
            )}

            {toast && (
                <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-300 ${toast.type === 'success' ? 'bg-zinc-900 border-t-2 border-emerald-400' : 'bg-red-600'
                    }`}>
                    {toast.type === 'success' ? (
                        <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                    ) : (
                        <AlertCircle className="w-5 h-5 text-white" />
                    )}
                    <span className="text-white font-bold text-sm">{toast.message}</span>
                </div>
            )}

            <style jsx global>{`
                .scrollbar-hide::-webkit-scrollbar { display: none; }
                .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: var(--border); border-radius: 10px; }
            `}</style>
        </div>
    );
}

