'use client';

import React from 'react';
import Link from 'next/link';
import { useRouter, usePathname } from 'next/navigation';
import { Plus, Trash2, Network } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { createMindmapAction, deleteMindmapAction } from '@/server/actions/mindmap-db';
import { toast } from 'sonner';

interface MindmapSidebarProps {
    records: { id: number; title: string; updated_at: string }[];
}

export function MindmapSidebar({ records }: MindmapSidebarProps) {
    const router = useRouter();
    const pathname = usePathname();

    const handleCreate = async () => {
        const loading = toast.loading('创建中...');
        try {
            const result = await createMindmapAction();
            if (result.success && result.id) {
                router.push(`/mindmap/${result.id}`);
                toast.success('新建成功', { id: loading });
            } else {
                toast.error(result.message || '创建失败', { id: loading });
            }
        } catch (error) {
            toast.error('请求失败', { id: loading });
        }
    };

    const handleDelete = async (id: number, e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!confirm('确定要删除这张思维导图吗？')) return;

        try {
            const result = await deleteMindmapAction(id);
            if (result.success) {
                toast.success('删除成功');
                if (pathname === `/mindmap/${id}`) {
                    router.push('/mindmap');
                }
            } else {
                toast.error(result.message || '删除失败');
            }
        } catch (error) {
            toast.error('请求失败');
        }
    };

    return (
        <div className="w-64 border-r border-border h-[calc(100vh-64px)] bg-muted/20 flex flex-col font-sans">
            <div className="p-4 border-b border-border">
                <Button
                    onClick={handleCreate}
                    className="w-full justify-start gap-2 h-10 shadow-sm"
                    variant="default"
                >
                    <Plus className="w-4 h-4" />
                    新建导图
                </Button>
            </div>

            <div className="flex-1 overflow-y-auto p-3 space-y-1 scrollbar-thin">
                {records.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground text-sm opacity-60">
                        暂无思维导图记录
                    </div>
                ) : (
                    records.map(record => {
                        const isActive = pathname === `/mindmap/${record.id}`;
                        return (
                            <Link
                                key={record.id}
                                href={`/mindmap/${record.id}`}
                                className={`group flex items-center justify-between p-2.5 rounded-lg text-sm transition-colors ${
                                    isActive
                                        ? 'bg-primary/10 text-primary font-medium'
                                        : 'hover:bg-muted text-foreground'
                                }`}
                            >
                                <div className="flex items-center gap-2 overflow-hidden">
                                    <Network className="w-4 h-4 flex-shrink-0 opacity-70" />
                                    <span className="truncate">{record.title}</span>
                                </div>

                                <button
                                    onClick={(e) => handleDelete(record.id, e)}
                                    className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-destructive/10 hover:text-destructive rounded transition-all"
                                    title="删除"
                                >
                                    <Trash2 className="w-3 h-3" />
                                </button>
                            </Link>
                        );
                    })
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useState, useCallback, useRef } from 'react';
import { getErrorMessage } from '@/lib/utils/error';
import { Network, Wand2, Trash2, AlignLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';
import dynamic from 'next/dynamic';
import { generateMindmapAction } from '@/server/actions/mindmap';
import { updateMindmapAction } from '@/server/actions/mindmap-db';
import { toast } from 'sonner';

const SimpleMindMapViewer = dynamic(
    () => import('@/components/ocr/SimpleMindMapViewer').then(mod => mod.SimpleMindMapViewer),
    { ssr: false, loading: () => <div className="h-full w-full flex items-center justify-center text-muted-foreground animate-pulse">引擎装载中...</div> }
);

interface MindmapEditorClientProps {
    mindmap: { id: number; title: string; content: string | null };
}

export default function MindmapEditorClient({ mindmap }: MindmapEditorClientProps) {
    const [title, setTitle] = useState(mindmap.title || '未命名导图');
    const [markdown, setMarkdown] = useState(mindmap.content || '');
    const [isGenerating, setIsGenerating] = useState(false);
    const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const [saveStatus, setSaveStatus] = useState('已保存');

    const triggerSave = useCallback((newTitle: string, newContent: string) => {
        setSaveStatus('保存中...');
        if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);

        saveTimeoutRef.current = setTimeout(async () => {
            const res = await updateMindmapAction({
                id: mindmap.id,
                title: newTitle,
                content: newContent
            });
            if (res.success) {
                setSaveStatus('已保存');
            } else {
                setSaveStatus('保存失败');
            }
        }, 800);
    }, [mindmap.id]);

    const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setTitle(val);
        triggerSave(val, markdown);
    };

    const handleMarkdownChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const val = e.target.value;
        setMarkdown(val);
        triggerSave(title, val);
    };

    const handleClear = useCallback(() => {
        if (confirm('确定要清空大纲内容吗？这将被立刻保存。')) {
            setMarkdown('');
            triggerSave(title, '');
        }
    }, [title, triggerSave]);

    const handleAIGenerate = useCallback(async () => {
        if (!markdown.trim()) {
            toast.error('空空如也，请粘贴需要转换的长文本');
            return;
        }

        setIsGenerating(true);
        const loadingToast = toast.loading('AI 正在深度解析文本结构，请稍候...');

        try {
            const res = await generateMindmapAction(markdown);
            if (res.success && res.data) {
                setMarkdown(res.data);
                triggerSave(title, res.data); // 自动保存
                toast.success('结构生成成功！', { id: loadingToast });
            } else {
                toast.error(res.error || '生成失败', { id: loadingToast });
            }
        } catch (error: unknown) {
            toast.error(getErrorMessage(error, '生成过程中发生意外错误'), { id: loadingToast });
        } finally {
            setIsGenerating(false);
        }
    }, [markdown, title, triggerSave]);

    return (
        <div className="flex flex-col h-[calc(100vh-64px)] overflow-hidden font-sans relative">
            {/* 顶栏 */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-card/50">
                <div className="flex items-center gap-3 w-1/2">
                    <input
                        className="text-2xl font-bold bg-transparent border-none outline-none w-full placeholder:text-muted-foreground/40 font-serif"
                        value={title}
                        onChange={handleTitleChange}
                        placeholder="在此输入思维导图标题"
                    />
                </div>
                <div className="text-sm text-muted-foreground px-3 py-1 bg-accent/50 rounded-full">
                    {saveStatus}
                </div>
            </div>

            {/* Split Workspace */}
            <div className="flex flex-1 overflow-hidden">
                {/* Left Panel: Editor */}
                <div className="w-1/3 min-w-[300px] max-w-[600px] border-r border-border flex flex-col bg-background relative">
                    <div className="flex items-center justify-between px-4 py-2 bg-muted/30 border-b border-border">
                        <div className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
                            <AlignLeft className="w-4 h-4" />
                            大纲文档
                        </div>
                        <div className="flex items-center gap-1.5">
                            <Button
                                variant="ghost"
                                size="sm"
                                onClick={handleClear}
                                className="h-7 px-2 text-muted-foreground hover:text-destructive"
                            >
                                <Trash2 className="w-3.5 h-3.5 mr-1" />
                                清空
                            </Button>
                            <Button
                                variant="default"
                                size="sm"
                                onClick={handleAIGenerate}
                                disabled={isGenerating}
                                className="h-7 px-3 bg-indigo-500 hover:bg-indigo-600 text-white shadow-md shadow-indigo-500/20"
                            >
                                <Wand2 className={`w-3.5 h-3.5 mr-1.5 ${isGenerating ? 'animate-spin' : ''}`} />
                                {isGenerating ? 'AI 解析中...' : '提取大纲'}
                            </Button>
                        </div>
                    </div>
                    <textarea
                        value={markdown}
                        onChange={handleMarkdownChange}
                        className="flex-1 w-full p-6 bg-transparent outline-none resize-none font-mono text-[13px] leading-7 text-foreground placeholder:text-muted-foreground/30 scrollbar-thin"
                        placeholder="在此处直接使用 Markdown 符号（#、- 等）排版来生成图谱。&#10;&#10;或者直接粘贴一篇乱糟糟的长文章，点击上面的『提取大纲』召唤 AI 帮你整理！"
                        spellCheck={false}
                    />
                </div>

                {/* Right Panel: Live Viewer */}
                <div className="flex-1 bg-[#fafafa] dark:bg-black/20 p-6 relative overflow-hidden flex flex-col">
                    <SimpleMindMapViewer
                        markdown={markdown}
                        onChange={(m) => handleMarkdownChange({ target: { value: m } } as any)}
                        className="shadow-xl shadow-primary/5 w-full flex-1 rounded-2xl bg-card border-border/50"
                    />
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter, usePathname } from 'next/navigation';
import { Plus, FileText, Trash2, BookOpen, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { createNoteAction, deleteNoteAction, createWelcomeNoteAction, searchNotesAction } from '@/server/actions/note';
import type { NotePreview } from '@/server/actions/note';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';

interface NoteSidebarProps {
    notes: NotePreview[];
}

export function NoteSidebar({ notes: initialNotes }: NoteSidebarProps) {
    const router = useRouter();
    const pathname = usePathname();
    const [isCreating, setIsCreating] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredNotes, setFilteredNotes] = useState(initialNotes);
    const [isSearching, setIsSearching] = useState(false);

    // 同步初始笔记列表
    useEffect(() => {
        if (!searchQuery.trim()) {
            setFilteredNotes(initialNotes);
        }
    }, [initialNotes, searchQuery]);

    // 防抖搜索
    const debouncedSearch = useDebouncedCallback(async (query: string) => {
        if (!query.trim()) {
            setFilteredNotes(initialNotes);
            setIsSearching(false);
            return;
        }

        setIsSearching(true);
        const result = await searchNotesAction(query);
        if (result.success && result.notes) {
            setFilteredNotes(result.notes);
        }
        setIsSearching(false);
    }, 300);

    const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const query = e.target.value;
        setSearchQuery(query);
        debouncedSearch(query);
    };

    const handleCreate = async () => {
        setIsCreating(true);
        try {
            const result = await createNoteAction();
            if (result.success && result.noteId) {
                router.push(`/notes/${result.noteId}`);
                toast.success('新笔记已创建');
            } else {
                toast.error(result.message || '创建失败');
            }
        } catch (error) {
            toast.error('请求失败');
        } finally {
            setIsCreating(false);
        }
    };

    const handleDelete = async (id: number, e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!confirm('确定要删除这条笔记吗？')) return;

        try {
            const result = await deleteNoteAction(id);
            if (result.success) {
                toast.success('删除成功');
                if (pathname === `/notes/${id}`) {
                    router.push('/notes');
                }
                router.refresh();
            } else {
                toast.error(result.message || '删除失败');
            }
        } catch (error) {
            toast.error('删除出错');
        }
    };

    return (
        <div className="w-64 border-r border-border h-full bg-muted/20 flex flex-col">
            <div className="p-4 border-b border-border space-y-3">
                <Button
                    onClick={handleCreate}
                    disabled={isCreating}
                    className="w-full justify-start gap-2"
                    variant="default"
                >
                    <Plus className="w-4 h-4" />
                    {isCreating ? '创建中...' : '新建笔记'}
                </Button>

                {/* 搜索框 */}
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                        placeholder="搜索笔记..."
                        value={searchQuery}
                        onChange={handleSearchChange}
                        className="pl-8 h-9"
                    />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-2 space-y-1">
                {isSearching && (
                    <div className="text-center py-4 text-muted-foreground text-sm">
                        搜索中...
                    </div>
                )}

                {!isSearching && filteredNotes.length === 0 && (
                    <div className="text-center py-8 text-muted-foreground text-sm">
                        {searchQuery ? '未找到匹配的笔记' : '暂无笔记'}
                    </div>
                )}

                {!isSearching && filteredNotes.map(note => {
                    const isActive = pathname === `/notes/${note.id}`;
                    return (
                        <Link
                            key={note.id}
                            href={`/notes/${note.id}`}
                            className={`group flex items-center justify-between p-2 rounded-lg text-sm transition-colors ${isActive
                                ? 'bg-primary/10 text-primary font-medium'
                                : 'hover:bg-muted text-foreground'
                                }`}
                        >
                            <div className="flex items-center gap-2 overflow-hidden">
                                <FileText className="w-4 h-4 flex-shrink-0 opacity-70" />
                                <span className="truncate">{note.title || '无标题'}</span>
                            </div>

                            <button
                                onClick={(e) => handleDelete(note.id, e)}
                                className="opacity-0 group-hover:opacity-100 p-1 hover:bg-destructive/10 hover:text-destructive rounded transition-all"
                                title="删除"
                            >
                                <Trash2 className="w-3 h-3" />
                            </button>
                        </Link>
                    );
                })}
            </div>

            <div className="p-2 border-t border-border">
                <Button
                    variant="ghost"
                    size="sm"
                    className="w-full justify-start gap-2 text-muted-foreground hover:text-foreground"
                    onClick={async () => {
                        const loadingToast = toast.loading('正在创建示例文档...');
                        try {
                            const result = await createWelcomeNoteAction();
                            if (result.success && result.noteId) {
                                router.push(`/notes/${result.noteId}`);
                                toast.success('示例文档已创建', { id: loadingToast });
                            } else {
                                toast.error('创建失败', { id: loadingToast });
                            }
                        } catch (e) {
                            toast.error('请求出错', { id: loadingToast });
                        }
                    }}
                >
                    <BookOpen className="w-4 h-4" />
                    导入使用指南
                </Button>
            </div>
        </div>
    );
}

'use client';

import React, { useCallback, useRef, useState } from 'react';
import dynamic from 'next/dynamic';

const NoteEditor = dynamic(() => import('@/components/editor/NoteEditor'), {
    ssr: false,
    loading: () => <div className="h-64 flex items-center justify-center text-muted-foreground animate-pulse">编辑器加载中...</div>
});
import { TagSelector } from '@/components/notes/TagSelector';
import { updateNoteAction } from '@/server/actions/note';
import { toast } from 'sonner';
import { Network, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { tiptapToMarkdown } from '@/lib/utils/tiptapToMarkdown';

const SimpleMindMapViewer = dynamic(
    () => import('@/components/ocr/SimpleMindMapViewer').then(mod => mod.SimpleMindMapViewer),
    { ssr: false, loading: () => <div className="h-full w-full flex items-center justify-center text-muted-foreground animate-pulse">引擎装载中...</div> }
);

interface NotePageClientProps {
    note: {
        id: number;
        title: string;
        content: string | null;
    };
}

export default function NotePageClient({ note }: NotePageClientProps) {
    const [title, setTitle] = useState(note.title);
    const [viewMode, setViewMode] = useState<'editor' | 'mindmap'>('editor');
    const [currentContent, setCurrentContent] = useState(note.content || '');
    
    // Use 'any' for timeout to avoid NodeJS vs Window type issues in frontend
    const saveTimeoutRef = useRef<any>(null);

    const handleSave = useCallback((newContent?: string, newTitle?: string) => {
        if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);

        saveTimeoutRef.current = setTimeout(async () => {
            const result = await updateNoteAction({
                id: note.id,
                title: newTitle,
                content: newContent
            });
            if (newContent !== undefined) {
                setCurrentContent(newContent);
            }
            if (!result.success) {
                toast.error('保存失败');
            }
        }, 1000);
    }, [note.id]);

    return (
        <div className="flex flex-col h-full max-w-4xl mx-auto w-full">
            <div className="pt-8 px-12 pb-2">
                <input
                    value={title}
                    onChange={(e) => {
                        const val = e.target.value;
                        setTitle(val);
                        handleSave(undefined, val);
                    }}
                    className="text-4xl font-bold bg-transparent border-none outline-none w-full placeholder:text-muted-foreground/40"
                    placeholder="无标题"
                />
                {/* 标签选择器与视图切换 */}
                <div className="mt-3 flex items-center justify-between">
                    <TagSelector noteId={note.id} />
                    
                    <div className="flex bg-muted/50 p-1 rounded-lg">
                        <Button
                            variant={viewMode === 'editor' ? 'secondary' : 'ghost'}
                            size="sm"
                            className="h-8 gap-1.5 px-3"
                            onClick={() => setViewMode('editor')}
                        >
                            <FileText className="w-3.5 h-3.5" />
                            文档
                        </Button>
                        <Button
                            variant={viewMode === 'mindmap' ? 'secondary' : 'ghost'}
                            size="sm"
                            className="h-8 gap-1.5 px-3"
                            onClick={() => setViewMode('mindmap')}
                        >
                            <Network className="w-3.5 h-3.5 text-primary" />
                            思维导图
                        </Button>
                    </div>
                </div>
            </div>
            <div className={`flex-1 px-12 pb-20 scrollbar-thin ${viewMode === 'editor' ? 'overflow-y-auto' : 'overflow-hidden pt-4'}`}>
                {viewMode === 'editor' ? (
                    <NoteEditor
                        key={note.id}
                        initialContent={note.content}
                        onChange={(content) => handleSave(content)}
                    />
                ) : (
                    <SimpleMindMapViewer 
                        markdown={tiptapToMarkdown(currentContent)} 
                        onChange={(md) => {
                            // 在笔记中反向映射通常需要转换回 JSON Content 或者原样更新 currentContent
                            setCurrentContent(md);
                            handleSave(md);
                        }}
                        className="h-full max-h-none border-none shadow-none" 
                    />
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Upload, FileText, Image as ImageIcon, Loader2, Copy, Check, Download, X, ScanLine, ChevronDown, Network } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { performOcrAction, getOcrModelsAction } from '@/server/actions/ocr';
import { generateMindmapAction } from '@/server/actions/mindmap';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import dynamic from 'next/dynamic';

const SimpleMindMapViewer = dynamic(
    () => import('@/components/ocr/SimpleMindMapViewer').then(mod => mod.SimpleMindMapViewer),
    { ssr: false, loading: () => <div className="h-full w-full flex items-center justify-center text-muted-foreground animate-pulse">引擎装载中...</div> }
);
import type { OcrModel, OcrModelInfo } from '@/server/actions/ocr';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

// 支持的文件类型
const ACCEPTED_EXTENSIONS = '.pdf,.png,.jpg,.jpeg,.webp,.bmp';
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

export default function OcrPage() {
    const [isDragging, setIsDragging] = useState(false);
    const [file, setFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [result, setResult] = useState<string | null>(null);
    const [copied, setCopied] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // 模型选择
    const [models, setModels] = useState<OcrModelInfo[]>([]);
    const [selectedModel, setSelectedModel] = useState<OcrModel>('paddle-ocr');
    const [showModelMenu, setShowModelMenu] = useState(false);
    const modelMenuRef = useRef<HTMLDivElement>(null);

    // 思维导图状态
    const [mindmapMarkdown, setMindmapMarkdown] = useState<string | null>(null);
    const [isGeneratingMindmap, setIsGeneratingMindmap] = useState(false);
    const [showMindmapDialog, setShowMindmapDialog] = useState(false);

    // 加载模型列表
    useEffect(() => {
        getOcrModelsAction().then(setModels);
    }, []);

    // 点击外部关闭模型菜单
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (modelMenuRef.current && !modelMenuRef.current.contains(e.target as Node)) {
                setShowModelMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const currentModel = models.find(m => m.id === selectedModel);

    // 检查当前文件是否被选中的模型支持
    const isFileSupported = useCallback((f: File | null, model: OcrModel) => {
        if (!f) return true;
        const m = models.find(x => x.id === model);
        if (!m) return true;
        return m.supportedTypes.includes(f.type);
    }, [models]);

    // 处理文件选择
    const handleFile = useCallback((selectedFile: File) => {
        const allTypes = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/bmp'];
        if (!allTypes.includes(selectedFile.type)) {
            toast.error('不支持的文件类型，请上传 PDF 或图片文件');
            return;
        }
        if (selectedFile.size > MAX_FILE_SIZE) {
            toast.error('文件过大，请上传 10MB 以内的文件');
            return;
        }

        setFile(selectedFile);
        setResult(null);

        // 图片文件生成预览
        if (selectedFile.type.startsWith('image/')) {
            const url = URL.createObjectURL(selectedFile);
            setPreviewUrl(url);
        } else {
            setPreviewUrl(null);
        }

        // 如果当前模型不支持此文件类型，自动切换到 PaddleOCR
        if (!isFileSupported(selectedFile, selectedModel)) {
            setSelectedModel('paddle-ocr');
            toast.info('已自动切换为 PaddleOCR（当前模型不支持此文件类型）');
        }
    }, [selectedModel, isFileSupported]);

    // 拖拽事件
    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    }, []);

    const handleDragLeave = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    }, []);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const droppedFile = e.dataTransfer.files[0];
        if (droppedFile) handleFile(droppedFile);
    }, [handleFile]);

    // 点击上传
    const handleClick = useCallback(() => {
        fileInputRef.current?.click();
    }, []);

    const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) handleFile(selectedFile);
    }, [handleFile]);

    // 开始 OCR 识别
    const handleRecognize = useCallback(async () => {
        if (!file) return;

        setIsProcessing(true);
        setResult(null);

        try {
            // 将文件转为 Base64
            const buffer = await file.arrayBuffer();
            const base64 = btoa(
                new Uint8Array(buffer).reduce((data, byte) => data + String.fromCharCode(byte), '')
            );

            const response = await performOcrAction(base64, file.name, file.type, selectedModel);

            if (response.success && response.text) {
                setResult(response.text);
                toast.success('识别完成');
            } else {
                toast.error(response.error || '识别失败');
            }
        } catch (error: unknown) {
            toast.error(error instanceof Error ? error.message : '识别过程中发生错误');
        } finally {
            setIsProcessing(false);
        }
    }, [file, selectedModel]);

    // 复制结果
    const handleCopy = useCallback(async () => {
        if (!result) return;
        await navigator.clipboard.writeText(result);
        setCopied(true);
        toast.success('已复制到剪贴板');
        setTimeout(() => setCopied(false), 2000);
    }, [result]);

    // 生成思维导图
    const handleGenerateMindmap = useCallback(async () => {
        if (!result) return;
        
        setIsGeneratingMindmap(true);
        try {
            const res = await generateMindmapAction(result);
            if (res.success && res.data) {
                setMindmapMarkdown(res.data);
                setShowMindmapDialog(true);
            } else {
                toast.error(res.error || '生成思维导图失败');
            }
        } catch (error: unknown) {
            toast.error(error instanceof Error ? error.message : '生成过程中发生错误');
        } finally {
            setIsGeneratingMindmap(false);
        }
    }, [result]);

    // 下载为 Markdown
    const handleDownload = useCallback(() => {
        if (!result) return;
        const blob = new Blob([result], { type: 'text/markdown;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        const baseName = file?.name.replace(/\.[^/.]+$/, '') || 'ocr_result';
        a.href = url;
        a.download = `${baseName}.md`;
        a.click();
        URL.revokeObjectURL(url);
    }, [result, file]);

    // 清除文件
    const handleClear = useCallback(() => {
        setFile(null);
        setPreviewUrl(null);
        setResult(null);
        if (fileInputRef.current) fileInputRef.current.value = '';
    }, []);

    // 切换模型
    const handleSelectModel = useCallback((modelId: OcrModel) => {
        // 检查当前文件是否兼容
        if (file && !isFileSupported(file, modelId)) {
            toast.warning('当前文件类型不被该模型支持，请更换文件或选择其他模型');
            return;
        }
        setSelectedModel(modelId);
        setShowModelMenu(false);
    }, [file, isFileSupported]);

    return (
        <div className="min-h-[calc(100vh-64px)] bg-background p-6 md:p-12 font-sans">
            <div className="max-w-4xl mx-auto space-y-8">

                {/* 页面标题 */}
                <div className="flex items-start justify-between">
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
                            <ScanLine className="w-8 h-8 text-primary" />
                            文字识别 (OCR)
                        </h1>
                        <p className="text-muted-foreground mt-2">
                            上传图片或 PDF 文件，智能识别文字内容并转为 Markdown 格式。
                        </p>
                    </div>

                    {/* 模型选择器 */}
                    <div className="relative" ref={modelMenuRef}>
                        <Button
                            variant="outline"
                            onClick={() => setShowModelMenu(!showModelMenu)}
                            className="h-10 px-4 gap-2 rounded-xl"
                        >
                            <div className="w-2 h-2 rounded-full bg-primary" />
                            <span className="text-sm font-medium">{currentModel?.name || '选择模型'}</span>
                            <ChevronDown className={cn(
                                "w-4 h-4 text-muted-foreground transition-transform",
                                showModelMenu && "rotate-180"
                            )} />
                        </Button>

                        {showModelMenu && (
                            <div className="absolute right-0 top-full mt-2 w-80 bg-popover border border-border rounded-xl shadow-lg z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                                {models.map((m) => {
                                    const supported = isFileSupported(file, m.id);
                                    return (
                                        <button
                                            key={m.id}
                                            onClick={() => handleSelectModel(m.id)}
                                            disabled={!supported}
                                            className={cn(
                                                "w-full text-left px-4 py-3 transition-colors border-b border-border last:border-b-0",
                                                selectedModel === m.id
                                                    ? "bg-primary/10"
                                                    : supported
                                                        ? "hover:bg-accent"
                                                        : "opacity-50 cursor-not-allowed"
                                            )}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className={cn(
                                                    "w-3 h-3 rounded-full border-2 flex-shrink-0",
                                                    selectedModel === m.id
                                                        ? "border-primary bg-primary"
                                                        : "border-muted-foreground"
                                                )} />
                                                <div>
                                                    <div className="font-medium text-sm text-foreground">
                                                        {m.name}
                                                        {!supported && (
                                                            <span className="ml-2 text-xs text-destructive">
                                                                (不支持当前文件类型)
                                                            </span>
                                                        )}
                                                    </div>
                                                    <div className="text-xs text-muted-foreground mt-0.5">
                                                        {m.description}
                                                    </div>
                                                </div>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </div>

                {/* 上传区域 */}
                {!file ? (
                    <div
                        onClick={handleClick}
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                        className={cn(
                            "relative border-2 border-dashed rounded-2xl p-16 text-center cursor-pointer transition-all duration-300",
                            "hover:border-primary/50 hover:bg-primary/5",
                            isDragging
                                ? "border-primary bg-primary/10 scale-[1.02]"
                                : "border-border bg-muted/20"
                        )}
                    >
                        <input
                            ref={fileInputRef}
                            type="file"
                            accept={ACCEPTED_EXTENSIONS}
                            onChange={handleInputChange}
                            className="hidden"
                        />
                        <div className="flex flex-col items-center gap-4">
                            <div className={cn(
                                "w-16 h-16 rounded-2xl flex items-center justify-center transition-colors",
                                isDragging ? "bg-primary/20 text-primary" : "bg-muted text-muted-foreground"
                            )}>
                                <Upload className="w-8 h-8" />
                            </div>
                            <div>
                                <p className="text-lg font-medium text-foreground">
                                    拖拽文件到这里，或点击上传
                                </p>
                                <p className="text-sm text-muted-foreground mt-1">
                                    支持 PDF、PNG、JPG、WebP、BMP，最大 10MB
                                </p>
                            </div>
                            <div className="flex gap-3 mt-2">
                                <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-muted text-xs text-muted-foreground">
                                    <FileText className="w-3.5 h-3.5" /> PDF
                                </div>
                                <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-muted text-xs text-muted-foreground">
                                    <ImageIcon className="w-3.5 h-3.5" /> 图片
                                </div>
                            </div>
                        </div>
                    </div>
                ) : (
                    /* 文件已选择：预览 + 操作 */
                    <Card className="border border-border rounded-2xl overflow-hidden">
                        <CardContent className="p-6">
                            <div className="flex items-center justify-between mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                                        {file.type === 'application/pdf'
                                            ? <FileText className="w-5 h-5" />
                                            : <ImageIcon className="w-5 h-5" />
                                        }
                                    </div>
                                    <div>
                                        <p className="font-medium text-sm text-foreground truncate max-w-[300px]">
                                            {file.name}
                                        </p>
                                        <p className="text-xs text-muted-foreground">
                                            {(file.size / 1024).toFixed(1)} KB · 使用 {currentModel?.name || selectedModel}
                                        </p>
                                    </div>
                                </div>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    onClick={handleClear}
                                    className="text-muted-foreground hover:text-destructive"
                                >
                                    <X className="w-4 h-4" />
                                </Button>
                            </div>

                            {/* 图片预览 */}
                            {previewUrl && (
                                <div className="mb-4 rounded-xl overflow-hidden border border-border bg-muted/30 max-h-[400px] flex items-center justify-center">
                                    <img
                                        src={previewUrl}
                                        alt="预览"
                                        className="max-h-[400px] object-contain"
                                    />
                                </div>
                            )}

                            {/* 识别按钮 */}
                            <Button
                                onClick={handleRecognize}
                                disabled={isProcessing}
                                className="w-full h-12 text-base rounded-xl"
                            >
                                {isProcessing ? (
                                    <>
                                        <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                                        正在识别中，请稍候...
                                    </>
                                ) : (
                                    <>
                                        <ScanLine className="w-5 h-5 mr-2" />
                                        开始识别
                                    </>
                                )}
                            </Button>
                        </CardContent>
                    </Card>
                )}

                {/* 识别结果 */}
                {result && (
                    <Card className="border border-border rounded-2xl overflow-hidden">
                        <CardContent className="p-6">
                            <div className="flex items-center justify-between mb-4">
                                <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
                                    <FileText className="w-5 h-5 text-primary" />
                                    识别结果
                                </h2>
                                <div className="flex gap-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={handleGenerateMindmap}
                                        disabled={isGeneratingMindmap}
                                        className="h-8"
                                    >
                                        {isGeneratingMindmap ? <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" /> : <Network className="w-3.5 h-3.5 mr-1.5 text-primary" />}
                                        <span className={isGeneratingMindmap ? "" : "text-primary font-medium"}>
                                            转为导图
                                        </span>
                                    </Button>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={handleCopy}
                                        className="h-8"
                                    >
                                        {copied
                                            ? <><Check className="w-3.5 h-3.5 mr-1.5" /> 已复制</>
                                            : <><Copy className="w-3.5 h-3.5 mr-1.5" /> 复制</>
                                        }
                                    </Button>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={handleDownload}
                                        className="h-8"
                                    >
                                        <Download className="w-3.5 h-3.5 mr-1.5" /> 下载 .md
                                    </Button>
                                </div>
                            </div>
                            <div className="bg-muted/30 rounded-xl p-4 border border-border max-h-[600px] overflow-y-auto">
                                <pre className="text-sm text-foreground whitespace-pre-wrap break-words font-mono leading-relaxed">
                                    {result}
                                </pre>
                            </div>
                            <p className="text-xs text-muted-foreground mt-3 text-right">
                                共 {result.length} 字符 · {currentModel?.name}
                            </p>
                        </CardContent>
                    </Card>
                )}

                {/* 思维导图弹窗 */}
                <Dialog open={showMindmapDialog} onOpenChange={setShowMindmapDialog}>
                    <DialogContent className="max-w-[90vw] w-[1200px] h-[85vh] flex flex-col p-6">
                        <DialogHeader>
                            <DialogTitle className="flex items-center gap-2 text-xl">
                                <Network className="w-5 h-5 text-primary" />
                                结构化思维导图
                            </DialogTitle>
                        </DialogHeader>
                        <div className="flex-1 mt-4 overflow-hidden rounded-xl border border-border bg-background">
                            {mindmapMarkdown && (
                                <SimpleMindMapViewer 
                                    markdown={mindmapMarkdown} 
                                    onChange={setMindmapMarkdown}
                                    className="w-full h-full"
                                />
                            )}
                        </div>
                    </DialogContent>
                </Dialog>
            </div>
        </div>
    );
}

"use client";

import React, { Suspense } from 'react';
import { AnimatePresence } from 'framer-motion';
import { ErrorBoundary } from '@/components/ErrorBoundary';
import { AlertTriangle, Loader2 } from 'lucide-react';

// Imported Components
import { HeaderProgressBar } from '@/components/practice/HeaderProgressBar';
import { ExitConfirmModal } from '@/components/practice/ExitConfirmModal';
import { FinishedCard } from '@/components/practice/FinishedCard';
import { PracticeCard } from '@/components/practice/PracticeCard';
import { ReviewCard } from '@/components/practice/ReviewCard';

// Controller Hook
import { usePracticeController } from './hooks/use-practice-controller';

function PracticeContent({ enableIntelligentReview }: { enableIntelligentReview: boolean }) {
    const {
        state,
        isLoadingAI,
        showExitConfirm,
        selectedOptions,
        timerConfig,
        actions
    } = usePracticeController(enableIntelligentReview);

    if (state.status === 'loading') return (
        <div className="p-8 text-center text-muted-foreground flex flex-col items-center gap-4">
            <Loader2 className="animate-spin h-8 w-8 text-primary" />
            正在初始化练习会话...
        </div>
    );

    const currentQuestion = state.sessionQueue[state.currentIndex];

    return (
        <ErrorBoundary>
            <div className="min-h-[calc(100vh-64px)] bg-background pb-20">
                <HeaderProgressBar
                    status={state.status}
                    currentIndex={state.currentIndex}
                    totalCount={state.sessionQueue.length}
                    onExit={actions.handleExit}
                    timerEnabled={timerConfig.enabled}
                    timerMode={timerConfig.mode}
                    timerSeconds={timerConfig.secondsPerQuestion}
                    currentQuestionId={state.sessionQueue[state.currentIndex]?.id}
                />

                <div className="p-4 md:p-8 max-w-2xl mx-auto">
                    {enableIntelligentReview && state.reviewQueue.length > 0 && state.status === 'practicing' && (
                        <div className="mb-6 p-3 bg-amber-500/10 border border-amber-500/20 rounded-lg flex items-center gap-3 text-amber-600 dark:text-amber-400 text-sm">
                            <AlertTriangle className="h-4 w-4 shrink-0" />
                            <span>您有 {state.reviewQueue.length} 个知识点待复盘，将在第 {state.reviewTriggeredAt} 题或结束时自动触发。</span>
                        </div>
                    )}

                    <AnimatePresence mode="wait">
                        {state.status === 'practicing' && currentQuestion && (
                            <PracticeCard
                                question={currentQuestion}
                                isMulti={currentQuestion.type === 'multi'}
                                selectedOptions={selectedOptions}
                                onOptionClick={actions.handleOptionClick}
                                onSubmitMulti={actions.submitMultiChoice}
                            />
                        )}

                        {enableIntelligentReview && state.status === 'reviewing' && (
                            <ReviewCard
                                currentItem={state.reviewQueue[state.currentReviewIndex] as any}
                                sessionQueue={state.sessionQueue}
                                isLoadingAI={isLoadingAI}
                                onReviewStep={actions.handleReviewStep}
                            />
                        )}

                        {state.status === 'finished' && (
                            <FinishedCard
                                sessionId={state.sessionId}
                                onDashboardClick={() => window.location.href = '/'}
                            />
                        )}
                    </AnimatePresence>
                </div>

                <ExitConfirmModal
                    isOpen={showExitConfirm}
                    onCancel={actions.cancelExit}
                    onConfirm={actions.confirmExit}
                />
            </div>
        </ErrorBoundary>
    );
}

export default function PracticeClient({ initialEnableIntelligentReview }: { initialEnableIntelligentReview: boolean }) {
    return (
        <Suspense fallback={
            <div className="p-8 text-center text-muted-foreground flex flex-col items-center gap-4">
                <Loader2 className="animate-spin h-8 w-8 text-primary" />
                正在加载练习环境...
            </div>
        }>
            <PracticeContent enableIntelligentReview={initialEnableIntelligentReview} />
        </Suspense>
    );
}

