"use client";

import { useEffect, useRef, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { toast } from 'sonner';
import { usePracticeEngine } from '../../../hooks/use-practice-engine';
import { useReviewGeneration } from './use-review-generation';
import { useKeyboardShortcuts } from './use-keyboard-shortcuts';
import { getPracticeSessionAction, getPracticeSessionByConfigAction, submitAnswerAction, getSessionByIdAction } from '@/server/actions/practice';
import { moveToObservationZoneAction } from '@/server/actions/zone';
import { PRACTICE_MODE_LABELS, PracticeMode } from '@/lib/practice/practice-types';

export function usePracticeController(enableIntelligentReview: boolean = false) {
    const router = useRouter();
    const searchParams = useSearchParams();
    const { state, dispatch } = usePracticeEngine(enableIntelligentReview);

    // Extracted AI Generation Logic
    const { isLoadingAI } = useReviewGeneration(state as any, dispatch);

    const isHandlingRef = useRef(false);
    const [showExitConfirm, setShowExitConfirm] = useState(false);
    const [selectedOptions, setSelectedOptions] = useState<string[]>([]);
    const [practiceMode, setPracticeMode] = useState<PracticeMode>('smart');
    // 计时器配置
    const [timerEnabled, setTimerEnabled] = useState(false);
    const [timerMode, setTimerMode] = useState<'count_up' | 'count_down'>('count_up');

    // Init Session
    useEffect(() => {
        const init = async () => {
            try {
                // 优先检查是否有 sessionId 参数（用于错题本等已创建会话的场景）
                const sessionIdParam = searchParams.get('sessionId');
                if (sessionIdParam) {
                    const session = await getSessionByIdAction(sessionIdParam);
                    if (session && session.questions.length > 0) {
                        setPracticeMode((session.practiceMode as PracticeMode) || 'review');
                        dispatch({
                            type: 'INIT_SESSION',
                            payload: {
                                questions: session.questions,
                                sessionId: session.sessionId,
                                startIndex: session.completedCount
                            }
                        });

                        if (session.completedCount > 0) {
                            toast.info(`已恢复练习进度 (${session.completedCount}/${session.questions.length})`, {
                                duration: 3000,
                                icon: '🔄'
                            });
                        } else {
                            toast.success(`错题强化模式已启动，共 ${session.questions.length} 题`, {
                                duration: 3000,
                                icon: '📝'
                            });
                        }
                        return; // 提前退出，不走常规创建流程
                    } else {
                        toast.error('会话已过期或不存在');
                        router.push('/wrong-book');
                        return;
                    }
                }

                // 检查是否有配置参数
                const mode = searchParams.get('mode') as PracticeMode | null;
                const limit = searchParams.get('limit');
                const forceNew = searchParams.get('new') === 'true';
                const noReview = searchParams.get('noReview') === '1';
                const enableTimer = searchParams.get('timer') === '1';

                let result;

                if (mode && limit) {
                    // 使用配置化选题
                    const config = {
                        mode,
                        limit: parseInt(limit) || 25,
                        types: searchParams.get('types')?.split(',') as ('single' | 'multi' | 'truefalse')[] | undefined,
                        tags: searchParams.get('tags')?.split(',').filter(Boolean),
                        dimensions: searchParams.get('dimensions')?.split(',') as import('@/types').Dimension[] | undefined,
                        enableReview: !noReview,
                        enableTimer
                    };

                    result = await getPracticeSessionByConfigAction(config);
                    setPracticeMode(mode);

                    // 设置计时器
                    if (enableTimer) {
                        setTimerEnabled(true);
                        // 考试模式使用正计时（记录总耗时），其他模式也用正计时
                        setTimerMode('count_up');
                    }

                    // 显示模式提示
                    const modeLabel = PRACTICE_MODE_LABELS[mode] || mode;
                    toast.success(`${modeLabel}模式已启动，共 ${result.questions.length} 题`, {
                        duration: 3000,
                        icon: '🎯'
                    });
                } else {
                    // 传统选题（兼容旧入口）
                    result = await getPracticeSessionAction(forceNew);
                }

                const { questions, sessionId, resumed, completedCount } = result as any;

                if (questions.length > 0) {
                    dispatch({
                        type: 'INIT_SESSION',
                        payload: {
                            questions,
                            sessionId,
                            startIndex: resumed ? completedCount : 0
                        }
                    });

                    if (resumed) {
                        toast.info(`欢迎回来！已为您恢复之前的练习进度 (${completedCount}/${questions.length})`, {
                            duration: 4000,
                            icon: '🔄'
                        });
                    }
                } else {
                    toast.error("暂无题目可练，请先上传题库或调整设置");
                    setTimeout(() => router.push('/practice/setup'), 2000);
                }
            } catch (error) {
                console.error("Failed to init session:", error);
                toast.error("初始化练习失败，请刷新重试");
            }
        };
        init();
    }, [dispatch, router, searchParams]);

    // Exit confirmation logic
    useEffect(() => {
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (state.status !== 'finished') {
                e.preventDefault();
                e.returnValue = '';
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [state.status]);

    const handleExit = () => {
        if (state.status === 'finished') {
            router.push('/');
        } else {
            setShowExitConfirm(true);
        }
    };

    const confirmExit = () => {
        router.push('/');
    };

    const cancelExit = () => {
        setShowExitConfirm(false);
    };

    // Answer Handling
    const submitAnswer = async (answer: string) => {
        if (isHandlingRef.current) return;
        isHandlingRef.current = true;

        try {
            const currentQuestion = state.sessionQueue[state.currentIndex];
            // Basic check
            // 增强的比对逻辑：支持标号(A/B/C)与文本的双向匹配
            const checkCorrect = (userAns: string, targetAns: string, options: string[]) => {
                if (userAns === targetAns) return true;

                // 如果用户提交的是标号 (A, B, C...)
                if (userAns.length === 1 && userAns >= 'A' && userAns <= 'Z') {
                    const idx = userAns.charCodeAt(0) - 65;
                    if (options[idx] === targetAns) return true;
                }

                // 如果正确答案是标号 (A, B, C...)
                if (targetAns.length === 1 && targetAns >= 'A' && targetAns <= 'Z') {
                    const idx = targetAns.charCodeAt(0) - 65;
                    if (options[idx] === userAns) return true;
                }

                return false;
            };

            let isCorrect = false;
            if (currentQuestion.type === 'multi') {
                const parseAnswer = (val: string): string[] => {
                    try { return JSON.parse(val); } catch { return val.split(',').map(s => s.trim()); }
                };
                const correctArr = parseAnswer(currentQuestion.answer).sort();
                const answerArr = parseAnswer(answer).sort();

                if (correctArr.length === answerArr.length) {
                    isCorrect = answerArr.every((v, i) => checkCorrect(v, correctArr[i], currentQuestion.options));
                }
            } else {
                isCorrect = checkCorrect(answer, currentQuestion.answer, currentQuestion.options);
            }

            const duration = Math.floor((Date.now() - (state.startTime || Date.now())) / 1000);

            dispatch({
                type: 'ANSWER_QUESTION',
                payload: {
                    questionId: currentQuestion.id,
                    answer,
                    isCorrect,
                    duration
                }
            });

            // Async save
            submitAnswerAction(currentQuestion.id, answer, isCorrect, duration, state.sessionId || undefined).catch(console.error);
        } catch (e) {
            console.error("Submit answer error:", e);
        } finally {
            setTimeout(() => {
                isHandlingRef.current = false;
            }, 500);
        }
    };

    const handleOptionClick = (option: string, mode: 'single' | 'multi') => {
        if (mode === 'single') {
            submitAnswer(option);
        } else {
            setSelectedOptions(prev => {
                if (prev.includes(option)) return prev.filter(o => o !== option);
                return [...prev, option];
            });
        }
    };

    const submitMultiChoice = () => {
        if (selectedOptions.length === 0) {
            toast.warning("请至少选择一个选项");
            return;
        }
        const sorted = [...selectedOptions].sort();
        submitAnswer(JSON.stringify(sorted));
        setSelectedOptions([]);
    };

    // Review Handling
    const handleReviewStep = async (success: boolean) => {
        const currentItem = state.reviewQueue[state.currentReviewIndex];

        if (success) {
            if (currentItem.currentStep === 'regression' && currentItem.regressionSubIndex === 2) {
                toast.success("复盘通过，该知识点已攻克！");
            } else if (currentItem.currentStep !== 'regression') {
                toast.success("回答正确，进入下一阶段");
            }
            dispatch({ type: 'COMPLETE_REVIEW_STEP', payload: { success: true } });
        } else {
            if (currentItem.failedAttempts >= 2) {
                toast.error("多次尝试失败，该知识点已列入【长期观察区】，请课后查阅教材。", { duration: 5000 });
                if (currentItem.tags.length > 0) {
                    moveToObservationZoneAction(currentItem.tags[0], "复盘熔断：连续 3 次尝试失败").catch(console.error);
                }
            } else {
                toast.error("复盘未通过，请仔细研读解析后重试。");
            }
            dispatch({ type: 'COMPLETE_REVIEW_STEP', payload: { success: false } });
        }
    };

    // Keyboard Shortcuts
    useKeyboardShortcuts(state as any, submitAnswer);

    return {
        state,
        isLoadingAI,
        showExitConfirm,
        selectedOptions,
        practiceMode,
        // 计时器配置
        timerConfig: {
            enabled: timerEnabled,
            mode: timerMode,
            // 每题倒计时秒数（如果使用倒计时模式）
            secondsPerQuestion: 90,
        },
        actions: {
            handleExit,
            confirmExit,
            cancelExit,
            handleOptionClick,
            submitMultiChoice,
            handleReviewStep,
            dispatch
        }
    };
}

import { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';
import { generateCorrectionQuizAction, generateRegressionChallengeAction } from '@/server/actions/ai';

// Define minimal types needed from state
interface ReviewItem {
    originalQuestionId: number;
    originalQuestionContent: string;
    wrongAnswer: string;
    currentStep: 'study' | 'quiz' | 'regression';
    quiz?: any;
    regression?: any;
    tags: string[];
}

interface SessionQuestion {
    id: number;
    answer: string;
    content: string;
}

interface PracticeState {
    status: 'loading' | 'practicing' | 'reviewing' | 'finished';
    currentReviewIndex: number;
    reviewQueue: ReviewItem[];
    sessionQueue: SessionQuestion[];
}

export function useReviewGeneration(state: PracticeState, dispatch: React.Dispatch<any>) {
    const [isLoadingAI, setIsLoadingAI] = useState(false);
    const generationTracker = useRef<Set<string>>(new Set());

    useEffect(() => {
        const checkAndGenerate = async () => {
            if (state.status !== 'reviewing') return;
            const currentItem = state.reviewQueue[state.currentReviewIndex];
            if (!currentItem) return;

            // 1. Generate Correction Quiz
            const quizKey = `quiz-${currentItem.originalQuestionId}`;
            const needsQuiz = !currentItem.quiz;
            const shouldBlockForQuiz = currentItem.currentStep === 'quiz' && needsQuiz;

            // Trigger Generation if needed and not started
            if (needsQuiz && !generationTracker.current.has(quizKey)) {
                console.log("Triggering background generation for Quiz", quizKey);
                generationTracker.current.add(quizKey);

                // If we are already in quiz step, show loading. If in study, don't block.
                if (shouldBlockForQuiz) setIsLoadingAI(true);

                generateCorrectionQuizAction(
                    currentItem.originalQuestionContent,
                    currentItem.wrongAnswer,
                    state.sessionQueue.find(q => q.id === currentItem.originalQuestionId)?.answer || ""
                ).then(data => {
                    dispatch({
                        type: 'LOAD_REVIEW_DATA',
                        payload: { index: state.currentReviewIndex, data: { quiz: data } }
                    });
                }).catch(e => {
                    console.error("Quiz gen failed", e);
                    toast.error("AI 生成失败，将使用降级模式");
                }).finally(() => {
                    setIsLoadingAI(false);
                });
            } else if (shouldBlockForQuiz && !isLoadingAI) {
                // If we are in quiz step, missing data, but tracker passed (maybe racing?), force loading
                setIsLoadingAI(true);
            }

            // 2. Generate Regression Challenge
            const regressionKey = `regression-${currentItem.originalQuestionId}`;
            const needsRegression = !currentItem.regression;
            const shouldBlockForRegression = currentItem.currentStep === 'regression' && needsRegression;

            if (needsRegression && !generationTracker.current.has(regressionKey)) {
                // Ideally trigger when leaving study or entering quiz
                if (currentItem.currentStep === 'quiz' || currentItem.currentStep === 'regression') {
                    console.log("Triggering background generation for Regression", regressionKey);
                    generationTracker.current.add(regressionKey);

                    if (shouldBlockForRegression) setIsLoadingAI(true);

                    const q = state.sessionQueue.find(q => q.id === currentItem.originalQuestionId);
                    if (q) {
                        generateRegressionChallengeAction(q.content, currentItem.tags)
                            .then(data => {
                                dispatch({
                                    type: 'LOAD_REVIEW_DATA',
                                    payload: { index: state.currentReviewIndex, data: { regression: data } }
                                });
                            }).catch(e => {
                                console.error("Regression gen failed", e);
                            }).finally(() => {
                                setIsLoadingAI(false);
                            });
                    }
                }
            } else if (shouldBlockForRegression && !isLoadingAI) {
                setIsLoadingAI(true);
            }

            // Ensure loading is off if we have what we need for current step
            if (
                (currentItem.currentStep === 'study') || // Never block study
                (currentItem.currentStep === 'quiz' && currentItem.quiz) ||
                (currentItem.currentStep === 'regression' && currentItem.regression)
            ) {
                if (isLoadingAI) setIsLoadingAI(false);
            }
        };

        checkAndGenerate();
    }, [state.status, state.currentReviewIndex, state.reviewQueue, state.sessionQueue, isLoadingAI]); // Intentionally kept isLoadingAI to check re-entry

    return { isLoadingAI };
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    Brain,
    RotateCcw,
    Target,
    FileCheck,
    Shuffle,
    ArrowRight,
    ChevronLeft,
    Settings2,
    Loader2,
    Tag,
    BookOpen,
    CheckCircle2
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import {
    PracticeMode,
    PracticeConfig,
    PRACTICE_MODE_LABELS,
    PRACTICE_MODE_DESCRIPTIONS,
    PRESET_CONFIGS,
    DEFAULT_PRACTICE_CONFIG,
    QUESTION_LIMIT_OPTIONS,
    DIMENSION_LABELS,
    Dimension
} from '@/lib/practice/practice-types';
import { getAvailableTagsAction } from '@/server/actions/practice';
import { KeypointTree } from '@/components/practice/KeypointTree';

// 模式图标组件
const ModeIcons: Record<PracticeMode, React.ReactNode> = {
    smart: <Brain className="w-6 h-6" />,
    review: <RotateCcw className="w-6 h-6" />,
    focus: <Target className="w-6 h-6" />,
    exam: <FileCheck className="w-6 h-6" />,
    random: <Shuffle className="w-6 h-6" />
};

// 模式颜色
const ModeColors: Record<PracticeMode, string> = {
    smart: 'from-blue-500 to-indigo-600',
    review: 'from-amber-500 to-orange-600',
    focus: 'from-green-500 to-emerald-600',
    exam: 'from-purple-500 to-violet-600',
    random: 'from-pink-500 to-rose-600'
};

export default function PracticeSetupPage() {
    const router = useRouter();
    const [config, setConfig] = useState<PracticeConfig>(DEFAULT_PRACTICE_CONFIG);
    const [availableTags, setAvailableTags] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAdvanced, setShowAdvanced] = useState(false);

    // 加载可用标签
    useEffect(() => {
        const loadTags = async () => {
            try {
                const tags = await getAvailableTagsAction();
                setAvailableTags(tags);
            } catch (error) {
                console.error('加载标签失败', error);
            } finally {
                setLoading(false);
            }
        };
        loadTags();
    }, []);

    // 切换模式时应用预设配置
    const handleModeChange = (mode: PracticeMode) => {
        const preset = PRESET_CONFIGS[mode];
        setConfig({
            ...config,
            mode,
            limit: preset.limit ?? config.limit,
            enableReview: preset.enableReview ?? config.enableReview,
            enableTimer: preset.enableTimer ?? config.enableTimer
        });
    };

    // 切换知识点选择
    const toggleTag = (tag: string) => {
        setConfig(prev => ({
            ...prev,
            tags: prev.tags?.includes(tag)
                ? prev.tags.filter(t => t !== tag)
                : [...(prev.tags || []), tag]
        }));
    };

    // 切换题目类型
    const toggleType = (type: 'single' | 'multi' | 'truefalse') => {
        setConfig(prev => ({
            ...prev,
            types: prev.types?.includes(type)
                ? prev.types.filter(t => t !== type)
                : [...(prev.types || []), type]
        }));
    };

    // 切换维度
    const toggleDimension = (dim: Dimension) => {
        setConfig(prev => ({
            ...prev,
            dimensions: prev.dimensions?.includes(dim)
                ? prev.dimensions.filter(d => d !== dim)
                : [...(prev.dimensions || []), dim]
        }));
    };

    // 开始练习
    const startPractice = () => {
        const params = new URLSearchParams({
            mode: config.mode,
            limit: config.limit.toString()
        });

        if (config.types && config.types.length > 0 && config.types.length < 2) {
            params.set('types', config.types.join(','));
        }
        if (config.tags && config.tags.length > 0) {
            params.set('tags', config.tags.join(','));
        }
        if (config.dimensions && config.dimensions.length > 0) {
            params.set('dimensions', config.dimensions.join(','));
        }
        if (config.enableTimer) {
            params.set('timer', '1');
        }
        if (!config.enableReview) {
            params.set('noReview', '1');
        }

        router.push(`/practice?${params.toString()}`);
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-background via-background to-muted/30 pb-20">
            {/* 顶部导航 */}
            <header className="border-b bg-background/80 backdrop-blur-sm sticky top-0 z-50">
                <div className="container mx-auto px-4 h-16 flex items-center justify-between">
                    <Link href="/" className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors">
                        <ChevronLeft className="w-5 h-5" />
                        返回首页
                    </Link>
                    <h1 className="font-bold text-lg">配置练习</h1>
                    <div className="w-20" /> {/* 占位 */}
                </div>
            </header>

            <main className="container mx-auto px-4 py-8 max-w-4xl">
                {/* 模式选择 */}
                <section className="mb-8">
                    <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                        <Settings2 className="w-5 h-5 text-primary" />
                        选择练习模式
                    </h2>
                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                        {(Object.keys(PRACTICE_MODE_LABELS) as PracticeMode[]).map((mode) => {
                            const isActive = config.mode === mode;
                            return (
                                <button
                                    key={mode}
                                    onClick={() => handleModeChange(mode)}
                                    className={`p-4 rounded-xl border-2 transition-all text-left ${isActive
                                        ? 'border-primary bg-primary/5 shadow-lg scale-[1.02]'
                                        : 'border-border hover:border-primary/50 bg-card'
                                        }`}
                                >
                                    <div className={`w-10 h-10 rounded-lg bg-gradient-to-br ${ModeColors[mode]} flex items-center justify-center text-white mb-2`}>
                                        {ModeIcons[mode]}
                                    </div>
                                    <div className="font-medium text-sm">{PRACTICE_MODE_LABELS[mode]}</div>
                                    {isActive && (
                                        <CheckCircle2 className="w-4 h-4 text-primary mt-1" />
                                    )}
                                </button>
                            );
                        })}
                    </div>
                    <p className="text-sm text-muted-foreground mt-3 px-1">
                        {PRACTICE_MODE_DESCRIPTIONS[config.mode]}
                    </p>
                </section>

                {/* 题目数量 */}
                <section className="mb-8">
                    <h2 className="text-lg font-bold mb-3 flex items-center gap-2">
                        <BookOpen className="w-5 h-5 text-primary" />
                        题目数量
                    </h2>
                    <div className="flex flex-wrap gap-2">
                        {QUESTION_LIMIT_OPTIONS.map((num) => (
                            <button
                                key={num}
                                onClick={() => setConfig({ ...config, limit: num })}
                                className={`px-4 py-2 rounded-lg border transition-all ${config.limit === num
                                    ? 'border-primary bg-primary text-primary-foreground'
                                    : 'border-border bg-card hover:border-primary/50'
                                    }`}
                            >
                                {num} 题
                            </button>
                        ))}
                    </div>
                </section>

                {/* 高级选项 */}
                <section className="mb-8">
                    <button
                        onClick={() => setShowAdvanced(!showAdvanced)}
                        className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors mb-4"
                    >
                        <Settings2 className="w-4 h-4" />
                        {showAdvanced ? '收起高级选项' : '展开高级选项'}
                        <ChevronLeft className={`w-4 h-4 transition-transform ${showAdvanced ? 'rotate-90' : '-rotate-90'}`} />
                    </button>

                    {showAdvanced && (
                        <Card>
                            <CardContent className="pt-6 space-y-6">
                                {/* 题目类型 */}
                                <div>
                                    <h3 className="font-medium mb-3">题目类型</h3>
                                    <div className="flex gap-4">
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <Checkbox
                                                checked={config.types?.includes('single') ?? true}
                                                onCheckedChange={() => toggleType('single')}
                                            />
                                            <span>单选题</span>
                                        </label>
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <Checkbox
                                                checked={config.types?.includes('multi') ?? true}
                                                onCheckedChange={() => toggleType('multi')}
                                            />
                                            <span>多选题</span>
                                        </label>
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <Checkbox
                                                checked={config.types?.includes('truefalse') ?? true}
                                                onCheckedChange={() => toggleType('truefalse')}
                                            />
                                            <span>判断题</span>
                                        </label>
                                    </div>
                                </div>

                                {/* 认知维度 */}
                                <div>
                                    <h3 className="font-medium mb-3">认知维度 (可选)</h3>
                                    <div className="flex flex-wrap gap-2">
                                        {(Object.keys(DIMENSION_LABELS) as Dimension[]).map((dim) => (
                                            <button
                                                key={dim}
                                                onClick={() => toggleDimension(dim)}
                                                className={`px-3 py-1.5 rounded-lg border text-sm transition-all ${config.dimensions?.includes(dim)
                                                    ? 'border-primary bg-primary/10 text-primary'
                                                    : 'border-border hover:border-primary/50'
                                                    }`}
                                            >
                                                {DIMENSION_LABELS[dim]}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {/* 知识点筛选 */}
                                {(config.mode === 'focus' || config.mode === 'smart') && (
                                    <div>
                                        <h3 className="font-medium mb-3 flex items-center gap-2">
                                            <Tag className="w-4 h-4" />
                                            知识点筛选 (可选)
                                        </h3>
                                        <KeypointTree
                                            selectedTags={config.tags || []}
                                            onSelectionChange={(tags) => setConfig({ ...config, tags })}
                                            maxHeight="350px"
                                        />
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                    )}
                </section>

                {/* 开始按钮 */}
                <div className="fixed bottom-0 left-0 right-0 p-4 bg-background/80 backdrop-blur-sm border-t">
                    <div className="container mx-auto max-w-4xl">
                        <Button
                            size="lg"
                            className="w-full group text-lg h-14"
                            onClick={startPractice}
                        >
                            <span className="mr-2">🚀</span>
                            开始练习 ({config.limit} 题)
                            <ArrowRight className="w-5 h-5 ml-2 group-hover:translate-x-1 transition-transform" />
                        </Button>
                    </div>
                </div>
            </main>
        </div>
    );
}

