                                                    <span className="text-xs font-normal text-neutral-400 ml-0.5">
                                                        /{limit === -1 ? '∞' : limit}
                                                    </span>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import {
