                                    className={cn(
                                        "flex flex-col items-center justify-center p-3 rounded-xl border text-sm transition-all h-20",
                                        settings.aiSeverity === level.id
                                            ? "bg-primary/10 border-primary text-primary ring-2 ring-primary/20"
