"use client";

import React, { useEffect, useState } from 'react';
import { getSettingsAction, updateSettingsAction, resetUserDataAction, Settings } from '@/server/actions/settings';
import { getUserProfileAction, updateProfileAction } from '@/server/actions/profile';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import {
  ShieldAlert,
  Trash2,
  BrainCircuit,
  Gauge,
  Save,
  User,
  Database,
  Download,
  Loader2,
  Smartphone,
  CheckCircle2,
} from 'lucide-react';
import { useTheme } from 'next-themes';
import { cn } from '@/lib/utils';
import { useTerminology } from '@/lib/hooks/use-terminology';
import { usePWAInstall } from '@/hooks/usePWAInstall';

import { SettingsProfileTab } from './components/SettingsProfileTab';
import { SettingsAIPreferencesTab } from './components/SettingsAIPreferencesTab';
import { SettingsAppearanceTab } from './components/SettingsAppearanceTab';

// --- Tab Configuration ---
type SettingsTab = 'profile' | 'ai' | 'appearance' | 'data';

const TABS: { id: SettingsTab; label: string; icon: React.ElementType }[] = [
  { id: 'profile', label: '个人资料', icon: User },
  { id: 'ai', label: 'AI 偏好', icon: BrainCircuit },
  { id: 'appearance', label: '界面外观', icon: Gauge },
  { id: 'data', label: '数据管理', icon: Database },
];

export default function SettingsPage() {
  const [activeTab, setActiveTab] = useState<SettingsTab>('ai');
  const [settings, setSettings] = useState<Settings | null>(null);
  const [profile, setProfile] = useState<any | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const { theme, setTheme } = useTheme();
  const terminology = useTerminology();
  const { isInstallable, isInstalled, promptInstall } = usePWAInstall();

  useEffect(() => {
    getSettingsAction().then(setSettings);
    getUserProfileAction().then((res) => {
      if (res.success) setProfile(res.profile);
    });
  }, []);

  const handleSave = async () => {
    if (!settings) return;
    setIsSaving(true);
    try {
      // Parallel Save
      const promises = [updateSettingsAction(settings)];
      if (profile) {
        promises.push(updateProfileAction({ username: profile.username }));
      }

      const results = await Promise.all(promises);
      const profileResult = results[1] as any; // updateProfileAction result

      if (profileResult && !profileResult.success) {
        toast.error(profileResult.error || "资料更新失败");
      } else {
        toast.success("配置已保存");
        // Refresh to sync sidebar
        if (profileResult) window.location.reload();
      }
    } catch (e) {
      toast.error("保存失败");
    } finally {
      setIsSaving(false);
    }
  };

  const handleReset = async () => {
    if (!confirm("⚠️极度危险操作⚠️\n\n确定要【删号重练】吗？\n此操作将永久清空所有练习记录、错题本和掌握度数据！")) return;

    try {
      const res = await resetUserDataAction();
      if (res.success) {
        toast.success(res.message);
        window.location.reload();
      }
    } catch (e) {
      toast.error("重置失败");
    }
  };

  if (!settings) return (
    <div className="flex h-[calc(100vh-64px)] w-full items-center justify-center">
      <Loader2 className="h-6 w-6 animate-spin text-primary" />
      <span className="ml-2 text-muted-foreground text-sm">正在加载配置...</span>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-background">
      {/* Left Sidebar (Settings Navigation) */}
      <div className="w-full md:w-64 flex flex-col border-r border-border bg-background/50 backdrop-blur-sm md:h-screen md:sticky md:top-0">
        <div className="p-6">
          <h1 className="text-2xl font-serif font-bold text-foreground">设置与偏好</h1>
          <p className="text-xs text-muted-foreground mt-1">打造专属学习环境</p>
        </div>
        <nav className="flex-1 px-4 space-y-1">
          {TABS.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                "flex items-center gap-3 w-full px-3 py-2.5 rounded-lg text-sm font-medium transition-all text-left",
                activeTab === tab.id
                  ? "bg-primary/10 text-primary shadow-sm"
                  : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
              )}
            >
              <tab.icon className={cn("h-4 w-4", activeTab === tab.id ? "text-primary" : "text-muted-foreground")} />
              {tab.label}
            </button>
          ))}
        </nav>
        <div className="p-4 text-xs text-muted-foreground/50 text-center">
          ZhuoYu v1.2.0 Build 20260114
        </div>
      </div>

      {/* Right Content Area */}
      <div className="flex-1 p-6 md:p-12 pb-24 overflow-y-auto">
        <div className="max-w-2xl mx-auto space-y-8">

          {/* Header for Mobile */}
          <div className="md:hidden mb-6">
            <h2 className="text-xl font-bold flex items-center gap-2">
              {React.createElement(TABS.find(t => t.id === activeTab)?.icon || Gauge, { className: "w-5 h-5 text-primary" })}
              {TABS.find(t => t.id === activeTab)?.label}
            </h2>
          </div>

          {/* --- Content: AI Preferences --- */}
          {activeTab === 'ai' && (
            <SettingsAIPreferencesTab settings={settings} setSettings={setSettings} />
          )}

          {/* --- Content: Appearance --- */}
          {activeTab === 'appearance' && (
            <SettingsAppearanceTab
              theme={theme}
              setTheme={setTheme}
              terminologyMode={terminology.mode}
              setTerminologyMode={terminology.setMode}
            />
          )}

          {/* --- Content: Profile --- */}
          {activeTab === 'profile' && (
            <SettingsProfileTab
              profile={profile}
              setProfile={setProfile}
              onSave={handleSave}
              isSaving={isSaving}
            />
          )}

          {/* --- Content: Data Management --- */}
          {activeTab === 'data' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
              {/* 安装应用卡片 */}
              <div className="bg-card rounded-2xl border border-border p-6 shadow-sm">
                <h3 className="font-bold text-foreground mb-4 flex items-center gap-2">
                  <Smartphone className="w-4 h-4 text-primary" />
                  安装应用
                </h3>
                <div className="p-4 bg-primary/5 rounded-xl border border-primary/20 flex items-center justify-between">
                  <div>
                    <div className="font-medium text-sm text-foreground">添加到桌面</div>
                    <div className="text-xs text-muted-foreground">
                      {isInstalled
                        ? '应用已安装，可从桌面启动'
                        : '像原生 App 一样使用琢玉'}
                    </div>
                  </div>
                  {isInstalled ? (
                    <div className="flex items-center gap-2 text-primary text-sm font-medium">
                      <CheckCircle2 className="w-4 h-4" />
                      已安装
                    </div>
                  ) : isInstallable ? (
                    <Button
                      onClick={promptInstall}
                      size="sm"
                      className="bg-primary hover:bg-primary/90"
                    >
                      <Smartphone className="w-4 h-4 mr-2" />
                      立即安装
                    </Button>
                  ) : (
                    <div className="text-xs text-muted-foreground max-w-[140px] text-right">
                      请使用 Chrome/Edge 浏览器访问
                    </div>
                  )}
                </div>
              </div>

              {/* 数据管理卡片 */}
              <div className="bg-card rounded-2xl border border-border p-6 shadow-sm">
                <h3 className="font-bold text-foreground mb-4 flex items-center gap-2">
                  <Database className="w-4 h-4 text-primary" />
                  数据管理
                </h3>
                <div className="space-y-4">
                  <div className="p-4 bg-muted/50 rounded-xl border border-border flex items-center justify-between">
                    <div>
                      <div className="font-medium text-sm text-foreground">导出个人数据</div>
                      <div className="text-xs text-muted-foreground">下载您的所有学习记录与设置</div>
                    </div>
                    <Button variant="outline" size="sm">
                      <Download className="w-4 h-4 mr-2" />
                      导出 CSV
                    </Button>
                  </div>

                  <div className="p-4 bg-destructive/5 rounded-xl border border-destructive/20 flex items-center justify-between">
                    <div>
                      <div className="font-medium text-sm text-destructive">危险操作</div>
                      <div className="text-xs text-destructive/70">数据一旦删除将无法恢复</div>
                    </div>
                    <Button variant="ghost" size="sm"
                      onClick={handleReset}
                      className="text-destructive hover:text-destructive hover:bg-destructive/10"
                    >
                      <Trash2 className="w-4 h-4 mr-2" />
                      清空数据
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Save Button (Floating) - Only for AI Tab as specific setting */}
          {activeTab === 'ai' && (
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0">
              <Button
                onClick={handleSave}
                disabled={isSaving}
                className="shadow-2xl shadow-primary/20 dark:shadow-primary/10 bg-primary hover:bg-primary/90 text-primary-foreground rounded-full px-6 py-6 h-auto text-lg transition-transform hover:scale-105 active:scale-95"
              >
                {isSaving ? <Loader2 className="w-6 h-6 animate-spin" /> : <Save className="w-6 h-6" />}
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { textbookService } from '@/lib/services/textbook';
import { Button } from '@/components/ui/button';
import { List } from 'lucide-react';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import rehypeRaw from 'rehype-raw';
import { Drawer, DrawerContent, DrawerTrigger, DrawerHeader, DrawerTitle } from "@/components/ui/drawer";
import { TextbookChat } from '@/components/textbooks/TextbookChat';

// Force dynamic because we are reading from DB directly in Server Component
export const revalidate = 60; // 开启 ISR，每 60 秒可以在后台重头生成一次，提升首屏响应速度

interface PageProps {
    params: Promise<{ id: string }>;
    searchParams: Promise<{ chapter?: string }>;
}

export default async function TextbookReaderPage({ params, searchParams }: PageProps) {
    const { id } = await params;
    const { chapter } = await searchParams;
    const textbookId = parseInt(id);

    const textbook = textbookService.getTextbook(textbookId);
    if (!textbook) notFound();

    const chapters = textbookService.getChapters(textbookId);
    const currentChapterId = chapter ? parseInt(chapter) : (chapters.length > 0 ? chapters[0].id : null);

    const currentChapter = currentChapterId ? textbookService.getChapter(currentChapterId) : null;

    return (
        <div className="flex h-[calc(100vh-4rem)]">
            {/* Sidebar - Desktop */}
            <div className="hidden md:flex w-64 flex-col border-r bg-muted/20">
                <div className="p-4 border-b">
                    <Link href="/textbooks" className="text-sm text-muted-foreground hover:text-primary mb-2 flex items-center">
                        &larr; 返回书架
                    </Link>
                    <h2 className="font-semibold truncate" title={textbook.title}>{textbook.title}</h2>
                </div>
                <div className="flex-1 overflow-y-auto p-2">
                    {chapters.map((chap) => (
                        <Link
                            key={chap.id}
                            href={`/textbooks/${textbookId}?chapter=${chap.id}`}
                            className={`block px-3 py-2 text-sm rounded-md mb-1 truncate transition-colors ${chap.id === currentChapterId
                                ? 'bg-primary/10 text-primary font-medium'
                                : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                                }`}
                            title={chap.title}
                        >
                            <div style={{ paddingLeft: `${(chap.level - 1) * 12}px` }}>
                                {chap.title}
                            </div>
                        </Link>
                    ))}
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col h-full overflow-hidden">
                {/* Mobile Header */}
                <div className="md:hidden flex items-center p-4 border-b">
                    <Drawer>
                        <DrawerTrigger asChild>
                            <Button variant="ghost" size="icon" className="mr-2">
                                <List className="h-5 w-5" />
                            </Button>
                        </DrawerTrigger>
                        <DrawerContent>
                            <DrawerHeader className="mb-4">
                                <DrawerTitle>{textbook.title}</DrawerTitle>
                            </DrawerHeader>
                            <div className="overflow-y-auto h-[60vh] px-4">
                                {chapters.map((chap) => (
                                    <Link
                                        key={chap.id}
                                        href={`/textbooks/${textbookId}?chapter=${chap.id}`}
                                        className={`block px-3 py-2 text-sm rounded-md mb-1 truncate ${chap.id === currentChapterId
                                            ? 'bg-primary/10 text-primary font-medium'
                                            : 'text-muted-foreground hover:bg-muted'
                                            }`}
                                    >
                                        <div style={{ paddingLeft: `${(chap.level - 1) * 12}px` }}>
                                            {chap.title}
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        </DrawerContent>
                    </Drawer>
                    <h2 className="font-semibold truncate">{textbook.title}</h2>
                </div>

                {/* Reader Content */}
                <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12">
                    <div className="max-w-3xl mx-auto">
                        {currentChapter ? (
                            <>
                                <article className="prose dark:prose-invert max-w-none">
                                    <h1>{currentChapter.title}</h1>
                                    <ReactMarkdown
                                        remarkPlugins={[remarkGfm, remarkMath]}
                                        rehypePlugins={[rehypeKatex, rehypeRaw]}
                                        components={{
                                            code: ({ node, inline, className, children, ...props }: any) => {
                                                return (
                                                    <code className={`${className} bg-muted px-1.5 py-0.5 rounded text-sm`} {...props}>
                                                        {children}
                                                    </code>
                                                )
                                            }
                                        }}
                                    >
                                        {currentChapter.content}
                                    </ReactMarkdown>
                                </article>
                                <TextbookChat
                                    context={currentChapter.content}
                                    title={textbook.title}
                                />
                            </>
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
                                <p>请选择左侧章节开始阅读</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Play } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';

interface QuestionCountPickerProps {
    /** 可选题目总数 */
    totalCount: number;
    /** 确认后回调，参数为选择的题量 */
    onConfirm: (count: number) => void;
    /** 是否禁用 */
    disabled?: boolean;
    /** 触发按钮的内容 */
    children: React.ReactNode;
}

/** 预设的快捷题量选项 */
const PRESET_COUNTS = [5, 10, 15, 20, 30];

/**
 * 题量选择器
 * 以 Popover 形式展示，提供预设选项 + 全部，点击即开始
 */
export function QuestionCountPicker({
    totalCount,
    onConfirm,
    disabled = false,
    children,
}: QuestionCountPickerProps) {
    const [open, setOpen] = useState(false);

    // 过滤掉超过总数的预设选项
    const availablePresets = PRESET_COUNTS.filter(c => c < totalCount);

    const handleSelect = (count: number) => {
        setOpen(false);
        onConfirm(count);
    };

    // 题目数 <= 5 时直接开始全部，无需选择
    if (totalCount <= 5) {
        return (
            <span onClick={() => !disabled && onConfirm(totalCount)}>
                {children}
            </span>
        );
    }

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild disabled={disabled}>
                {children}
            </PopoverTrigger>
            <PopoverContent
                className="w-48 p-2"
                align="end"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="text-xs text-muted-foreground px-2 py-1 mb-1">
                    选择练习题量（共 {totalCount} 题）
                </div>
                <div className="space-y-0.5">
                    {availablePresets.map(count => (
                        <button
                            key={count}
                            className="w-full text-left px-3 py-2 text-sm rounded-md hover:bg-muted transition-colors flex items-center justify-between"
                            onClick={() => handleSelect(count)}
                        >
                            <span>{count} 题</span>
                            <Play className="w-3 h-3 text-muted-foreground" />
                        </button>
                    ))}
                    {/* 全部选项 */}
                    <div className="border-t my-1" />
                    <button
                        className="w-full text-left px-3 py-2 text-sm rounded-md hover:bg-muted transition-colors flex items-center justify-between font-medium"
                        onClick={() => handleSelect(totalCount)}
                    >
                        <span>全部 {totalCount} 题</span>
                        <Play className="w-3 h-3 text-muted-foreground fill-current" />
                    </button>
                </div>
            </PopoverContent>
        </Popover>
    );
}

"use client";

import React, { useState } from 'react';
import Link from 'next/link';
import {
    BookOpen,
    AlertTriangle,
    Play,
    Flame,
    Calendar,
    Layers,
    CheckCircle2,
    Archive,
    RotateCcw,
    Shuffle,
    SortDesc
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { useWrongBookController } from './hooks/use-wrong-book-controller';
import { WrongQuestionCard } from './components/WrongQuestionCard';
import { TagTreeView } from './components/TagTreeView';
import { WrongBookSkeleton } from './components/WrongBookSkeleton';
import { QuestionCountPicker } from './components/QuestionCountPicker';

export default function WrongBookPage() {
    // 复练排序模式：priority = 按错误频次+遗忘权重，random = 纯随机
    const [practiceMode, setPracticeMode] = useState<'priority' | 'random'>('priority');

    const {
        // 数据
        questions,
        groupedQuestions,
        masteredQuestions,
        stats,
        // UI 状态
        isLoading,
        viewMode,
        setViewMode,
        expandedTags,
        selectedIds,
        isCreating,
        isRandomLoading,
        // 详情状态
        expandedQuestionId,
        questionDetail,
        isLoadingDetail,
        // 方法
        toggleTag,
        toggleSelect,
        selectAll,
        startPractice,
        startRandomPractice,
        toggleQuestionDetail,
        handleMarkAsMastered,
        handleUnmarkMastered
    } = useWrongBookController();

    // 加载状态
    if (isLoading) {
        return <WrongBookSkeleton />;
    }

    return (
        <div className="min-h-screen bg-background">
            <main className="container mx-auto max-w-4xl px-4 py-8 pb-32">
                {/* 头部 */}
                <div className="mb-8">
                    <h1 className="text-3xl font-bold text-foreground flex items-center gap-3">
                        <BookOpen className="text-red-500 h-8 w-8" />
                        错题本
                    </h1>
                    <p className="text-muted-foreground mt-1">
                        智能汇集易错知识点，攻克薄弱环节
                    </p>
                </div>

                {/* 统计卡片 */}
                {stats.total > 0 && (
                    <div className="mb-8">
                        <div className="grid grid-cols-3 gap-4 mb-4">
                            <div className="bg-card rounded-xl p-4 border shadow-sm">
                                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                                    <AlertTriangle className="w-4 h-4" />
                                    累计错题
                                </div>
                                <div className="text-2xl font-bold text-foreground">{stats.total}</div>
                            </div>
                            <div className="bg-card rounded-xl p-4 border shadow-sm">
                                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                                    <Calendar className="w-4 h-4" />
                                    本周新增
                                </div>
                                <div className="text-2xl font-bold text-amber-600">{stats.recent}</div>
                            </div>
                            <div className="bg-card rounded-xl p-4 border shadow-sm">
                                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                                    <Flame className="w-4 h-4" />
                                    高频错题
                                </div>
                                <div className="text-2xl font-bold text-red-600">{stats.frequent}</div>
                            </div>
                        </div>

                        {/* 复练模式选择 + 智能随机练习入口 */}
                        <div className="space-y-2">
                            {/* 排序模式切换 */}
                            <div className="flex items-center gap-2 bg-muted/50 rounded-xl p-1">
                                <button
                                    onClick={() => setPracticeMode('priority')}
                                    className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                                        practiceMode === 'priority'
                                            ? 'bg-card shadow text-foreground'
                                            : 'text-muted-foreground hover:text-foreground'
                                    }`}
                                >
                                    <SortDesc className="w-3.5 h-3.5" />
                                    优先复习
                                </button>
                                <button
                                    onClick={() => setPracticeMode('random')}
                                    className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                                        practiceMode === 'random'
                                            ? 'bg-card shadow text-foreground'
                                            : 'text-muted-foreground hover:text-foreground'
                                    }`}
                                >
                                    <Shuffle className="w-3.5 h-3.5" />
                                    随机顺序
                                </button>
                            </div>

                            {/* 智能随机练习入口 - 带题量选择 */}
                            <QuestionCountPicker
                                totalCount={stats.total}
                                onConfirm={(count) => startRandomPractice(count, undefined, practiceMode)}
                                disabled={isRandomLoading}
                            >
                                <Button
                                    className="w-full h-14 text-lg bg-red-600 hover:bg-red-700 shadow-lg shadow-red-500/20"
                                    disabled={isRandomLoading}
                                >
                                    <Play className={`w-5 h-5 mr-2 ${isRandomLoading ? 'animate-pulse' : 'fill-current'}`} />
                                    {isRandomLoading ? '智能抽题中...' : practiceMode === 'priority' ? '智能优先复习' : '随机顺序复习'}
                                </Button>
                            </QuestionCountPicker>
                            <p className="text-center text-[10px] text-muted-foreground opacity-70">
                                {practiceMode === 'priority'
                                    ? '综合"错误频次"与"遗忘时长"为你挑选最急需复习的题目'
                                    : '随机抽取指定数量的错题进行练习'}
                            </p>
                        </div>
                    </div>
                )}

                {/* 无错题状态 */}
                {stats.total === 0 ? (
                    <div className="bg-card rounded-2xl p-12 text-center border border-dashed border-border">
                        <div className="mx-auto w-16 h-16 bg-green-500/10 rounded-full flex items-center justify-center mb-4">
                            <CheckCircle2 className="text-green-500 h-8 w-8" />
                        </div>
                        <h3 className="text-lg font-medium text-foreground">太棒了！暂无错题</h3>
                        <p className="text-muted-foreground mt-2 mb-6">
                            继续保持正确率，或者开始新的练习挑战自己。
                        </p>
                        <Link href="/practice">
                            <Button variant="outline">开始练习</Button>
                        </Link>
                    </div>
                ) : (
                    <>
                        {/* 视图切换 */}
                        <div className="flex items-center justify-between mb-4">
                            <div className="flex gap-2">
                                <button
                                    onClick={() => setViewMode('list')}
                                    className={`px-3 py-1.5 rounded-lg text-sm transition-all flex items-center gap-1 ${viewMode === 'list' ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/80'
                                        }`}
                                >
                                    <Layers className="w-3 h-3" />
                                    全部 ({questions.length})
                                </button>
                                <button
                                    onClick={() => setViewMode('byTag')}
                                    className={`px-3 py-1.5 rounded-lg text-sm transition-all ${viewMode === 'byTag' ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/80'
                                        }`}
                                >
                                    按知识点
                                </button>
                                <button
                                    onClick={() => setViewMode('mastered')}
                                    className={`px-3 py-1.5 rounded-lg text-sm transition-all flex items-center gap-1 ${viewMode === 'mastered' ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/80'
                                        }`}
                                >
                                    <Archive className="w-3 h-3" />
                                    已掌握 ({masteredQuestions.length})
                                </button>
                            </div>

                            {viewMode === 'list' && (
                                <div className="flex items-center gap-2">
                                    <Button variant="outline" size="sm" onClick={selectAll}>
                                        {selectedIds.size === questions.length ? '取消全选' : '全选'}
                                    </Button>
                                    <span className="text-sm text-muted-foreground">
                                        已选 {selectedIds.size} 题
                                    </span>
                                </div>
                            )}
                        </div>

                        {/* 列表视图 */}
                        {viewMode === 'list' && (
                            <div className="space-y-3">
                                {questions.map((q, index) => (
                                    <div 
                                        key={q.questionId} 
                                        className={`animate-fade-in-up ${index < 5 ? `stagger-${index + 1}` : ''}`}
                                    >
                                        <WrongQuestionCard
                                            question={q}
                                            isSelected={selectedIds.has(q.questionId)}
                                            isExpanded={expandedQuestionId === q.questionId}
                                            detail={expandedQuestionId === q.questionId ? questionDetail : null}
                                            isLoadingDetail={isLoadingDetail}
                                            onToggleSelect={() => toggleSelect(q.questionId)}
                                            onToggleDetail={() => toggleQuestionDetail(q.questionId)}
                                            onPractice={() => startPractice([q.questionId])}
                                            onMarkAsMastered={() => handleMarkAsMastered(q.questionId)}
                                        />
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* 按知识点视图 */}
                        {viewMode === 'byTag' && (
                            <TagTreeView
                                groupedQuestions={groupedQuestions}
                                onStartPractice={startPractice}
                            />
                        )}

                        {/* 已掌握视图 */}
                        {viewMode === 'mastered' && (
                            <div className="space-y-3">
                                {masteredQuestions.length === 0 ? (
                                    <div className="bg-card rounded-2xl p-12 text-center border border-dashed">
                                        <div className="mx-auto w-16 h-16 bg-muted rounded-full flex items-center justify-center mb-4">
                                            <Archive className="text-muted-foreground h-8 w-8" />
                                        </div>
                                        <h3 className="text-lg font-medium">暂无已掌握的错题</h3>
                                        <p className="text-muted-foreground mt-2">
                                            在错题详情中点击"标记为已掌握"可将攻克的题目归档
                                        </p>
                                    </div>
                                ) : (
                                    masteredQuestions.map((q) => (
                                        <div
                                            key={q.questionId}
                                            className="bg-card rounded-xl p-4 border shadow-sm"
                                        >
                                            <div className="flex items-start gap-3">
                                                <div className="w-8 h-8 rounded-full bg-green-500/10 flex items-center justify-center shrink-0">
                                                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                                                </div>
                                                <div className="flex-1">
                                                    <div className="text-sm text-foreground leading-relaxed line-clamp-2 mb-2">
                                                        {q.questionContent}
                                                    </div>
                                                    <div className="flex flex-wrap items-center gap-2">
                                                        {q.tags.slice(0, 3).map(tag => (
                                                            <Badge key={tag} variant="outline" className="text-xs">
                                                                {tag}
                                                            </Badge>
                                                        ))}
                                                        <span className="text-xs text-green-600 flex items-center gap-1">
                                                            <CheckCircle2 className="w-3 h-3" />
                                                            掌握于 {new Date(q.masteredAt).toLocaleDateString()}
                                                        </span>
                                                    </div>
                                                </div>
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => handleUnmarkMastered(q.questionId)}
                                                    title="恢复到错题本"
                                                >
                                                    <RotateCcw className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        )}
                    </>
                )}
            </main>

            {/* 底部操作栏 */}
            {questions.length > 0 && viewMode === 'list' && selectedIds.size > 0 && (
                <div className="fixed bottom-0 left-0 right-0 p-4 bg-background/80 backdrop-blur-sm border-t">
                    <div className="container mx-auto max-w-4xl">
                        <QuestionCountPicker
                            totalCount={selectedIds.size}
                            onConfirm={(count) => startPractice(undefined, count)}
                            disabled={isCreating}
                        >
                            <Button
                                size="lg"
                                className="w-full h-14 text-lg"
                                disabled={isCreating}
                            >
                                {isCreating ? '正在创建...' : `开始练习选中的 ${selectedIds.size} 道错题`}
                                <Play className="w-5 h-5 ml-2" />
                            </Button>
                        </QuestionCountPicker>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useTerminology } from '@/lib/hooks/use-terminology';
import { cn } from '@/lib/utils';
import { Home, BookOpen, Book, User, Bot } from 'lucide-react';

interface UserProps {
    user?: {
        username: string;
        id: number;
    } | null;
}

export function MobileNav({ user }: UserProps) {
    const pathname = usePathname();
    const { t } = useTerminology();

    // Hide on login/register pages
    if (pathname === '/login' || pathname === '/register') {
        return null;
    }

    const navItems = [
        { name: t('nav.home'), href: '/dashboard', icon: Home },
        { name: t('nav.practice'), href: '/practice', icon: BookOpen },
        { name: 'AI 助手', href: '/chat', icon: Bot },
        { name: t('nav.knowledge'), href: '/knowledge', icon: Book },
        { name: '我的', href: '/profile', icon: User },
    ];

    return (
        <nav className="md:hidden fixed bottom-6 left-6 right-6 z-50 bg-card/95 backdrop-blur-md rounded-2xl shadow-xl shadow-black/10 dark:shadow-black/30 border border-border ring-1 ring-border/50">
            <div className="flex justify-around items-center h-16">
                {navItems.map((item) => {
                    const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`);
                    return (
                        <Link
                            key={item.href}
                            href={item.href}
                            className={cn(
                                "flex flex-col items-center justify-center w-full h-full gap-1 transition-all duration-300",
                                isActive ? "text-primary" : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <div className={cn(
                                "relative p-1.5 rounded-xl transition-all duration-300",
                                isActive ? "bg-emerald-100/50 transform -translate-y-1" : ""
                            )}>
                                <item.icon className={cn("w-5 h-5", isActive && "fill-current")} />
                                {isActive && (
                                    <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 bg-emerald-500 rounded-full" />
                                )}
                            </div>
                            <span className={cn(
                                "text-[10px] font-medium transition-all duration-300",
                                isActive ? "scale-105 font-bold" : "scale-100"
                            )}>
                                {item.name}
                            </span>
                        </Link>
                    );
                })}
            </div>
        </nav>
    );
}

"use client";

import React from 'react';
import dynamic from 'next/dynamic';
import { TrendDataItem } from '@/server/actions/stats';
import { Loader2 } from 'lucide-react';

// 动态提取所需的 recharts 组件以实现包体积懒加载
const AreaChart = dynamic(() => import('recharts').then(mod => mod.AreaChart), { ssr: false });
const Area = dynamic(() => import('recharts').then(mod => mod.Area), { ssr: false });
const XAxis = dynamic(() => import('recharts').then(mod => mod.XAxis), { ssr: false });
const YAxis = dynamic(() => import('recharts').then(mod => mod.YAxis), { ssr: false });
const CartesianGrid = dynamic(() => import('recharts').then(mod => mod.CartesianGrid), { ssr: false });
const Tooltip = dynamic(() => import('recharts').then(mod => mod.Tooltip), { ssr: false });
const ResponsiveContainer = dynamic(() => import('recharts').then(mod => mod.ResponsiveContainer), { ssr: false });
const BarChart = dynamic(() => import('recharts').then(mod => mod.BarChart), { ssr: false });
const Bar = dynamic(() => import('recharts').then(mod => mod.Bar), { ssr: false });
const ComposedChart = dynamic(() => import('recharts').then(mod => mod.ComposedChart), { ssr: false });
const Line = dynamic(() => import('recharts').then(mod => mod.Line), { ssr: false });

interface TrendChartProps {
    data: TrendDataItem[];
    type?: 'accuracy' | 'practiced' | 'combined';
    height?: number;
}

// 自定义 Tooltip
const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-card border rounded-lg shadow-lg p-3 text-sm">
                <p className="font-medium text-foreground mb-1">{label}</p>
                {payload.map((entry: any, index: number) => (
                    <p key={index} style={{ color: entry.color }}>
                        {entry.name}: {entry.value}{entry.name === '正确率' ? '%' : ' 题'}
                    </p>
                ))}
            </div>
        );
    }
    return null;
};

// 正确率趋势图
export function AccuracyTrendChart({ data, height = 200 }: Omit<TrendChartProps, 'type'>) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <AreaChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <defs>
                    <linearGradient id="accuracyGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="hsl(var(--primary))" stopOpacity={0.3} />
                        <stop offset="95%" stopColor="hsl(var(--primary))" stopOpacity={0} />
                    </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                <XAxis
                    dataKey="displayDate"
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                />
                <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                    tickFormatter={(v) => `${v}%`}
                />
                <Tooltip content={<CustomTooltip />} />
                <Area
                    type="monotone"
                    dataKey="accuracy"
                    name="正确率"
                    stroke="hsl(var(--primary))"
                    fill="url(#accuracyGradient)"
                    strokeWidth={2}
                />
            </AreaChart>
        </ResponsiveContainer>
    );
}

// 练习量柱状图
export function PracticedBarChart({ data, height = 200 }: Omit<TrendChartProps, 'type'>) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <BarChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                <XAxis
                    dataKey="displayDate"
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                />
                <YAxis
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                />
                <Tooltip content={<CustomTooltip />} />
                <Bar
                    dataKey="practiced"
                    name="练习量"
                    fill="hsl(var(--primary))"
                    radius={[4, 4, 0, 0]}
                    opacity={0.8}
                />
                <Bar
                    dataKey="correct"
                    name="正确数"
                    fill="hsl(142 76% 36%)"
                    radius={[4, 4, 0, 0]}
                    opacity={0.8}
                />
            </BarChart>
        </ResponsiveContainer>
    );
}

// 综合趋势图 (柱状图 + 折线图)
export function CombinedTrendChart({ data, height = 250 }: Omit<TrendChartProps, 'type'>) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <ComposedChart data={data} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                <XAxis
                    dataKey="displayDate"
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                />
                <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                />
                <YAxis
                    yAxisId="right"
                    orientation="right"
                    domain={[0, 100]}
                    tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }}
                    axisLine={{ stroke: 'hsl(var(--border))' }}
                    tickFormatter={(v) => `${v}%`}
