import React, { useState, useRef, useEffect, useCallback, forwardRef, useImperativeHandle, memo } from 'react';
import { Send, Loader2, StopCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';

export interface ChatInputHandle {
    focus: () => void;
    setValue: (value: string) => void;
}

interface ChatInputProps {
    isLoading: boolean;
    showFavorites: boolean;
    enableRag: boolean;
    setEnableRag: (enable: boolean) => void;
    onSendMessage: (content: string) => void;
    onStopGeneration: () => void;
}

// 快捷指令定义
const COMMANDS = [
    { command: '/quiz', description: '生成练习题', example: '/quiz 教育学基础' },
    { command: '/explain', description: '解释概念', example: '/explain 认知发展理论' },
];

export const ChatInput = memo(forwardRef<ChatInputHandle, ChatInputProps>(({
    isLoading,
    showFavorites,
    enableRag,
    setEnableRag,
    onSendMessage,
    onStopGeneration
}, ref) => {
    const [inputValue, setInputValue] = useState('');
    const [showCommands, setShowCommands] = useState(false);
    const [filteredCommands, setFilteredCommands] = useState(COMMANDS);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useImperativeHandle(ref, () => ({
        focus: () => {
            textareaRef.current?.focus();
        },
        setValue: (value: string) => {
            setInputValue(value);
        }
    }));

    // 处理快捷指令输入
    useEffect(() => {
        if (inputValue.startsWith('/')) {
            const query = inputValue.toLowerCase();
            const filtered = COMMANDS.filter(cmd => cmd.command.startsWith(query));
            setFilteredCommands(filtered);
            setShowCommands(filtered.length > 0);
        } else {
            setShowCommands(false);
        }
    }, [inputValue]);

    const selectCommand = useCallback((command: string) => {
        setInputValue(command + ' ');
        setShowCommands(false);
        textareaRef.current?.focus();
    }, []);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!inputValue || !inputValue.trim()) return;

        onSendMessage(inputValue);
        setInputValue('');

        // Reset height
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (inputValue.trim() && !isLoading) {
                handleSubmit(e);
            }
        }
        // 按 Tab 选择第一个指令
        if (e.key === 'Tab' && showCommands && filteredCommands.length > 0) {
            e.preventDefault();
            selectCommand(filteredCommands[0].command);
        }
        // 按 Esc 关闭指令列表
        if (e.key === 'Escape') {
            setShowCommands(false);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        e.target.style.height = 'auto';
        e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`;
        setInputValue(e.target.value);
    };

    return (
        <footer className="p-4 md:p-6 bg-gradient-to-t from-background via-background to-transparent sticky bottom-0 z-20">
            <div className="max-w-3xl mx-auto relative group">
                {/* 快捷指令自动补全 */}
                {showCommands && (
                    <div className="absolute bottom-full mb-2 left-0 right-0 bg-popover border border-border rounded-xl shadow-lg overflow-hidden z-10">
                        {filteredCommands.map(cmd => (
                            <button
                                key={cmd.command}
                                onClick={() => selectCommand(cmd.command)}
                                className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-muted transition-colors"
                            >
                                <code className="text-sm font-mono text-primary">{cmd.command}</code>
                                <span className="text-xs text-muted-foreground">{cmd.description}</span>
                                <span className="text-xs text-muted-foreground/50 ml-auto">{cmd.example}</span>
                            </button>
                        ))}
                    </div>
                )}

                {/* 工具栏与提示 */}
                <div className="flex justify-between items-center mb-2 px-1">
                    <div className="text-xs text-muted-foreground/50">
                        {showFavorites ? '' : '支持 Shift + Enter 换行'}
                    </div>
                    <div className="flex items-center gap-2">
                        <span className={`text-xs transition-colors ${enableRag ? 'text-primary font-medium' : 'text-muted-foreground'}`}>
                            {enableRag ? '知识库增强已启用' : '知识库增强已关闭'}
                        </span>
                        <button
                            type="button"
                            onClick={() => setEnableRag(!enableRag)}
                            className={`relative inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background ${enableRag ? 'bg-primary' : 'bg-input'
                                }`}
                        >
                            <span
                                className={`pointer-events-none block h-4 w-4 rounded-full bg-background shadow-lg ring-0 transition-transform ${enableRag ? 'translate-x-4' : 'translate-x-0'
                                    }`}
                            />
                        </button>
                    </div>
                </div>

                <form
                    onSubmit={handleSubmit}
                    className="relative flex items-end gap-2 bg-muted/50 border border-input rounded-2xl p-2 pl-4 focus-within:bg-background focus-within:border-primary focus-within:ring-4 focus-within:ring-primary/20 transition-all duration-300 shadow-sm"
                >
                    <textarea
                        ref={textareaRef}
                        value={inputValue}
                        onChange={handleChange}
                        onKeyDown={handleKeyDown}
                        placeholder={showFavorites ? "收藏夹模式下无法发送消息" : "输入问题，Shift + Enter 换行，输入 / 查看指令..."}
                        className="flex-1 max-h-[200px] py-3 bg-transparent border-none focus:ring-0 text-sm resize-none scrollbar-hide font-medium text-foreground placeholder:text-muted-foreground"
                        rows={1}
                        disabled={isLoading || showFavorites}
                    />

                    <div className="pb-1 pr-1">
                        {isLoading ? (
                            <Button
                                type="button"
                                onClick={onStopGeneration}
                                variant="destructive"
                                size="icon"
                                data-testid="stop-button"
                                className="h-10 w-10 rounded-xl shrink-0 shadow-lg shadow-destructive/20"
                            >
                                <StopCircle className="w-5 h-5" />
                            </Button>
                        ) : (
                            <Button
                                type="submit"
                                disabled={!inputValue || !inputValue.trim() || showFavorites}
                                size="icon"
                                data-testid="send-button"
                                className="h-10 w-10 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground shrink-0 shadow-lg shadow-primary/20 transition-all active:scale-95 disabled:bg-muted disabled:text-muted-foreground disabled:shadow-none"
                            >
                                <Send className="w-5 h-5" />
                            </Button>
                        )}
                    </div>
                </form>

                {isLoading && (
                    <div className="absolute -top-10 left-0 right-0 flex justify-center pointer-events-none">
                        <span className="bg-background/90 backdrop-blur text-[10px] font-bold text-primary px-3 py-1 rounded-full shadow-sm border border-border flex items-center gap-2 animate-bounce">
                            <Loader2 className="w-3 h-3 animate-spin" /> AI THINKING
                        </span>
                    </div>
                )}
            </div>
        </footer>
    );
}));

ChatInput.displayName = 'ChatInput';

import React from 'react';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger
} from '@/components/ui/dropdown-menu';
import { Brain, GraduationCap, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';

export type ChatMode = 'standard' | 'socratic';

interface ChatModeToggleProps {
    mode: ChatMode;
    onModeChange: (mode: ChatMode) => void;
}

export function ChatModeToggle({ mode, onModeChange }: ChatModeToggleProps) {
    return (
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="h-8 gap-2 bg-muted/50 hover:bg-muted">
                    {mode === 'standard' ? (
                        <>
                            <Brain className="h-4 w-4 text-blue-500" />
                            <span className="text-xs font-medium">标准助手</span>
                        </>
                    ) : (
                        <>
                            <GraduationCap className="h-4 w-4 text-purple-600" />
                            <span className="text-xs font-medium text-purple-600">苏格拉底导师</span>
                        </>
                    )}
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-[200px]">
                <DropdownMenuItem onClick={() => onModeChange('standard')} className="gap-2 cursor-pointer">
                    <Brain className="h-4 w-4 text-blue-500" />
                    <div className="flex flex-col text-left">
                        <span className="font-medium">标准助手</span>
                        <span className="text-xs text-muted-foreground">直接回答，简洁明了</span>
                    </div>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => onModeChange('socratic')} className="gap-2 cursor-pointer bg-purple-50/50 dark:bg-purple-900/10">
                    <GraduationCap className="h-4 w-4 text-purple-600" />
                    <div className="flex flex-col text-left">
                        <span className="font-medium text-purple-600">苏格拉底导师</span>
                        <span className="text-xs text-muted-foreground">循循善诱，启发思考</span>
                    </div>
                </DropdownMenuItem>
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquarePlus, Search, Loader2, Star, MessageSquare, Trash2, Pencil, Check, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useTerminology } from '@/lib/hooks/use-terminology';
import { renameChatSessionAction } from '@/server/actions/chat';

interface ChatSidebarProps {
    sessions: any[];
    currentSessionId: number | null;
    onSessionSelect: (sessionId: number, messageId?: number) => void;
    onNewSession: () => void;
    onDeleteSession: (sessionId: number) => void;
    onRenameSession?: (sessionId: number, newTitle: string) => void;
    showFavorites: boolean;
    onToggleShowFavorites: () => void;
}

// 日期格式化
const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
};

const highlightText = (text: string, query: string) => {
    if (!query || !text) return text;
    const parts = text.split(new RegExp(`(${query})`, 'gi'));
    return (
        <span>
            {parts.map((part, i) =>
                part.toLowerCase() === query.toLowerCase() ?
                    <span key={i} className="text-primary font-bold bg-primary/10 rounded px-0.5">{part}</span> :
                    part
            )}
        </span>
    );
};

/** 单条会话条目（含内联重命名） */
function SessionItem({
    session,
    isActive,
    onSelect,
    onDelete,
    onRename,
}: {
    session: any;
    isActive: boolean;
    onSelect: () => void;
    onDelete: () => void;
    onRename: (newTitle: string) => void;
}) {
    const [isEditing, setIsEditing] = useState(false);
    const [editValue, setEditValue] = useState(session.title);
    const inputRef = useRef<HTMLInputElement>(null);

    // 进入编辑模式时聚焦输入框
    useEffect(() => {
        if (isEditing) {
            inputRef.current?.focus();
            inputRef.current?.select();
        }
    }, [isEditing]);

    const commitRename = () => {
        const trimmed = editValue.trim();
        if (trimmed && trimmed !== session.title) {
            onRename(trimmed);
        }
        setIsEditing(false);
    };

    const cancelRename = () => {
        setEditValue(session.title);
        setIsEditing(false);
    };

    return (
        <div
            className={`group relative rounded-lg transition-all ${isActive
                ? 'bg-card shadow-sm border border-primary/20'
                : 'hover:bg-accent'
                }`}
        >
            {isEditing ? (
                // 内联编辑态
                <div className="flex items-center gap-1 px-2 py-2">
                    <input
                        ref={inputRef}
                        value={editValue}
                        onChange={(e) => setEditValue(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') commitRename();
                            if (e.key === 'Escape') cancelRename();
                        }}
                        className="flex-1 min-w-0 text-sm bg-background border border-primary/40 rounded px-2 py-1 focus:outline-none focus:ring-1 focus:ring-primary"
                        maxLength={40}
                    />
                    <button onClick={commitRename} className="p-1 text-primary hover:bg-primary/10 rounded" aria-label="确认">
                        <Check className="w-3.5 h-3.5" />
                    </button>
                    <button onClick={cancelRename} className="p-1 text-muted-foreground hover:bg-accent rounded" aria-label="取消">
                        <X className="w-3.5 h-3.5" />
                    </button>
                </div>
            ) : (
                // 正常显示态
                <button
                    onClick={onSelect}
                    className="w-full text-left px-3 py-2.5 pr-16"
                >
                    <div className="font-medium text-sm text-foreground truncate">
                        {session.title}
                    </div>
                    <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                        <span>{formatDate(session.updated_at)}</span>
                        <span>•</span>
                        <span>{session.message_count} 条消息</span>
                    </div>
                </button>
            )}

            {/* 操作按钮组（悬停显示） */}
            {!isEditing && (
                <div className="absolute right-1 top-1/2 -translate-y-1/2 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-all">
                    <button
                        aria-label="重命名会话"
                        onClick={(e) => {
                            e.stopPropagation();
                            setEditValue(session.title);
                            setIsEditing(true);
                        }}
                        className="p-1.5 rounded hover:bg-primary/10 text-muted-foreground hover:text-primary"
                    >
                        <Pencil className="w-3.5 h-3.5" />
                    </button>
                    <button
                        aria-label="删除会话"
                        onClick={(e) => {
                            e.stopPropagation();
                            if (confirm('确定要删除这个对话吗？')) {
                                onDelete();
                            }
                        }}
                        className="p-1.5 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive"
                    >
                        <Trash2 className="w-3.5 h-3.5" />
                    </button>
                </div>
            )}
        </div>
    );
}

export default function ChatSidebar({
    sessions,
    currentSessionId,
    onSessionSelect,
    onNewSession,
    onDeleteSession,
    onRenameSession,
    showFavorites,
    onToggleShowFavorites,
}: ChatSidebarProps) {
    const { t } = useTerminology();
    const [searchQuery, setSearchQuery] = useState('');
    const [isSearching, setIsSearching] = useState(false);
    const [searchResults, setSearchResults] = useState<any[]>([]);

    // 执行重命名（调用服务端 Action 并通知父组件）
    const handleRename = async (sessionId: number, newTitle: string) => {
        const result = await renameChatSessionAction(sessionId, newTitle);
        if (result.success && onRenameSession) {
            onRenameSession(sessionId, result.title ?? newTitle);
        }
    };

    return (
        <div className="w-64 h-full bg-sidebar border-r border-border flex flex-col">
            {/* 头部 */}
            <div className="p-4 border-b border-border space-y-3">
                <button
                    onClick={onNewSession}
                    className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-primary hover:bg-primary/90 text-primary-foreground rounded-lg font-medium transition-colors"
                >
                    <MessageSquarePlus className="w-4 h-4" />
                    {t('chat.new')}
                </button>

                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <input
                        type="text"
                        placeholder={t('chat.search')}
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-9 pr-3 py-2 bg-background border border-input rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all text-foreground placeholder:text-muted-foreground"
                    />
                    {isSearching && (
                        <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-3 h-3 text-primary animate-spin" />
                    )}
                </div>
            </div>

            {/* 收藏切换 */}
            <div className="px-4 pb-2 pt-2">
                <button
                    onClick={() => onToggleShowFavorites()}
                    className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${showFavorites
                        ? 'bg-yellow-50 text-yellow-700 border border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-400 dark:border-yellow-900'
                        : 'text-muted-foreground hover:bg-accent'
                        }`}
                >
                    <Star className={`w-4 h-4 ${showFavorites ? 'fill-yellow-500 text-yellow-500' : ''}`} />
                    {t('chat.favorites')}
                </button>
            </div>

            {/* 会话列表 */}
            <div className="flex-1 overflow-y-auto scrollbar-thin">
                {searchQuery ? (
                    // 搜索结果视图
                    <div className="p-2 space-y-1">
                        {searchResults.length === 0 && !isSearching ? (
                            <div className="text-center py-8 text-muted-foreground text-sm">
                                <p>未找到相关内容</p>
                            </div>
                        ) : (
                            searchResults.map((result) => (
                                <button
                                    key={result.messageId}
                                    onClick={() => onSessionSelect(result.sessionId, result.messageId)}
                                    className="w-full text-left p-3 rounded-lg hover:bg-accent transition-colors group"
                                >
                                    <div className="font-medium text-sm text-foreground mb-1 truncate">
                                        {result.sessionTitle}
                                    </div>
                                    <div className="text-xs text-muted-foreground line-clamp-2 leading-relaxed">
                                        <span className={`inline-block px-1.5 py-0.5 rounded mr-1 ${result.role === 'user' ? 'bg-primary/10 text-primary' : 'bg-green-500/10 text-green-600'
                                            }`}>
                                            {result.role === 'user' ? '问' : '答'}
                                        </span>
                                        {highlightText(result.content, searchQuery)}
                                    </div>
                                    <div className="mt-1 text-[10px] text-muted-foreground/70">
                                        {formatDate(result.created_at)}
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                ) : (
                    // 会话列表视图
                    <>
                        {(sessions.length === 0 && currentSessionId === null) ? (
                            <div className="flex flex-col items-center justify-center h-full text-muted-foreground px-4 text-center">
                                <MessageSquare className="w-12 h-12 mb-2 opacity-20" />
                                <p className="text-sm">{t('chat.empty')}</p>
                                <p className="text-xs mt-1">{t('chat.start_tip')}</p>
                            </div>
                        ) : (
                            <div className="p-2 space-y-1">
                                {/* 临时会话占位 */}
                                {currentSessionId === null && (
                                    <div className="bg-card shadow-sm border border-primary/20 rounded-lg p-3 mb-2 animate-pulse">
                                        <div className="font-medium text-sm text-primary">{t('chat.new')}...</div>
                                        <div className="text-[10px] text-muted-foreground mt-1">{t('chat.start_tip')}</div>
                                    </div>
                                )}
                                {sessions.map((session) => (
                                    <SessionItem
                                        key={session.id}
                                        session={session}
                                        isActive={currentSessionId === session.id}
                                        onSelect={() => onSessionSelect(session.id)}
                                        onDelete={() => onDeleteSession(session.id)}
                                        onRename={(newTitle) => handleRename(session.id, newTitle)}
                                    />
                                ))}
                            </div>
                        )}
                    </>
                )}
            </div>

