'use client';

import { motion } from 'framer-motion';

export function CultivationBackground() {
  return (
    <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
      {/* 渐变底底 */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.05)_0%,rgba(0,0,0,1)_80%)]" />
      
      {/* 飘动的灵气 */}
      {[...Array(6)].map((_, i) => (
        <motion.div
          key={i}
          className="absolute rounded-full bg-emerald-500/10 blur-[100px]"
          style={{
            width: Math.random() * 400 + 200,
            height: Math.random() * 400 + 200,
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
          }}
          animate={{
            x: [0, Math.random() * 100 - 50, 0],
            y: [0, Math.random() * 100 - 50, 0],
            scale: [1, 1.2, 1],
            opacity: [0.1, 0.2, 0.1],
          }}
          transition={{
            duration: Math.random() * 10 + 10,
            repeat: Infinity,
            ease: "linear",
          }}
        />
      ))}

      {/* 细微的星光点点 */}
      <div className="absolute inset-0 opacity-20">
        {[...Array(20)].map((_, i) => (
          <motion.div
            key={`star-${i}`}
            className="absolute w-1 h-1 bg-white rounded-full"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              opacity: [0.2, 0.8, 0.2],
              scale: [1, 1.5, 1],
            }}
            transition={{
              duration: Math.random() * 4 + 2,
              repeat: Infinity,
              ease: "easeInOut",
              delay: Math.random() * 5,
            }}
          />
        ))}
      </div>
      
      {/* 底部雾气 */}
      <div className="absolute bottom-0 left-0 right-0 h-96 bg-gradient-to-t from-black to-transparent opacity-60" />
    </div>
  );
}

'use client';

import { LeaderboardEntry } from '@/lib/cultivation/types';
import { motion } from 'framer-motion';
import { Trophy, Medal, Star } from 'lucide-react';

interface LeaderboardItemProps {
  entry: LeaderboardEntry;
  rank: number;
}

export function LeaderboardItem({ entry, rank }: LeaderboardItemProps) {
  const isTop3 = rank <= 3;
  
  // 决定颜色
  const getRankColor = () => {
    if (rank === 1) return 'text-amber-400';
    if (rank === 2) return 'text-zinc-300';
    if (rank === 3) return 'text-orange-400';
    return 'text-zinc-500';
  };

  const getRankIcon = () => {
    if (rank === 1) return <Trophy className="w-5 h-5 text-amber-400" />;
    if (rank === 2) return <Medal className="w-5 h-5 text-zinc-300" />;
    if (rank === 3) return <Medal className="w-5 h-5 text-orange-400" />;
    return <span className="text-sm font-bold opacity-40">{rank}</span>;
  };

  return (
    <motion.div
      initial={{ opacity: 0, x: -10 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay: rank * 0.05 }}
      className={`group flex items-center justify-between p-4 rounded-2xl border border-transparent hover:border-white/5 hover:bg-white/5 transition-all ${isTop3 ? 'bg-white/5' : ''}`}
    >
      <div className="flex items-center gap-4">
        {/* 排名 */}
        <div className="w-8 flex justify-center">
          {getRankIcon()}
        </div>
        
        {/* 道号与境界 */}
        <div className="flex flex-col">
          <span className={`font-bold ${isTop3 ? 'text-zinc-100' : 'text-zinc-400'}`}>
            {entry.username}
          </span>
          <div className="flex items-center gap-2">
             <span className="text-[10px] text-emerald-500 font-serif">
              {entry.cultivation.realm}
            </span>
            <span className="text-[10px] text-zinc-600">
              {entry.cultivation.stage}
            </span>
          </div>
        </div>
      </div>

      {/* 修为 */}
      <div className="flex flex-col items-end">
        <div className="flex items-center gap-1.5">
          <Star className="w-3 h-3 text-zinc-500" />
          <span className="text-sm font-serif text-zinc-300">{entry.totalPracticed}</span>
        </div>
        <span className="text-[10px] text-zinc-600 uppercase tracking-tighter">累计修为</span>
      </div>
    </motion.div>
  );
}

'use client';

