          />
        </div>
      </div>

      {/* 描述语 */}
      <p className="text-center text-zinc-400 text-sm leading-relaxed font-light min-h-[3rem]">
        {state.description}
      </p>

      {/*数据展示 */}
      <div className="grid grid-cols-2 gap-8 mt-10 w-full pt-8 border-t border-white/5">
        <div className="text-center">
          <div className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">累计修为</div>
          <div className="text-xl font-serif text-zinc-200">{state.total修为}</div>
        </div>
        <div className="text-center">
          <div className="text-xs text-zinc-500 font-bold uppercase tracking-wider mb-1">根基稳固</div>
          <div className="text-xl font-serif text-zinc-200">{state.mastery}%</div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { getKnowledgeTreeAction, KnowledgeParams } from "@/server/actions/practice";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Target, Loader2, ChevronRight, ChevronDown, Check, Folder, FileText } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

// 递归树节点组件
function TreeNode({
    node,
    level = 0,
    selectedTags,
    toggleTag
}: {
    node: KnowledgeParams;
    level?: number;
    selectedTags: string[];
    toggleTag: (tag: string) => void;
}) {
    const [expanded, setExpanded] = useState(false);
    const hasChildren = node.children && node.children.length > 0;
    const isSelected = selectedTags.includes(node.path);

    // 如果是叶子节点，默认总是展开（没子节点也不用展开）
    // 如果是父节点，点击可以折叠/展开

    return (
        <div className="select-none">
            <div
                className={cn(
                    "flex items-center gap-2 py-1.5 px-2 rounded-md transition-colors cursor-pointer text-sm",
                    isSelected ? "bg-primary/10 text-primary" : "hover:bg-accent text-foreground"
                )}
                style={{ paddingLeft: `${level * 16 + 8}px` }}
                onClick={(e) => {
                    e.stopPropagation();
                    if (hasChildren) {
                        setExpanded(!expanded);
                    } else {
                        toggleTag(node.path);
                    }
                }}
            >
                {/* 展开/折叠图标 (仅对有子节点的节点显示) */}
                <span
                    className={cn(
                        "w-4 h-4 flex items-center justify-center rounded-sm hover:bg-black/5 transition-colors",
                        hasChildren ? "opacity-100" : "opacity-0"
                    )}
                    onClick={(e) => {
                        e.stopPropagation();
                        setExpanded(!expanded);
                    }}
                >
                    {expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                </span>

                {/* 复选框/选择逻辑 */}
                <div
                    className={cn(
                        "w-4 h-4 rounded border flex items-center justify-center transition-all",
                        isSelected
                            ? "bg-primary border-primary text-primary-foreground"
                            : "border-border bg-card hover:border-primary/50"
                    )}
                    onClick={(e) => {
                        e.stopPropagation();
                        toggleTag(node.path);
                    }}
                >
                    {isSelected && <Check className="w-3 h-3" />}
                </div>

                {/* 图标与文本 */}
                <span className="flex items-center gap-2 flex-1">
                    {hasChildren ? (
                        <Folder className={cn("w-4 h-4", isSelected ? "text-primary" : "text-amber-400")} />
                    ) : (
                        <FileText className={cn("w-4 h-4", isSelected ? "text-primary" : "text-muted-foreground")} />
                    )}
                    <span className={cn("font-medium", isSelected && "text-primary")}>
                        {node.name}
                    </span>
                    <span className="text-xs text-muted-foreground ml-auto">
                        {node.count}题
                    </span>
                </span>
            </div>

            {hasChildren && expanded && (
                <div className="border-l border-border ml-5 my-1">
                    {node.children.map(child => (
                        <TreeNode
                            key={child.path}
                            node={child}
                            level={level + 1}
                            selectedTags={selectedTags}
                            toggleTag={toggleTag}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

export function KnowledgePointSelector({ children }: { children: React.ReactNode }) {
    const router = useRouter();
    const [open, setOpen] = useState(false);
    const [treeData, setTreeData] = useState<KnowledgeParams[]>([]);
    const [selectedTags, setSelectedTags] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (open && treeData.length === 0) {
            setLoading(true);
            getKnowledgeTreeAction()
                .then(setTreeData)
                .catch(() => toast.error("获取知识点失败"))
                .finally(() => setLoading(false));
        }
    }, [open, treeData.length]);

    const toggleTag = (path: string) => {
        setSelectedTags(prev =>
            prev.includes(path)
                ? prev.filter(t => t !== path)
                : [...prev, path]
        );
    };

    const handleStart = () => {
        if (selectedTags.length === 0) {
            toast.warning("请至少选择一个知识点");
            return;
        }
        setOpen(false);
        const params = new URLSearchParams({
            mode: 'focus',
            limit: '25',
            tags: selectedTags.join(',')
        });
        router.push(`/practice?${params.toString()}`);
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                {children}
            </DialogTrigger>
            <DialogContent className="sm:max-w-lg bg-white/95 backdrop-blur-xl border-white/20">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 font-serif text-xl">
                        <Target className="w-5 h-5 text-emerald-600" />
                        选择专项突破知识点
                    </DialogTitle>
                </DialogHeader>

                <div className="py-2">
                    {loading ? (
                        <div className="flex justify-center py-12">
                            <Loader2 className="w-8 h-8 animate-spin text-emerald-600" />
                        </div>
                    ) : (
                        <ScrollArea className="h-[400px] w-full rounded-xl border border-border bg-muted/30 p-2">
                            {treeData.length > 0 ? (
                                <div className="space-y-1">
                                    {treeData.map(node => (
                                        <TreeNode
                                            key={node.path}
                                            node={node}
                                            selectedTags={selectedTags}
                                            toggleTag={toggleTag}
                                        />
                                    ))}
                                </div>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-muted-foreground space-y-2 py-10">
                                    <Folder className="w-10 h-10 opacity-20" />
                                    <span>暂无知识点数据，请先导入教材</span>
                                </div>
                            )}
                        </ScrollArea>
                    )}
                </div>

                <div className="flex justify-between items-center pt-2">
                    <div className="text-xs text-muted-foreground">
                        已选 <span className="font-bold text-primary">{selectedTags.length}</span> 个考点
                    </div>
                    <Button
                        onClick={handleStart}
                        disabled={selectedTags.length === 0}
                        className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg shadow-primary/20 rounded-full px-6"
                    >
                        开始练习
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

/** @vitest-environment jsdom */
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import '@testing-library/jest-dom';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import React from 'react';
import { KnowledgePointSelector } from '../KnowledgePointSelector';
import { useRouter } from 'next/navigation';
import { getKnowledgeTreeAction } from '@/server/actions/practice';
import { toast } from 'sonner';

// Mock next/navigation
vi.mock('next/navigation', () => ({
    useRouter: vi.fn(),
}));

// Mock server actions
vi.mock('@/server/actions/practice', () => ({
    getKnowledgeTreeAction: vi.fn(),
}));

// Mock sonner
vi.mock('sonner', () => ({
    toast: {
        error: vi.fn(),
        warning: vi.fn(),
        success: vi.fn(),
    },
}));

const mockTreeData = [
    {
        name: '数学',
        path: 'math',
        count: 10,
        children: [
            { name: '代数', path: 'math/algebra', count: 5, children: [] },
            { name: '几何', path: 'math/geometry', count: 5, children: [] },
        ]
    },
    {
        name: '英语',
        path: 'english',
        count: 5,
        children: []
    }
];

describe('KnowledgePointSelector Component', () => {
    const mockPush = vi.fn();

    beforeEach(() => {
        vi.clearAllMocks();
        (useRouter as any).mockReturnValue({ push: mockPush });
        (getKnowledgeTreeAction as any).mockResolvedValue(mockTreeData);
    });

    it('opens dialog when trigger is clicked', async () => {
        render(
            <KnowledgePointSelector>
                <button>Open Selector</button>
            </KnowledgePointSelector>
        );

        const trigger = screen.getByText('Open Selector');
        fireEvent.click(trigger);

        expect(screen.getByText('选择专项突破知识点')).toBeInTheDocument();
        
        // Should show loading then data
        await waitFor(() => {
            expect(screen.getByText('数学')).toBeInTheDocument();
            expect(screen.getByText('英语')).toBeInTheDocument();
        });
    });

    it('toggles selection of knowledge points', async () => {
        render(
            <KnowledgePointSelector>
                <button>Open Selector</button>
            </KnowledgePointSelector>
        );

        fireEvent.click(screen.getByText('Open Selector'));

        await waitFor(() => screen.getByText('数学'));

        // Click '英语' node
        const englishNode = screen.getByText('英语');
        fireEvent.click(englishNode);

        expect(screen.getByText(/已选/)).toHaveTextContent('已选 1 个考点');

        // Click again to deselect
        fireEvent.click(englishNode);
        expect(screen.getByText(/已选/)).toHaveTextContent('已选 0 个考点');
    });

    it('navigates to practice page with correct params on start', async () => {
        render(
            <KnowledgePointSelector>
                <button>Open Selector</button>
            </KnowledgePointSelector>
        );

        fireEvent.click(screen.getByText('Open Selector'));
        await waitFor(() => screen.getByText('英语'));

        // Select '英语'
        fireEvent.click(screen.getByText('英语'));

        // Click '开始练习'
        const startBtn = screen.getByText('开始练习');
        fireEvent.click(startBtn);

        expect(mockPush).toHaveBeenCalledWith(
            expect.stringContaining('/practice?mode=focus&limit=25&tags=english')
        );
    });

    it('shows warning when starting without selection', async () => {
        render(
            <KnowledgePointSelector>
                <button>Open Selector</button>
            </KnowledgePointSelector>
        );

        fireEvent.click(screen.getByText('Open Selector'));
        await waitFor(() => screen.getByText('英语'));

        const startBtn = screen.getByText('开始练习');
        // '开始练习' button is disabled when selectedTags.length === 0 in the JSX
        // But the handleStart function also has a check. 
        // Let's check if the button is indeed disabled.
        expect(startBtn).toBeDisabled();
    });

    it('handles recursive expansion', async () => {
        render(
            <KnowledgePointSelector>
                <button>Open Selector</button>
            </KnowledgePointSelector>
        );

        fireEvent.click(screen.getByText('Open Selector'));
        await waitFor(() => screen.getByText('数学'));

        // '代数' should not be visible initially because '数学' is not expanded
        expect(screen.queryByText('代数')).not.toBeInTheDocument();

        // Click on the chevron/folder of '数学' to expand
        // The TreeNode handles expansion on click of the main div if it has children
        const mathNode = screen.getByText('数学');
        fireEvent.click(mathNode);

        expect(screen.getByText('代数')).toBeInTheDocument();
        expect(screen.getByText('几何')).toBeInTheDocument();
    });
});

'use client';

import {
    EditorCommand,
    EditorCommandEmpty,
    EditorCommandItem,
    EditorCommandList,
    EditorContent,
    type EditorInstance,
    EditorRoot,
    ImageResizer,
    type JSONContent,
    handleCommandNavigation,
    handleImageDrop,
    handleImagePaste,
} from 'novel';
import { useState, useRef, useEffect, useCallback } from 'react';
import { defaultExtensions } from './extensions';
import { slashCommand, suggestionItems } from './slash-command';
import { uploadFn } from './image-upload';
import { NodeSelector, LinkSelector, ColorSelector, TextButtons } from './selectors';
import { Separator } from '@/components/ui/separator';
import GenerativeMenuSwitch from './generative/generative-menu-switch';
import QuestionPicker from './QuestionPicker';

const extensions = [...defaultExtensions, slashCommand];

interface NoteEditorProps {
    initialContent?: string | null;
    onChange?: (content: string) => void;
}

export default function NoteEditor({ initialContent, onChange }: NoteEditorProps) {
    const [content, setContent] = useState<JSONContent | null>(() => {
        if (!initialContent) return null;
        try {
            return JSON.parse(initialContent);
        } catch (e) {
            // 兼容历史纯文本内容，转换为最小合法文档结构
            return {
                type: 'doc',
                content: [
                    {
                        type: 'paragraph',
                        content: [{ type: 'text', text: initialContent }],
                    },
                ],
            };
        }
    });
    const [saveStatus, setSaveStatus] = useState('已保存');

    // Bubble Menu 状态
    const [openNode, setOpenNode] = useState(false);
    const [openColor, setOpenColor] = useState(false);
    const [openLink, setOpenLink] = useState(false);
    const [openAI, setOpenAI] = useState(false);

    // QuestionPicker 状态
    const [showQuestionPicker, setShowQuestionPicker] = useState(false);
    const editorRef = useRef<EditorInstance | null>(null);

    // 处理插入题目引用
    const handleInsertQuestion = useCallback((questionId: number) => {
        if (editorRef.current) {
            editorRef.current
                .chain()
                .focus()
                .insertContent({
                    type: 'questionEmbed',
                    attrs: { questionId },
                })
                .run();
        }
    }, []);

    // 监听自定义事件以打开 QuestionPicker
    useEffect(() => {
        const handleOpenPicker = () => setShowQuestionPicker(true);
        window.addEventListener('open-question-picker', handleOpenPicker);
        return () => window.removeEventListener('open-question-picker', handleOpenPicker);
    }, []);

    // 防抖保存
    const handleUpdate = (editor: EditorInstance) => {
        editorRef.current = editor;
        setSaveStatus('保存中...');
        const json = editor.getJSON();

        if (onChange) {
            onChange(JSON.stringify(json));
        }

        setTimeout(() => setSaveStatus('已保存'), 500);
    };

    return (
        <div className="relative w-full max-w-screen-lg">
            {/* 保存状态指示器 */}
            <div className="flex absolute right-5 top-5 z-10 mb-5 gap-2">
                <div className="rounded-lg bg-accent px-2 py-1 text-sm text-muted-foreground">
                    {saveStatus}
                </div>
            </div>

            <EditorRoot>
                <EditorContent
                    initialContent={content || undefined}
                    extensions={extensions}
                    className="relative min-h-[500px] w-full max-w-screen-lg border-muted bg-background sm:mb-[calc(10vh)] sm:rounded-lg sm:border sm:shadow-lg"
                    editorProps={{
                        handleDOMEvents: {
                            keydown: (_view, event) => handleCommandNavigation(event),
                        },
                        handlePaste: (view, event) => handleImagePaste(view, event, uploadFn),
                        handleDrop: (view, event, _slice, moved) => handleImageDrop(view, event, moved, uploadFn),
                        attributes: {
                            class: 'prose prose-lg dark:prose-invert prose-headings:font-bold font-default focus:outline-none max-w-full p-8',
                        },
                    }}
                    onUpdate={({ editor }) => handleUpdate(editor)}
                    slotAfter={<ImageResizer />}
                >
                    {/* Slash Command 菜单 */}
                    <EditorCommand className="z-50 h-auto max-h-[330px] overflow-y-auto rounded-md border border-muted bg-background px-1 py-2 shadow-md transition-all">
                        <EditorCommandEmpty className="px-2 text-muted-foreground">
                            未找到匹配的命令
                        </EditorCommandEmpty>
                        <EditorCommandList>
                            {suggestionItems.map((item) => (
                                <EditorCommandItem
                                    value={item.title}
                                    onCommand={(val) => item.command?.(val)}
                                    className="flex w-full items-center space-x-2 rounded-md px-2 py-1 text-left text-sm hover:bg-accent aria-selected:bg-accent"
                                    key={item.title}
                                >
                                    <div className="flex h-10 w-10 items-center justify-center rounded-md border border-muted bg-background">
                                        {item.icon}
                                    </div>
                                    <div>
                                        <p className="font-medium">{item.title}</p>
                                        <p className="text-xs text-muted-foreground">{item.description}</p>
                                    </div>
                                </EditorCommandItem>
                            ))}
                        </EditorCommandList>
                    </EditorCommand>

                    {/* Generative Bubble Menu */}
                    <GenerativeMenuSwitch open={openAI} onOpenChange={setOpenAI}>
                        <Separator orientation="vertical" />
                        <NodeSelector open={openNode} onOpenChange={setOpenNode} />
                        <Separator orientation="vertical" />
                        <LinkSelector open={openLink} onOpenChange={setOpenLink} />
                        <Separator orientation="vertical" />
                        <TextButtons />
                        <Separator orientation="vertical" />
                        <ColorSelector open={openColor} onOpenChange={setOpenColor} />
                    </GenerativeMenuSwitch>
                </EditorContent>
            </EditorRoot>

            {/* 题目选择器弹窗 */}
            <QuestionPicker
                isOpen={showQuestionPicker}
                onClose={() => setShowQuestionPicker(false)}
                onSelect={handleInsertQuestion}
            />
        </div>
    );
}

