"use client";

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Highlighter, Underline, Waves, Copy } from 'lucide-react';
import { fetchJson, apiClient } from '@/lib/utils/api-client';

interface Annotation {
    id?: number;
    start: number;
    end: number;
    tag: 'highlight' | 'underline' | 'wavy';
    color?: string;
}

interface AnnotatableTextProps {
    text: string;
    questionId: number;
    className?: string;
}

// 标记类型配置
const TAG_STYLES: Record<string, { className: string; color: string }> = {
    highlight: { className: 'bg-yellow-200 dark:bg-yellow-500/40', color: '#FFE066' },
    underline: { className: 'underline decoration-blue-500 decoration-2', color: '#3B82F6' },
    wavy: { className: 'underline decoration-red-500 decoration-wavy decoration-2', color: '#EF4444' },
};

/**
 * 可标注文本组件
 * 支持划词后添加高亮、下划线、波浪线标记
 */
export function AnnotatableText({ text, questionId, className }: AnnotatableTextProps) {
    const queryClient = useQueryClient();
    const [annotations, setAnnotations] = useState<Annotation[]>([]);
    const [selection, setSelection] = useState<{ start: number; end: number } | null>(null);
    const [selectedText, setSelectedText] = useState<string>('');
    const [toolbarPosition, setToolbarPosition] = useState<{ x: number; y: number } | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const toolbarRef = useRef<HTMLDivElement>(null);

    // 使用 useQuery 加载标注数据，5 分钟缓存
    const { data: annotationData } = useQuery({
        queryKey: ['annotations', questionId],
        queryFn: () => fetchJson<{ annotations: any[] }>(`/api/annotations?questionId=${questionId}`),
        staleTime: 5 * 60 * 1000,
        enabled: !!questionId,
    });

    // 将查询结果同步到本地 state（因为增删操作需要乐观更新）
    useEffect(() => {
        if (annotationData?.annotations) {
            setAnnotations(annotationData.annotations.map((a: any) => ({
                id: a.id,
                start: a.start_offset,
                end: a.end_offset,
                tag: a.tag,
                color: a.color,
            })));
        }
    }, [annotationData]);

    // 处理文本选择
    const handleMouseUp = useCallback(() => {
        const windowSelection = window.getSelection();
        if (!windowSelection || windowSelection.isCollapsed) {
            setSelection(null);
            setSelectedText('');
            setToolbarPosition(null);
            return;
        }

        const range = windowSelection.getRangeAt(0);
        const container = containerRef.current;
        if (!container || !container.contains(range.commonAncestorContainer)) {
            return;
        }

        // 计算选区在文本中的偏移量
        const preSelectionRange = range.cloneRange();
        preSelectionRange.selectNodeContents(container);
        preSelectionRange.setEnd(range.startContainer, range.startOffset);
        const start = preSelectionRange.toString().length;
        const end = start + range.toString().length;

        if (start === end) {
            setSelection(null);
            setSelectedText('');
            setToolbarPosition(null);
            return;
        }

        setSelection({ start, end });
        setSelectedText(text.slice(start, end));

        // 设置工具栏位置
        const rect = range.getBoundingClientRect();
        setToolbarPosition({
            x: rect.left + rect.width / 2,
            y: rect.top - 10,
        });
    }, []);

    // 添加标注
    const addAnnotation = useCallback(async (tag: 'highlight' | 'underline' | 'wavy') => {
        if (!selection) return;

        const newAnnotation: Annotation = {
            start: selection.start,
            end: selection.end,
            tag,
            color: TAG_STYLES[tag].color,
        };

        // 保存到服务器
        try {
            const res = await apiClient.post('/api/annotations', {
                questionId,
                startOffset: selection.start,
                endOffset: selection.end,
                tag,
                color: TAG_STYLES[tag].color,
            });
            const data = await res.json() as { id: number };
            
            newAnnotation.id = data.id;
            setAnnotations(prev => [...prev, newAnnotation]);
            
            // 乐观更新后刷新缓存
            queryClient.invalidateQueries({ queryKey: ['annotations', questionId] });
        } catch (error) {
            console.error('保存标注失败:', error);
        }

        setSelection(null);
        setToolbarPosition(null);
        window.getSelection()?.removeAllRanges();
    }, [selection, questionId, queryClient]);

    // 删除标注
    const deleteAnnotation = useCallback(async (id: number) => {
        try {
            await apiClient.delete(`/api/annotations?id=${id}`);
            setAnnotations(prev => prev.filter(a => a.id !== id));
            // 关键：务必刷新 React Query 缓存，否则重新进入页面或触发更新时，旧数据会重新填充 state
            queryClient.invalidateQueries({ queryKey: ['annotations', questionId] });
        } catch (error) {
            console.error('删除标注失败:', error);
        }
    }, [queryClient, questionId]);

    // 点击外部关闭工具栏
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (toolbarRef.current && !toolbarRef.current.contains(e.target as Node)) {
                setSelection(null);
                setSelectedText('');
                setToolbarPosition(null);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // 渲染带标注的文本
    const renderAnnotatedText = () => {
        if (annotations.length === 0) {
            return text;
        }

        // 按起始位置排序
        const sorted = [...annotations].sort((a, b) => a.start - b.start);
        const parts: React.ReactNode[] = [];
        let lastEnd = 0;

        sorted.forEach((ann, idx) => {
            // 处理重叠情况：如果当前标注的开始位置早于上一个标注的结束位置，说明重叠
            // 我们目前简单处理：跳过重叠部分的绘制，优先保证文本在 UI 上不重复
            if (ann.start < lastEnd) {
                // 如果这个标注完全被上一个覆盖了，直接跳过
                if (ann.end <= lastEnd) return;
                
                // 如果只是部分重叠，目前暂时跳过整个标注，优先保证文本正确
                return; 
            }

            // 添加未标注部分
            if (ann.start > lastEnd) {
                parts.push(
                    <span key={`plain-${idx}`}>{text.slice(lastEnd, ann.start)}</span>
                );
            }

            // 添加标注部分
            const style = TAG_STYLES[ann.tag];
            parts.push(
                <span
                    key={`ann-${ann.id || idx}`}
                    className={`${style.className} cursor-pointer group relative`}
                    onClick={(e) => {
                        e.stopPropagation(); // 防止触发父容器的事件
                        e.preventDefault();
                        if (ann.id) deleteAnnotation(ann.id);
                    }}
                    title="点击删除标注"
                >
                    {text.slice(ann.start, ann.end)}
                </span>
            );

            lastEnd = ann.end;
        });

        // 添加剩余文本
        if (lastEnd < text.length) {
            parts.push(<span key="plain-last">{text.slice(lastEnd)}</span>);
        }

        return parts;
    };

    return (
        <div className="relative">
            {/* 文本内容 */}
            <div
                ref={containerRef}
                onMouseUp={handleMouseUp}
                onContextMenu={(e) => e.preventDefault()}
                className={`select-text leading-relaxed whitespace-pre-wrap ${className || ''}`}
            >
                {renderAnnotatedText()}
            </div>

            {/* 浮动工具栏 */}
            {toolbarPosition && (
                <div
                    ref={toolbarRef}
                    className="fixed z-50 bg-card border border-border rounded-lg shadow-lg p-1 flex gap-1 animate-in fade-in zoom-in-95 duration-150"
                    style={{
                        left: toolbarPosition.x,
                        top: toolbarPosition.y,
                        transform: 'translate(-50%, -100%)',
                    }}
                >
                    <button
                        onClick={() => addAnnotation('highlight')}
                        className="p-2 hover:bg-yellow-100 dark:hover:bg-yellow-500/20 rounded transition-colors"
                        title="高亮"
                    >
                        <Highlighter className="h-4 w-4 text-yellow-600" />
                    </button>
                    <button
                        onClick={() => addAnnotation('underline')}
                        className="p-2 hover:bg-blue-100 dark:hover:bg-blue-500/20 rounded transition-colors"
                        title="下划线"
                    >
                        <Underline className="h-4 w-4 text-blue-600" />
                    </button>
                    <button
                        onClick={() => addAnnotation('wavy')}
                        className="p-2 hover:bg-red-100 dark:hover:bg-red-500/20 rounded transition-colors"
                        title="波浪线"
                    >
                        <Waves className="h-4 w-4 text-red-500" />
                    </button>
                    <div className="w-px bg-border mx-0.5" />
                    <button
                        onClick={() => {
                            navigator.clipboard.writeText(selectedText);
                            setSelection(null);
                            setSelectedText('');
                            setToolbarPosition(null);
                            window.getSelection()?.removeAllRanges();
                        }}
                        className="p-2 hover:bg-muted rounded transition-colors"
                        title="复制"
                    >
                        <Copy className="h-4 w-4 text-muted-foreground" />
                    </button>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { getErrorMessage } from '@/lib/utils/error';
import { CheckCircle2, XCircle, BookOpen, ChevronDown, ChevronUp, BrainCircuit, Lightbulb, Loader2, Sparkles, RefreshCw } from 'lucide-react';
import { formatDuration, indexToLetter, cn } from '@/lib/utils/utils';
import { AnnotatableText } from './AnnotatableText';
import dynamic from 'next/dynamic';
const MarkdownViewer = dynamic(() => import('@/components/chat/MarkdownViewer'), { ssr: false });
import { generateMnemonicAction } from '@/server/actions/ai-mnemonic';
import { generateFirstPrinciplesAction } from '@/server/actions/ai';
import { toast } from 'sonner';
import { sanitizeHtml } from '@/lib/utils/security';
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

export interface QuestionLogData {
    questionId?: number;           // 题目 ID (用于标注持久化)
    questionContent: string;
    options: string[];
    correctAnswer: string;
    userAnswer: string;
    isCorrect: boolean;
    duration: number;
    tags: string[];
    source: string;
    explanation: string;
    correctRatio?: number | null;      // 全站正确率
    mostWrongAnswer?: string | null;   // 易错项
    reviewData?: any;
    aiMnemonic?: string | null;        // AI 助记
    material?: string | null;          // 材料内容（纯文本）
    materialHtml?: string | null;      // 材料内容（HTML）
}

interface QuestionCardProps {
    log: QuestionLogData;
    index: number;
    isExpanded: boolean;
    onToggle: () => void;
    refCallback?: (el: HTMLDivElement | null) => void;
}

/**
 * 解析答案字符串（兼容单选和多选）
 * 单选: "B" -> ["B"]
 * 多选 JSON: '["A","B"]' -> ["A", "B"]
 * 多选逗号分隔: "A,B,C" -> ["A", "B", "C"]
 */
export function parseAnswer(answer: string): string[] {
    if (!answer) return [];
    const trimmed = answer.trim();

    // 1. JSON 数组格式 '["A","B"]'
    if (trimmed.startsWith('[')) {
        try {
            const parsed = JSON.parse(trimmed);
            return Array.isArray(parsed) ? parsed : [answer];
        } catch {
            return [answer];
        }
    }

    // 2. 逗号分隔格式 'A,B,C' (多选题/不定项选择题)
    if (trimmed.includes(',')) {
        return trimmed.split(',').map(s => s.trim());
    }

    // 3. 单选题 / 判断题：单个值
    return [answer];
}

/**
 * 单个题目卡片组件
 * 包含：题目内容、选项、统计栏、解析区域、AI复盘
 */
export const QuestionCard = React.memo(({ log, index, isExpanded, onToggle, refCallback }: QuestionCardProps) => {
    // 第一性原理分析状态
    const [fpAnalysis, setFpAnalysis] = useState<string | null>(null);
    const [isLoadingFP, setIsLoadingFP] = useState(false);

    // AI 助记状态 (初始值来自服务端，如果为空则允许手动生成)
    const [mnemonic, setMnemonic] = useState<string | null>(log.aiMnemonic || null);
    const [isGeneratingMnemonic, setIsGeneratingMnemonic] = useState(false);

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    // 生成 AI 助记
    const handleGenerateMnemonic = async (force: boolean = false) => {
        if ((!force && mnemonic) || isGeneratingMnemonic || !log.questionId) return;

        setIsGeneratingMnemonic(true);
        try {
            const result = await generateMnemonicAction(String(log.questionId), force);
            if (!isMounted.current) return;
            
            if (result.success && result.content) {
                setMnemonic(result.content);
                if (!result.cached) {
                    toast.success(force ? '重新生成成功！' : '记忆口诀生成成功！');
                }
            } else {
                toast.error(result.message || '生成失败');
            }
        } catch (error) {
            console.error('助记生成失败:', error);
            if (isMounted.current) toast.error('请求出错，请稍后重试');
        } finally {
            if (isMounted.current) setIsGeneratingMnemonic(false);
        }
    };

    // 获取第一性原理分析
    const handleFirstPrinciples = async (force: boolean = false) => {
        if ((!force && fpAnalysis) || isLoadingFP) return; // 已有结果且不强制重新生成，或正在加载

        setIsLoadingFP(true);

        try {
            const result = await generateFirstPrinciplesAction(
                log.questionContent,
                log.explanation,
                log.correctAnswer,
                log.isCorrect ? undefined : log.userAnswer,
                force // 传递 force 参数
            );
            if (!isMounted.current) return;
            
            setFpAnalysis(result.analysis);
            if (force && !result.cached) {
                toast.success('重新解析成功！');
            }
        } catch (error: unknown) {
            console.error('第一性原理分析失败:', error);
            if (isMounted.current) toast.error(getErrorMessage(error, '分析失败，请稍后重试'));
        } finally {
            if (isMounted.current) setIsLoadingFP(false);
        }
    };

    const hasMaterial = !!log.materialHtml;

    return (
        <div
            ref={refCallback}
            className="bg-card rounded-2xl shadow-sm border border-border overflow-hidden scroll-mt-24 md:scroll-mt-20"
            style={{ contentVisibility: 'auto', containIntrinsicSize: '0 300px' }}
        >
            <div className={`flex flex-col md:flex-row ${hasMaterial ? 'md:h-[600px]' : ''}`}>

                {/* 左侧：材料区域 (仅当有材料时显示) */}
                {hasMaterial && (
                    <div className="md:w-1/2 p-5 border-b md:border-b-0 md:border-r border-border bg-muted/10 overflow-auto scrollbar-thin">
                        <div className="sticky top-0 z-10 mb-4">
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300">
                                材料
                            </span>
                        </div>
                        <div
                            className="prose prose-sm dark:prose-invert max-w-none text-foreground leading-relaxed"
                            dangerouslySetInnerHTML={{ __html: sanitizeHtml(log.materialHtml || '') }}
                        />
                    </div>
                )}

                {/* 右侧：题目与交互区域 (如果有材料，宽度为 1/2，否则占满) */}
                <div className={`flex flex-col ${hasMaterial ? 'md:w-1/2 md:h-full md:overflow-auto scrollbar-thin' : 'w-full'}`}>
                    {/* 题目头部 */}
                    <div className={`p-5 flex-1 ${log.isCorrect ? 'border-l-4 border-l-green-500' : 'border-l-4 border-l-red-500'}`}>
                        <div className="flex items-start gap-3">
                            <div className="flex items-center gap-2 flex-shrink-0">
                                <span className="text-sm font-bold text-muted-foreground">{index + 1}.</span>
                                {log.isCorrect ? (
                                    <CheckCircle2 className="h-5 w-5 text-green-500" />
                                ) : (
                                    <XCircle className="h-5 w-5 text-red-500" />
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                {/* 题干内容 */}
                                <div
                                    className="font-medium text-foreground leading-relaxed"
                                    dangerouslySetInnerHTML={{ __html: sanitizeHtml(log.questionContent) }}
                                />

                                {/* 选项列表 */}
                                {log.options.length > 0 && (
                                    <div className="mt-3 space-y-2">
                                        {log.options.map((opt, oi) => {
                                            const letter = indexToLetter(oi);
                                            const correctAnswers = parseAnswer(log.correctAnswer);
                                            const userAnswers = parseAnswer(log.userAnswer);
                                            const isCorrectOption = correctAnswers.includes(letter);
                                            const isUserChoice = userAnswers.includes(letter) || userAnswers.includes(opt);

                                            return (
                                                <div
                                                    key={oi}
                                                    className={`flex items-start gap-2 p-2 rounded-lg text-sm ${isCorrectOption
                                                        ? 'bg-green-500/10 text-green-700 dark:text-green-400'
                                                        : isUserChoice && !log.isCorrect
                                                            ? 'bg-red-500/10 text-red-700 dark:text-red-400'
                                                            : 'text-muted-foreground'
                                                        }`}
                                                >
                                                    <span className={`w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 ${isCorrectOption
                                                        ? 'bg-green-500 text-white'
                                                        : isUserChoice && !log.isCorrect
                                                            ? 'bg-red-500 text-white'
                                                            : 'bg-muted text-muted-foreground'
                                                        }`}>
                                                        {letter}
                                                    </span>
                                                    <span>{opt}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* 统计栏 */}
                        <div className="mt-6 pt-4 border-t border-border">
                            <div className="grid grid-cols-3 md:grid-cols-5 gap-2 md:gap-4 text-center">
                                <div>
                                    <div className="text-base md:text-lg font-bold text-green-600">
                                        {parseAnswer(log.correctAnswer).join(', ') || '-'}
                                    </div>
                                    <div className="text-[10px] text-muted-foreground">正确答案</div>
                                </div>
                                <div>
                                    <div className={cn("text-base md:text-lg font-bold", log.isCorrect ? "text-green-600" : "text-rose-500")}>
                                        {parseAnswer(log.userAnswer).join(', ') || '未作答'}
                                    </div>
                                    <div className="text-[10px] text-muted-foreground">你的答案</div>
                                </div>
                                {log.correctRatio != null && (
                                    <div>
                                        <div className="text-base md:text-lg font-bold text-purple-600">
                                            {log.correctRatio}%
                                        </div>
                                        <div className="text-[10px] text-muted-foreground">正确率</div>
                                    </div>
                                )}
                                <div>
                                    <div className="text-base md:text-lg font-bold text-blue-600">
                                        {formatDuration(log.duration)}
                                    </div>
                                    <div className="text-[10px] text-muted-foreground">用时</div>
                                </div>
                                {log.mostWrongAnswer && (
                                    <div>
                                        <div className="text-base md:text-lg font-bold text-amber-600">
                                            {log.mostWrongAnswer}
                                        </div>
                                        <div className="text-[10px] text-muted-foreground">易错项</div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* 展开按钮 */}
                        <button
                            onClick={onToggle}
                            className="mt-4 w-full flex items-center justify-center gap-1 text-sm text-muted-foreground hover:text-primary transition-colors py-2 border border-border/50 rounded-lg hover:bg-muted/50"
                        >
                            {isExpanded ? (
                                <>收起详情 <ChevronUp className="h-4 w-4" /></>
                            ) : (
                                <>查看解析 <ChevronDown className="h-4 w-4" /></>
                            )}
                        </button>
                    </div>

                    {/* 展开的详情区域 */}
                    {isExpanded && (
                        <div className="border-t border-border">
                            {/* 第一性原理分析 */}
                            <div className="p-5 bg-gradient-to-r from-amber-500/5 to-orange-500/5 border-b border-amber-500/10">
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-2 text-amber-700 dark:text-amber-400 font-bold text-sm">
                                        <Lightbulb className="h-4 w-4" />
                                        第一性原理
                                    </div>
                                    {!fpAnalysis && (
                                        <button
                                            onClick={() => handleFirstPrinciples(false)}
                                            disabled={isLoadingFP}
                                            className="px-3 py-1.5 text-xs font-medium bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-400 rounded-full border border-amber-500/20 transition-colors disabled:opacity-50 flex items-center gap-1.5"
                                        >
                                            {isLoadingFP ? (
                                                <>
                                                    <Loader2 className="h-3 w-3 animate-spin" />
                                                    分析中...
                                                </>
                                            ) : (
                                                '一键解析'
                                            )}
                                        </button>
                                    )}
                                    {fpAnalysis && (
                                        <button
                                            onClick={() => handleFirstPrinciples(true)}
                                            disabled={isLoadingFP}
                                            className="p-1.5 text-amber-400 hover:text-amber-600 dark:hover:text-amber-300 transition-colors disabled:opacity-50"
                                            title="重新解析"
                                        >
                                            <RefreshCw className={`h-4 w-4 ${isLoadingFP ? 'animate-spin' : ''}`} />
                                        </button>
                                    )}
                                </div>

                                {fpAnalysis ? (
                                    <div className="bg-card p-4 rounded-xl border border-amber-500/20 shadow-sm">
                                        {log.questionId ? (
                                            <AnnotatableText
                                                text={fpAnalysis}
                                                questionId={-log.questionId}
                                                className="text-sm text-foreground"
                                            />
                                        ) : (
                                            <div className="text-sm text-foreground leading-relaxed whitespace-pre-wrap">
                                                {fpAnalysis}
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    <div className="text-xs text-muted-foreground">
                                        点击上方按钮，AI 将用底层逻辑为你解析这道题（≤200字）
                                    </div>
                                )}
                            </div>

                            {/* 解析 */}
                            {log.explanation && (
                                <div className="p-5 bg-blue-500/5">
                                    <div className="flex items-center gap-2 mb-3 text-blue-700 dark:text-blue-400 font-bold text-sm">
                                        <BookOpen className="h-4 w-4" />
                                        详细解析
                                    </div>
                                    {log.questionId ? (
                                        <AnnotatableText
                                            text={log.explanation}
                                            questionId={log.questionId}
                                            className="text-sm text-foreground"
                                        />
                                    ) : (
                                        <div className="text-sm text-foreground leading-relaxed whitespace-pre-wrap">
                                            {log.explanation}
                                        </div>
                                    )}
                                </div>
                            )}

                            {/* AI 助记大师 */}
                            <div className="p-5 bg-purple-500/5 border-t border-purple-500/10">
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-2 text-purple-700 dark:text-purple-400 font-bold text-sm">
                                        <Sparkles className="h-4 w-4" />
                                        AI 记忆大师
                                    </div>
                                    {!mnemonic && log.questionId && (
                                        <button
                                            onClick={() => handleGenerateMnemonic(false)}
                                            disabled={isGeneratingMnemonic}
                                            className="px-3 py-1.5 text-xs font-medium bg-purple-500/10 hover:bg-purple-500/20 text-purple-700 dark:text-purple-400 rounded-full border border-purple-500/20 transition-colors disabled:opacity-50 flex items-center gap-1.5"
                                        >
                                            {isGeneratingMnemonic ? (
                                                <>
                                                    <Loader2 className="h-3 w-3 animate-spin" />
                                                    生成中...
                                                </>
                                            ) : (
                                                '生成记忆口诀'
                                            )}
                                        </button>
                                    )}

                                    {mnemonic && log.questionId && (
                                        <button
                                            onClick={() => handleGenerateMnemonic(true)}
                                            disabled={isGeneratingMnemonic}
                                            className="p-1.5 text-purple-400 hover:text-purple-600 dark:hover:text-purple-300 transition-colors disabled:opacity-50"
                                            title="重新生成"
                                        >
                                            <RefreshCw className={`h-4 w-4 ${isGeneratingMnemonic ? 'animate-spin' : ''}`} />
                                        </button>
                                    )}
                                </div>

                                {mnemonic ? (
                                        <MarkdownViewer content={mnemonic} />
                                ) : (
                                    <div className="text-xs text-muted-foreground">
                                        遇到难记的知识点？点击按钮，AI 为你生成趣味口诀和脑洞联想。
                                    </div>
                                )}
                            </div>

                            {/* 考点和来源 */}
                            <div className="p-5 bg-muted/30 space-y-3">
                                {log.tags.length > 0 && (
                                    <div>
                                        <div className="text-xs font-bold text-muted-foreground mb-2">考点</div>
                                        <div className="flex flex-wrap gap-2">
                                            {log.tags.map((tag, i) => {
                                                const parts = tag.split('/');
                                                const leaf = parts[parts.length - 1];
                                                const fullPath = parts.join(' > ');

                                                return (
                                                    <TooltipProvider key={i}>
                                                        <Tooltip delayDuration={300}>
                                                            <TooltipTrigger asChild>
                                                                <span className="px-3 py-1 bg-primary/10 text-primary text-sm font-medium rounded-full cursor-help hover:bg-primary/20 transition-colors">
                                                                    {leaf}
                                                                </span>
                                                            </TooltipTrigger>
                                                            <TooltipContent>
                                                                <p className="text-xs">{fullPath}</p>
                                                            </TooltipContent>
                                                        </Tooltip>
                                                    </TooltipProvider>
                                                );
                                            })}
                                        </div>
                                    </div>
                                )}
                                {log.source && (
                                    <div>
                                        <div className="text-xs font-bold text-muted-foreground mb-1">来源</div>
                                        <div className="text-sm text-blue-600 dark:text-blue-400">
                                            {log.source}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* AI复盘 */}
                            {log.reviewData && (
                                <div className="p-5 bg-amber-500/5 border-t border-amber-500/20">
                                    <div className="flex items-center gap-2 mb-3 text-amber-700 dark:text-amber-300 font-bold text-sm">
                                        <BrainCircuit className="h-4 w-4" />
                                        AI 复盘档案
                                    </div>

                                    {log.reviewData.quiz && (
                                        <div className="mb-4">
                                            <div className="text-xs font-bold text-amber-700 dark:text-amber-400 mb-1">纠偏找茬变式</div>
                                            <div className="text-sm text-foreground bg-card p-3 rounded-xl border border-amber-500/20 shadow-sm">
                                                {log.reviewData.quiz.quiz.content}
                                            </div>
                                        </div>
                                    )}

                                    {log.reviewData.regression && (
                                        <div>
                                            <div className="text-xs font-bold text-purple-700 dark:text-purple-400 mb-1">回归挑战变式</div>
                                            <div className="space-y-2">
                                                {log.reviewData.regression.challenges.map((c: any, ci: number) => (
                                                    <div key={ci} className="text-sm text-foreground bg-card p-3 rounded-xl border border-purple-500/20 shadow-sm">
                                                        {c.content}
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
});

"use client";

import React from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { usePathname } from 'next/navigation';
import { motion } from 'framer-motion';
import {
    BookOpen,
    LayoutDashboard,
    Settings,
    Home,
    History,
    Bot,
    Bookmark,
    BookX,
    FileText,
    Book,
    Sparkles,
    ChevronsUpDown,
    Palette,
    Moon,
    Sun,
    Eye,
    Monitor,
    ScanLine,
    Network
} from 'lucide-react';
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { useTerminology } from "@/lib/hooks/use-terminology";

interface SidebarProps {
    userSection?: React.ReactNode;
}

// --- Helper Components Moved Outside to Avoid Remounting ---
const NavGroup = ({
    title,
    items,
    pathname
}: {
    title?: string,
    items: { name: string, href: string, icon: React.ComponentType<{ className?: string }> }[],
    pathname: string
}) => (
    <div className="mb-6">
        {title && (
            <h3 className="px-4 mb-2 text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                {title}
            </h3>
        )}
        <div className="space-y-1">
            {items.map((item) => {
                const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`);
                return (
                    <Link
                        key={item.href}
                        href={item.href}
                        className={cn(
                            "flex items-center gap-3 px-3 py-2 mx-2 rounded-lg text-sm font-medium transition-colors group relative",
                            isActive
                                ? "text-primary dark:text-primary-foreground"
                                : "text-muted-foreground hover:bg-accent hover:text-foreground"
                        )}
                    >
                        {isActive && (
                            <motion.div
                                layoutId="sidebar-active-pill"
                                initial={false}
                                className="absolute inset-0 bg-primary/10 dark:bg-primary/20 rounded-lg -z-10"
                                transition={{
                                    type: "spring",
                                    stiffness: 450, // 增加刚度，使其移动更平衡
                                    damping: 35,    // 调整阻尼，减少回弹感
                                    mass: 0.8       // 减小质量，响应更快
                                }}
                            />
                        )}
                        <item.icon className={cn(
                            "h-4 w-4 transition-colors",
                            isActive ? "text-primary" : "text-muted-foreground group-hover:text-foreground"
                        )} />
                        <span>{item.name}</span>
                        {isActive && <div className="ml-auto w-1 h-1 rounded-full bg-primary" />}
                    </Link>
                );
            })}
        </div>
    </div>
);

export function AppSidebar({ userSection }: SidebarProps) {
    const pathname = usePathname();
    const { t } = useTerminology();

    // Hide sidebar on landing page, login, and register
    if (pathname === '/' || pathname === '/login' || pathname === '/register') {
        return null;
    }

    const mainNavItems = [
        { name: t('nav.home'), href: '/dashboard', icon: Home },
        { name: t('nav.practice'), href: '/practice', icon: BookOpen },
        { name: t('nav.wrong_book'), href: '/wrong-book', icon: BookX },
        { name: t('nav.history'), href: '/history', icon: History },
    ];

    const knowledgeItems = [
        { name: t('nav.ai_tutor'), href: '/chat', icon: Bot },
        { name: t('nav.knowledge'), href: '/knowledge', icon: Bookmark },
        { name: t('nav.textbooks'), href: '/textbooks', icon: Book },
        { name: t('nav.graph'), href: '/knowledge-graph', icon: LayoutDashboard },
    ];

    const moreItems = [
        { name: t('nav.ocr'), href: '/ocr', icon: ScanLine },
        { name: t('nav.mindmap'), href: '/mindmap', icon: Network },
    ];

    const systemItems = [
        { name: t('nav.docs'), href: '/docs', icon: FileText },
        { name: t('nav.pricing'), href: '/pricing', icon: Sparkles },
        { name: t('nav.settings'), href: '/settings', icon: Settings },
    ];

    return (
        <aside className="hidden md:flex w-64 flex-col border-r border-sidebar-border bg-sidebar h-screen sticky top-0 overflow-hidden font-sans">
            {/* Logo Area */}
            <div className="h-16 flex items-center px-6 border-b border-sidebar-border">
                <Link href="/" className="flex items-center gap-2 group">
                    <div className="relative w-7 h-7">
                        <Image src="/logo.png" alt="琢玉 Logo" width={28} height={28} className="object-contain group-hover:scale-110 transition-transform" />
                    </div>
                    <span className="font-bold text-lg bg-gradient-to-r from-emerald-700 to-teal-700 bg-clip-text text-transparent font-serif md:dark:from-emerald-400 md:dark:to-teal-400">
                        琢玉
                    </span>
                </Link>
            </div>

            {/* Main Navigation */}
            <ScrollArea className="flex-1 py-6 scrollbar-thin">
                <NavGroup title={t('section.start')} items={mainNavItems} pathname={pathname} />
                <NavGroup title={t('section.knowledge')} items={knowledgeItems} pathname={pathname} />
                <NavGroup title={t('section.more')} items={moreItems} pathname={pathname} />
                <NavGroup title={t('section.system')} items={systemItems} pathname={pathname} />
            </ScrollArea>

            {/* Footer / User Profile Slot */}
            {userSection}
        </aside>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Tag, Plus, X, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Badge } from '@/components/ui/badge';
import {
    getTagsAction,
    createTagAction,
    getNoteTagsAction,
    setNoteTagsAction,
} from '@/server/actions/note-tag';
import { TAG_COLORS, type NoteTag } from '@/lib/types/note-tag';
import { toast } from 'sonner';

interface TagSelectorProps {
    noteId: number;
    onTagsChange?: (tags: NoteTag[]) => void;
}

export function TagSelector({ noteId, onTagsChange }: TagSelectorProps) {
    const [allTags, setAllTags] = useState<NoteTag[]>([]);
    const [selectedTagIds, setSelectedTagIds] = useState<Set<number>>(new Set());
    const [isOpen, setIsOpen] = useState(false);
    const [newTagName, setNewTagName] = useState('');
    const [isCreating, setIsCreating] = useState(false);

    // 加载所有标签和当前笔记的标签
    useEffect(() => {
        const loadTags = async () => {
            const [allResult, noteResult] = await Promise.all([
                getTagsAction(),
                getNoteTagsAction(noteId)
            ]);

            if (allResult.success && allResult.tags) {
                setAllTags(allResult.tags);
            }
            if (noteResult.success && noteResult.tags) {
                setSelectedTagIds(new Set(noteResult.tags.map(t => t.id)));
                onTagsChange?.(noteResult.tags);
            }
        };
        loadTags();
    }, [noteId, onTagsChange]);

    // 切换标签选中状态
    const toggleTag = async (tagId: number) => {
        const newSelected = new Set(selectedTagIds);
        if (newSelected.has(tagId)) {
            newSelected.delete(tagId);
        } else {
            newSelected.add(tagId);
        }

        setSelectedTagIds(newSelected);

        const result = await setNoteTagsAction(noteId, Array.from(newSelected));
        if (result.success) {
            const selectedTags = allTags.filter(t => newSelected.has(t.id));
            onTagsChange?.(selectedTags);
        } else {
            toast.error(result.message || '设置标签失败');
            // 回滚
            setSelectedTagIds(selectedTagIds);
        }
    };

    // 创建新标签
    const handleCreateTag = async () => {
        if (!newTagName.trim()) return;

        setIsCreating(true);
        const result = await createTagAction(newTagName.trim());

        if (result.success && result.tagId) {
            // 刷新标签列表
            const tagsResult = await getTagsAction();
            if (tagsResult.success && tagsResult.tags) {
                setAllTags(tagsResult.tags);
            }
            setNewTagName('');
            toast.success('标签已创建');
        } else {
            toast.error(result.message || '创建失败');
        }
        setIsCreating(false);
    };

    const selectedTags = allTags.filter(t => selectedTagIds.has(t.id));

    return (
        <div className="flex items-center gap-2 flex-wrap">
            {/* 已选中的标签 */}
            {selectedTags.map(tag => (
                <Badge
                    key={tag.id}
                    variant="secondary"
                    className="gap-1 pr-1"
                    style={{ backgroundColor: tag.color + '20', color: tag.color, borderColor: tag.color }}
                >
                    {tag.name}
                    <button
                        onClick={() => toggleTag(tag.id)}
                        className="ml-1 rounded-full hover:bg-black/10 p-0.5"
                    >
                        <X className="w-3 h-3" />
                    </button>
                </Badge>
            ))}

            {/* 添加标签按钮 */}
            <Popover open={isOpen} onOpenChange={setIsOpen}>
                <PopoverTrigger asChild>
                    <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-muted-foreground">
                        <Tag className="w-3 h-3" />
                        <Plus className="w-3 h-3" />
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="w-64 p-2" align="start">
                    {/* 创建新标签 */}
                    <div className="flex gap-1 mb-2">
                        <Input
                            placeholder="新建标签..."
                            value={newTagName}
                            onChange={(e) => setNewTagName(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleCreateTag()}
                            className="h-8 text-sm"
                        />
                        <Button
                            size="sm"
                            className="h-8 px-2"
                            onClick={handleCreateTag}
                            disabled={isCreating || !newTagName.trim()}
                        >
                            <Plus className="w-4 h-4" />
                        </Button>
                    </div>

                    {/* 标签列表 */}
                    <div className="max-h-48 overflow-y-auto space-y-1">
                        {allTags.length === 0 && (
                            <p className="text-sm text-muted-foreground text-center py-2">
                                暂无标签，创建一个吧
                            </p>
                        )}
                        {allTags.map(tag => (
                            <button
                                key={tag.id}
                                onClick={() => toggleTag(tag.id)}
                                className="w-full flex items-center justify-between p-1.5 rounded hover:bg-muted text-sm"
                            >
                                <span className="flex items-center gap-2">
                                    <span
                                        className="w-3 h-3 rounded-full"
                                        style={{ backgroundColor: tag.color }}
                                    />
                                    {tag.name}
                                </span>
                                {selectedTagIds.has(tag.id) && (
                                    <Check className="w-4 h-4 text-primary" />
                                )}
                            </button>
                        ))}
                    </div>
                </PopoverContent>
            </Popover>
        </div>
    );
}

'use client';

import React, { useEffect, useRef } from 'react';
import { Transformer } from 'markmap-lib';
import { Markmap } from 'markmap-view';
import { Toolbar } from 'markmap-toolbar';
import { Download, Code, FileImage, Save } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import 'markmap-toolbar/dist/style.css';
import { createNoteAction } from '@/server/actions/note';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';

export interface MarkmapViewerProps {
    markdown: string;
    className?: string;
    fileName?: string;
}

const transformer = new Transformer();

export function MarkmapViewer({ markdown, className = '', fileName = '' }: MarkmapViewerProps) {
    const router = useRouter();
    const svgRef = useRef<SVGSVGElement>(null);
    const mmRef = useRef<Markmap | null>(null);
    const toolbarRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!svgRef.current) return;

        // 1. 解析 Markdown 获取 node 结构
        const { root, features } = transformer.transform(markdown);

        // 2. 初始化或更新 Markmap 实例
        if (mmRef.current) {
            mmRef.current.setData(root);
            mmRef.current.fit();
        } else {
            const mm = Markmap.create(svgRef.current, {
                // 可在此处调整导图颜色、间距等
                color: (node: { state?: { depth?: number } }) => {
                    // 简单的按层级给颜色，或者返回一个固定数组
                    const colors = ['#3b82f6', '#10b981', '#8b5cf6', '#f59e0b', '#ec4899'];
                    const depth = node.state?.depth ?? 0;
                    return colors[depth % colors.length];
                },
                // 为了避免过密，增加一点间距
                nodeMinHeight: 20,
                spacingHorizontal: 80,
                spacingVertical: 8,
            }, root);
            mmRef.current = mm;

            // 3. 挂载 Toolbar（仅挂载一次）
            if (toolbarRef.current) {
                const toolbar = new Toolbar();
                toolbar.attach(mm);
                toolbar.setItems([...Toolbar.defaultItems]);
                toolbarRef.current.appendChild(toolbar.render());
            }
        }
    }, [markdown]);

    // 下载为交互式 HTML (推荐，样式最完整且支持交互)
    const handleDownloadHtml = () => {
        const { root } = transformer.transform(markdown);
        const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>知识点思维导图</title>
<style>
* { margin: 0; padding: 0; }
body { font-family: sans-serif; }
#mindmap { display: block; width: 100vw; height: 100vh; }
</style>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/markmap-toolbar@0.17.0/dist/style.css">
</head>
<body>
<svg id="mindmap"></svg>
<script src="https://cdn.jsdelivr.net/npm/d3@7.8.5/dist/d3.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/markmap-view@0.17.0/dist/browser/index.js"></script>
<script src="https://cdn.jsdelivr.net/npm/markmap-toolbar@0.17.0/dist/browser/index.js"></script>
<script>
  // 注入数据
  const markmapData = ${JSON.stringify(root)};
  
  // 渲染
  const { Markmap, loadCSS, loadJS } = window.markmap;
  const mm = Markmap.create('svg#mindmap', {
      color: (node) => {
          const colors = ['#3b82f6', '#10b981', '#8b5cf6', '#f59e0b', '#ec4899'];
          return colors[node.depth % colors.length];
      },
      nodeMinHeight: 20,
      spacingHorizontal: 80,
      spacingVertical: 8,
  }, markmapData);
  
  // 工具栏
  const { Toolbar } = window.markmap;
  const toolbar = new Toolbar();
  toolbar.attach(mm);
  toolbar.setItems([...Toolbar.defaultItems]);
  const el = toolbar.render();
  el.style.position = 'absolute';
  el.style.bottom = '1rem';
  el.style.right = '1rem';
  document.body.append(el);
</script>
</body>
</html>`;
        const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = '思维导图_交互网页版.html';
        a.click();
        URL.revokeObjectURL(url);
    };

    // 下载为静态 SVG 图片
    const handleDownloadSvg = () => {
        if (!svgRef.current) return;
        // 获取 SVG 内容并加上 XML 命名空间
        const svgClone = svgRef.current.cloneNode(true) as SVGSVGElement;
        svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
        const svgData = new XMLSerializer().serializeToString(svgClone);
        const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = '思维导图.svg';
        a.click();
        URL.revokeObjectURL(url);
    };

    // 保存到我的笔记的云端数据库
    const handleSaveToNote = async () => {
        const title = fileName ? `${fileName.replace(/\.[^/.]+$/, "")} (导图)` : '未命名思维导图';
        const loadingToast = toast.loading('正在保存中...');
        try {
            const result = await createNoteAction({ title, content: markdown });
            if (result.success && result.noteId) {
                toast.success('已保存到我的笔记', { 
                    id: loadingToast,
                    action: {
                        label: '前往查看',
                        onClick: () => router.push(`/notes/${result.noteId}`)
                    }
                });
            } else {
                toast.error(result.message || '保存失败', { id: loadingToast });
            }
        } catch (error) {
            toast.error('保存过程中出错', { id: loadingToast });
        }
    };

    return (
        <div className={`relative w-full h-full min-h-[500px] bg-background border border-border rounded-xl flex flex-col overflow-hidden ${className}`}>
            {/* 顶部工具栏：下载选项 */}
            <div className="absolute top-4 right-4 z-10 flex gap-2">
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button variant="outline" size="sm" className="h-9 shadow-sm bg-background/80 backdrop-blur-md">
                            <Download className="w-4 h-4 mr-2" />
                            保存导出
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={handleSaveToNote} className="cursor-pointer mb-1 bg-primary/5">
                            <Save className="w-4 h-4 mr-2 text-primary" />
                            <div className="flex flex-col">
                                <span className="font-medium">保存到我的笔记</span>
                                <span className="text-[10px] text-muted-foreground mt-0.5">云端存储，跨端同步，可在笔记库回顾</span>
                            </div>
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={handleDownloadHtml} className="cursor-pointer">
                            <Code className="w-4 h-4 mr-2 text-primary" />
                            <div className="flex flex-col">
                                <span>交互式网页 (.html)</span>
                                <span className="text-[10px] text-muted-foreground mt-0.5">推荐：可展开折叠，保留所有功能</span>
                            </div>
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={handleDownloadSvg} className="cursor-pointer mt-1">
                            <FileImage className="w-4 h-4 mr-2 text-emerald-500" />
                            <div className="flex flex-col">
                                <span>静态矢量图 (.svg)</span>
                                <span className="text-[10px] text-muted-foreground mt-0.5">适合插入到 PPT 或文档中</span>
                            </div>
                        </DropdownMenuItem>
                    </DropdownMenuContent>
                </DropdownMenu>
            </div>

            {/* SVG 容器 */}
            <svg ref={svgRef} className="flex-1 w-full h-full select-none" />
            <div 
                ref={toolbarRef} 
                className="absolute bottom-4 right-4 bg-card shadow-sm border border-border rounded opacity-80 hover:opacity-100 transition-opacity"
            />
        </div>
    );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import MindMap from 'simple-mind-map';
import Drag from 'simple-mind-map/src/plugins/Drag.js';
import KeyboardNavigation from 'simple-mind-map/src/plugins/KeyboardNavigation.js';
import RichText from 'simple-mind-map/src/plugins/RichText.js';
import MiniMap from 'simple-mind-map/src/plugins/MiniMap.js';
import { transformToMarkdown } from 'simple-mind-map/src/parse/toMarkdown.js';
import { markdownToSmm } from '@/lib/utils/mindmapConverter';

// Register plugins globally
MindMap.usePlugin(Drag)
    .usePlugin(KeyboardNavigation)
    .usePlugin(RichText)
    .usePlugin(MiniMap);

interface SimpleMindMapViewerProps {
    markdown: string;
    onChange?: (newMarkdown: string) => void;
    className?: string;
    readOnly?: boolean;
}

export function SimpleMindMapViewer({ markdown, onChange, className = '', readOnly = false }: SimpleMindMapViewerProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const minimapRef = useRef<HTMLDivElement>(null);
    const mindMapRef = useRef<any>(null);
    
    // 我们用一个 ref 记录内部状态是否刚发生变更，避免死循环
    const isInternalUpdate = useRef(false);

    useEffect(() => {
        if (!containerRef.current) return;

        // 初始化
        const mindMap = new (MindMap as any)({
            el: containerRef.current,
            fit: true,
            theme: 'classic2', // 内置高颜值主题
            readonly: readOnly,
        });
        
        mindMapRef.current = mindMap;

        // 绑定事件：数据变化时向外触发 Markdown 同步
        mindMap.on('data_change', () => {
            if (isInternalUpdate.current) {
                isInternalUpdate.current = false;
                return;
            }
            
            const currentData = mindMap.getData();
            // simple-mind-map 自带的 markdown 导出方法
            const newMarkdown = transformToMarkdown(currentData);
            
            if (onChange) {
                onChange(newMarkdown);
            }
        });

        // initial load
        const initData = markdownToSmm(markdown);
        isInternalUpdate.current = true;
        mindMap.setData(initData);

        return () => {
            mindMap.destroy();
        };
    }, []); // eslint-disable-line react-hooks/exhaustive-deps

    // 处理外部传入的 markdown 变更（比如左侧代码编辑器或 AI 刚写完）
    useEffect(() => {
        if (!mindMapRef.current || !markdown) return;
        
        // 简单做一个 Diff 判断，如果外部 Markdown 传进来的和我们刚刚发出去的没有巨大变化，直接跳过
        // 为了防止编辑器焦点丢失，只有在手动明确是由外部引起的大变更时，重新 setData
        const currentData = mindMapRef.current.getData();
        const existingMD = transformToMarkdown(currentData);
        
        // 我们粗略比较去掉空格和换行后的字符串
        if (existingMD.replace(/\s/g, '') !== markdown.replace(/\s/g, '')) {
             isInternalUpdate.current = true;
             mindMapRef.current.setData(markdownToSmm(markdown));
        }
    }, [markdown]);

    return (
        <div className={`relative ${className}`}>
            <div ref={containerRef} className="absolute inset-0 w-full h-full outline-none" />
            <div 
                ref={minimapRef} 
                className="absolute bottom-4 right-4 w-48 h-32 bg-white/50 backdrop-blur-md rounded-xl border border-black/10 shadow-lg pointer-events-none opacity-0" // mini map hook, simple-mind-map 会自动找此类或需要在配置里指定
            ></div>
            {/* 提示遮罩 */}
            {!readOnly && (
                <div className="absolute top-4 right-4 bg-background/80 backdrop-blur text-muted-foreground text-xs px-3 py-1.5 rounded-full pointer-events-none shadow-sm">
                    💡 双击节点编辑文字，拖拽改变结构，Tab 新建子节点
                </div>
            )}
        </div>
    );
}

