import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Check, Circle, EyeOff, Eye, CheckCircle2, XCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface PracticeCardProps {
    question: {
        id: number;
        content: string;
        options: string[];
        type: string;  // 与 Question 类型保持一致
        dimension: string;
    };
    isMulti: boolean;
    selectedOptions: string[];
    onOptionClick: (option: string, mode: 'single' | 'multi') => void;
    onSubmitMulti: () => void;
}

export function PracticeCard({
    question,
    isMulti,
    selectedOptions,
    onOptionClick,
    onSubmitMulti
}: PracticeCardProps) {
    // 排除法状态：存储被划掉的选项（判断题不需要此功能）
    const [excludedOptions, setExcludedOptions] = useState<string[]>([]);

    // 当题目更换时，重置排除状态
    useEffect(() => {
        setExcludedOptions([]);
    }, [question.id]);

    const toggleExclude = (e: React.MouseEvent, option: string) => {
        e.preventDefault(); // 阻止默认右键菜单
        e.stopPropagation();
        setExcludedOptions(prev =>
            prev.includes(option)
                ? prev.filter(o => o !== option)
                : [...prev, option]
        );
    };

    const options = Array.isArray(question?.options) ? question.options : [];
    const isTrueFalse = question.type === 'truefalse';

    // 题型标签样式
    const typeLabel = isTrueFalse ? "判断题" : isMulti ? "多项选择" : "单项选择";
    const typeLabelClass = isTrueFalse
        ? 'bg-orange-500/10 text-orange-600 dark:text-orange-400'
        : isMulti
            ? 'bg-purple-500/10 text-purple-600 dark:text-purple-400'
            : 'bg-blue-500/10 text-blue-600 dark:text-blue-400';

    return (
        <motion.div
            key="practicing"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.3 }}
            className="border border-border p-4 md:p-6 rounded shadow-sm bg-card"
        >
            <div className="mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <span className={`text-xs px-2 py-1 rounded font-bold ${typeLabelClass}`}>
                        {typeLabel}
                    </span>
                    <span className="text-xs text-muted-foreground">
                        认知维度: {question.dimension === 'knowledge' ? '识记' : question.dimension === 'application' ? '应用' : '理解'}
                    </span>
                </div>
                {!isTrueFalse && (
                    <div className="text-[10px] text-muted-foreground/50 italic">
                        提示: 点击选项右侧眼睛图标或右键可"排除"
                    </div>
                )}
            </div>

            <h2 className="text-xl mb-6 font-bold leading-relaxed text-foreground">
                {question.content}
            </h2>

            {/* 判断题：渲染两个大按钮 */}
            {isTrueFalse ? (
                <div className="grid grid-cols-2 gap-4 mb-6">
                    {[
                        { letter: 'A', label: '正确', icon: <CheckCircle2 className="w-8 h-8" /> },
                        { letter: 'B', label: '错误', icon: <XCircle className="w-8 h-8" /> },
                    ].map(({ letter, label, icon }) => {
                        const isSelected = selectedOptions.includes(letter);
                        return (
                            <button
                                key={letter}
                                onClick={() => onOptionClick(letter, 'single')}
                                className={`flex flex-col items-center justify-center gap-3 py-6 rounded-xl border-2 transition-all font-bold text-lg
                                    ${isSelected
                                        ? letter === 'A'
                                            ? 'border-emerald-500 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400'
                                            : 'border-red-500 bg-red-500/10 text-red-600 dark:text-red-400'
                                        : 'border-border hover:border-primary/50 bg-card text-foreground hover:bg-accent'
                                    }`}
                            >
                                {icon}
                                {label}
                            </button>
                        );
                    })}
                </div>
            ) : (
                /* 普通选择题：原有渲染逻辑 */
                <div className="grid grid-cols-1 gap-3 mb-6">
                    {options.map((option, idx) => {
                        const letter = String.fromCharCode(65 + idx);
                        const isSelected = selectedOptions.includes(letter);
                        const isExcluded = excludedOptions.includes(option);

                        return (
                            <div
                                key={idx}
                                onClick={() => !isExcluded && onOptionClick(letter, isMulti ? 'multi' : 'single')}
                                onContextMenu={(e) => toggleExclude(e, option)}
                                className={`w-full text-left p-3 md:p-4 rounded border transition-all flex items-center group relative cursor-pointer min-h-[48px]
                                    ${isExcluded ? 'opacity-40 grayscale bg-muted border-border cursor-not-allowed' :
                                        isMulti && isSelected ? 'bg-blue-500/10 border-blue-500' : 'hover:bg-accent hover:border-blue-500/30 border-border'}
                                `}
                                role="button"
                                tabIndex={0}
                            >
                                <span className={`w-8 h-8 rounded-full flex items-center justify-center mr-4 font-bold text-sm shrink-0
                                    ${isExcluded ? 'bg-muted text-muted-foreground' :
                                        isMulti && isSelected ? 'bg-blue-500 text-white' : 'bg-muted/50 text-muted-foreground group-hover:bg-blue-500/10 group-hover:text-blue-600 dark:group-hover:text-blue-400'}
                                `}>
                                    {isMulti ? (isSelected ? <Check className="w-4 h-4" /> : <Circle className="w-4 h-4" />) : letter}
                                </span>

                                <span className={`text-foreground flex-1 ${isExcluded ? 'line-through decoration-2' : ''}`}>
                                    {option}
                                </span>

                                {/* 排除法辅助按钮 (移动端友好) */}
                                <div
                                    onClick={(e) => toggleExclude(e, option)}
                                    className={`ml-2 p-1.5 rounded-md transition-colors z-10 ${isExcluded ? 'text-blue-500 hover:bg-blue-500/10' : 'text-muted-foreground opacity-100 md:opacity-0 md:group-hover:opacity-100 hover:bg-accent'}`}
                                    title={isExcluded ? "恢复选项" : "排除此项"}
                                >
                                    {isExcluded ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            {isMulti && (
                <Button className="w-full" onClick={onSubmitMulti} size="lg">
                    确认提交
                </Button>
            )}
        </motion.div>
    );
}

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Database, BookOpen, Target, ShieldCheck, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';

// Define minimal types to avoid deep dependency
interface Question {
    id: number;
    content: string;
    options: string[];
    type: string;
    answer: string;
    explanation?: string;
}

interface ReviewItem {
    originalQuestionId: number;
    originalQuestionContent: string;
    currentStep: 'study' | 'quiz' | 'regression';
    wrongAnswer: string;
    tags: string[];
    quiz?: {
        analysis: string;
        quiz: {
            content: string;
            options: string[];
            answer: string;
        };
    };
    regression?: {
        logicType: string;
        challenges: {
            content: string;
            options: string[];
            answer: string;
        }[];
    };
    regressionSubIndex: number;
}

interface ReviewCardProps {
    currentItem: ReviewItem;
    sessionQueue: Question[];
    isLoadingAI: boolean;
    onReviewStep: (success: boolean) => void;
}

export function ReviewCard({ currentItem, sessionQueue, isLoadingAI, onReviewStep }: ReviewCardProps) {
    if (!currentItem) return null;

    const steps = [
        { id: 'study', label: '解析研读', icon: BookOpen },
        { id: 'quiz', label: '纠偏找茬', icon: Target },
        { id: 'regression', label: '回归挑战', icon: ShieldCheck },
    ];

    const currentStepIndex = steps.findIndex(s => s.id === currentItem.currentStep);

    return (
        <motion.div
            key="reviewing"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.3 }}
            className="border border-amber-500/20 p-6 rounded-2xl shadow-lg bg-card relative overflow-hidden"
        >
            {/* 装饰性背景 */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 rounded-full -mr-16 -mt-16 pointer-events-none" />

            <div className="relative z-10">
                <div className="flex items-center justify-between mb-8">
                    <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                        <div className="w-2 h-6 bg-amber-500 rounded-full" />
                        智能复盘模式
                    </h2>
                    <div className="text-xs font-medium text-amber-600 dark:text-amber-400 bg-amber-500/10 px-3 py-1 rounded-full border border-amber-500/20">
                        AI 深度个性化生成
                    </div>
                </div>

                {/* Progress Stepper */}
                <div className="flex items-center justify-between mb-10 relative">
                    {/* 连接线 */}
                    <div className="absolute top-5 left-0 w-full h-0.5 bg-muted -z-10" />
                    <div
                        className="absolute top-5 left-0 h-0.5 bg-amber-500 -z-10 transition-all duration-500"
                        style={{ width: `${(currentStepIndex / (steps.length - 1)) * 100}%` }}
                    />

                    {steps.map((step, idx) => {
                        const Icon = step.icon;
                        const isCompleted = idx < currentStepIndex;
                        const isActive = idx === currentStepIndex;

                        return (
                            <div key={step.id} className="flex flex-col items-center gap-2">
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${isCompleted ? 'bg-amber-500 border-amber-500 text-white shadow-md' :
                                        isActive ? 'bg-card border-amber-500 text-amber-600 dark:text-amber-400 shadow-md ring-4 ring-amber-500/20' :
                                            'bg-card border-border text-muted-foreground'
                                    }`}>
                                    {isCompleted ? <Check className="w-5 h-5" /> : <Icon className="w-5 h-5" />}
                                </div>
                                <span className={`text-xs font-bold transition-colors ${isActive ? 'text-amber-600 dark:text-amber-400' : 'text-muted-foreground'
                                    }`}>
                                    {step.label}
                                </span>
                            </div>
                        );
                    })}
                </div>

                <div className="mb-6">
                    <p className="text-sm text-muted-foreground mb-2 flex items-center gap-1">
                        <Database className="w-3.5 h-3.5" />
                        复盘原题: {currentItem.originalQuestionContent.length > 50 ? currentItem.originalQuestionContent.substring(0, 50) + '...' : currentItem.originalQuestionContent}
                    </p>
                </div>

                <div className="bg-muted/30 rounded-2xl p-4 md:p-6 mb-6 min-h-[200px] border border-border">
                    {isLoadingAI ? (
                        <div className="flex items-center justify-center h-full text-muted-foreground animate-pulse py-12">
                            <div className="flex flex-col items-center gap-3">
                                <div className="w-8 h-8 border-4 border-amber-200 border-t-amber-500 rounded-full animate-spin" />
                                <p>AI 正在生成专属复盘内容...</p>
                            </div>
                        </div>
                    ) : (
                        <AnimatePresence mode="wait">
                            <motion.div
                                key={currentItem.currentStep}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, y: -10 }}
                            >
                                {currentItem.currentStep === 'study' && (
                                    <div className="space-y-6">
                                        {/* 突出展示原题题干 */}
                                        <div className="bg-zinc-800 text-white p-5 rounded-lg shadow-inner relative overflow-hidden">
                                            <div className="absolute top-0 right-0 p-2 opacity-10">
                                                <Database className="w-12 h-12" />
                                            </div>
                                            <h4 className="text-[10px] font-bold text-zinc-400 mb-2 uppercase tracking-[0.2em]">错题回顾 / Original Question</h4>
                                            <p className="text-lg font-medium leading-relaxed">
                                                {currentItem.originalQuestionContent}
                                            </p>
                                        </div>

                                        <div className="bg-card p-5 rounded-xl border border-border shadow-sm">
                                            <h4 className="text-xs font-bold text-muted-foreground mb-4 uppercase tracking-wider flex items-center">
                                                <div className="w-1 h-3 bg-blue-500 mr-2 rounded-full"></div>
                                                思维纠偏 (Diff Analysis)
                                            </h4>

                                            {(() => {
                                                const q = sessionQueue.find(sq => sq.id === currentItem.originalQuestionId);
                                                if (!q) return null;
                                                const userAnsRaw = currentItem.wrongAnswer;
                                                const correctAnsRaw = q.answer;
                                                const isMulti = q.type === 'multi';

                                                // 解析答案显示逻辑 (通用版本)
                                                const getAnswerDisplay = (raw: string) => {
                                                    try {
                                                        const arr = isMulti ? JSON.parse(raw) : [raw];
                                                        const labels: string[] = [];
                                                        const contents: string[] = [];

                                                        arr.forEach((val: string) => {
                                                            if (val.length === 1 && val >= 'A' && val <= 'Z') {
                                                                const idx = val.charCodeAt(0) - 65;
                                                                if (q.options[idx]) {
                                                                    labels.push(val);
                                                                    contents.push(q.options[idx]);
                                                                    return;
                                                                }
                                                            }
                                                            const idx = q.options.indexOf(val);
                                                            if (idx !== -1) {
                                                                labels.push(String.fromCharCode(65 + idx));
                                                                contents.push(val);
                                                            } else {
                                                                labels.push('?');
                                                                contents.push(val);
                                                            }
                                                        });

                                                        return {
                                                            label: labels.join(isMulti ? ' + ' : ''),
                                                            content: contents.join(isMulti ? '; ' : '')
                                                        };
                                                    } catch (e) {
                                                        return { label: raw, content: raw };
                                                    }
                                                };

                                                const userAns = getAnswerDisplay(userAnsRaw);
                                                const correctAns = getAnswerDisplay(correctAnsRaw);

                                                return (
                                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                        {/* 用户错误项 */}
                                                        <div className="relative p-4 rounded-lg bg-red-500/10 border-2 border-red-500/20">
                                                            <div className="absolute -top-3 left-4 px-2 py-0.5 bg-red-100 text-red-600 text-[10px] font-bold rounded-full uppercase tracking-wider">
                                                                您的选择
                                                            </div>
                                                            <div className="flex items-start gap-3 mt-2">
                                                                <div className="w-8 h-8 rounded-full bg-red-500/20 text-red-700 dark:text-red-400 flex items-center justify-center font-bold text-sm shrink-0">
                                                                    {userAns.label}
                                                                </div>
                                                                <div className="text-sm text-red-700 dark:text-red-300 leading-relaxed opacity-80 line-through decoration-red-300">
                                                                    {userAns.content}
                                                                </div>
                                                            </div>
                                                        </div>

                                                        {/* 正确答案项 */}
                                                        <div className="relative p-4 rounded-lg bg-green-500/10 border-2 border-green-500/20">
