"use client";

import React, { useCallback, useMemo, useRef } from 'react';
import dynamic from 'next/dynamic';
import { Target, BookOpen } from 'lucide-react';
import { KnowledgeGraphData, KnowledgeNode, KnowledgeLink } from '@/server/actions/viz';
import type { ForceGraphMethods, NodeObject } from 'react-force-graph-2d';
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer";
import { Button } from "@/components/ui/button";
import { useRouter } from 'next/navigation';

// 动态导入 ForceGraph2D，禁用 SSR（因为它依赖 canvas）
 
const ForceGraph2D = dynamic(() => import('react-force-graph-2d'), {
  ssr: false,
  loading: () => (
    <div className="w-full h-full flex items-center justify-center">
      <div className="text-muted-foreground">加载知识图谱...</div>
    </div>
  ),
// eslint-disable-next-line @typescript-eslint/no-explicit-any
}) as any;

// react-force-graph 运行时会注入 x、y、val 等属性
type ForceKnowledgeNode = KnowledgeNode & {
  x: number;
  y: number;
  val: number;
};

interface KnowledgeTreeProps {
  data: KnowledgeGraphData;
}

export function KnowledgeTree({ data }: KnowledgeTreeProps) {
  const graphRef = useRef<ForceGraphMethods<NodeObject<KnowledgeNode>> | undefined>(undefined);
  const router = useRouter();
  const [selectedNode, setSelectedNode] = React.useState<KnowledgeNode | null>(null);
  const [drawerOpen, setDrawerOpen] = React.useState(false);

  // 转换数据格式以适配 react-force-graph
  const graphData = useMemo(() => ({
    nodes: data.nodes.map(node => ({
      ...node,
      // react-force-graph 需要 id 字段
      val: node.group === 0 ? 20 : node.group === 1 ? 12 : 6 + (node.score / 20),
    })),
    links: data.links.map(link => ({
      source: link.source,
      target: link.target,
      value: link.value,
    })),
  }), [data]);

  // 节点颜色逻辑
  const getNodeColor = useCallback((node: KnowledgeNode) => {
    if (node.group === 0) return '#0f172a'; // 根节点
    if (node.group === 1) return '#2563eb'; // 分类节点
    // 叶子节点基于分数着色
    if (node.score < 60) return '#ef4444'; // 红色
    if (node.score < 85) return '#eab308'; // 黄色
    return '#22c55e'; // 绿色
  }, []);

  // 节点点击处理
  const handleNodeClick = useCallback((node: KnowledgeNode) => {
    if (node.group === 2) {
      setSelectedNode(node as KnowledgeNode);
      setDrawerOpen(true);
    }
  }, []);

  // 节点绘制（自定义 Canvas 渲染）
  const paintNode = useCallback((node: ForceKnowledgeNode, ctx: CanvasRenderingContext2D, globalScale: number) => {
    const label = node.id.split('/').pop() || node.id;
    const fontSize = node.group === 0 ? 14 / globalScale : 10 / globalScale;
    const nodeRadius = node.val;

    // 绘制节点圆
    ctx.beginPath();
    ctx.arc(node.x, node.y, nodeRadius, 0, 2 * Math.PI, false);
    ctx.fillStyle = getNodeColor(node);
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2 / globalScale;
    ctx.stroke();

    // 绘制标签
    const shouldShowLabel = globalScale > 1.2 || node.group < 2;
    if (shouldShowLabel) {
      ctx.font = `${node.group < 2 ? 'bold' : 'normal'} ${fontSize}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'bottom';

      // 绘制文字阴影/背景以提升对比度
      ctx.shadowColor = 'rgba(255, 255, 255, 0.8)';
      ctx.shadowBlur = 4;
      ctx.fillStyle = node.group === 0 ? '#1e293b' : '#475569';
      ctx.fillText(label, node.x, node.y - nodeRadius - 2);

      // 重置阴影
      ctx.shadowBlur = 0;
    }
  }, [getNodeColor]);

  // 配置 D3 物理引擎
  React.useEffect(() => {
    if (graphRef.current) {
      const fg = graphRef.current;
      
      // 增强电荷斥力 (Repulsion)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (fg.d3Force('charge') as any)?.strength(-400);

      // 增加链路距离 (Link Distance)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (fg.d3Force('link') as any)?.distance(80);

      // 引入节点碰撞检测 (Collision)，防止重叠
       
      fg.d3Force('collide', ((_node: NodeObject<KnowledgeNode>) => {
         // 碰撞半径：节点半径 + 较大的保护边距（为文字留白）
         const n = _node as ForceKnowledgeNode;
         return n.val + 25;
      }) as any);

      // 重新预热引擎以应用新参数
      fg.d3ReheatSimulation();
    }
  }, [graphData]); // 当数据变化时重新应用力场

  return (
    <div className="w-full h-full relative">
      <ForceGraph2D
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        ref={graphRef as any}
        graphData={graphData}
        nodeRelSize={1}
        nodeVal="val"
        nodeCanvasObject={paintNode as (node: NodeObject<KnowledgeNode>, ctx: CanvasRenderingContext2D, globalScale: number) => void}
        nodePointerAreaPaint={(node: NodeObject<KnowledgeNode>, color: string, ctx: CanvasRenderingContext2D) => {
          const n = node as ForceKnowledgeNode;
          ctx.beginPath();
          ctx.arc(n.x, n.y, n.val, 0, 2 * Math.PI, false);
          ctx.fillStyle = color;
          ctx.fill();
        }}
        linkColor={() => '#e2e8f0'}
        linkWidth={(link: KnowledgeLink) => Math.sqrt(link.value) * 1.5}
        onNodeClick={(node: KnowledgeNode) => handleNodeClick(node as unknown as KnowledgeNode)}
        cooldownTicks={100}
        onEngineStop={() => graphRef.current?.zoomToFit(400, 50)}
        enableZoomInteraction={true}
        enablePanInteraction={true}
        // 微调仿真参数
        d3AlphaDecay={0.02}
        d3VelocityDecay={0.4}
      />

      <Drawer open={drawerOpen} onOpenChange={setDrawerOpen}>
        <DrawerContent>
          <div className="mx-auto w-full max-w-sm">
            <DrawerHeader>
              <div className="flex items-center gap-2 mb-2">
                <div className={`p-2 rounded-lg ${(selectedNode?.score || 0) < 60 ? "bg-red-500/10 text-red-500" :
                  (selectedNode?.score || 0) < 85 ? "bg-yellow-500/10 text-yellow-500" :
                    "bg-green-500/10 text-green-500"
                  }`}>
                  <Target className="h-5 w-5" />
                </div>
                <DrawerTitle className="text-xl">
                  {selectedNode?.id.split('/').pop()}
                </DrawerTitle>
              </div>
              <DrawerDescription>
                详细掌握度分析与针对性提升建议。
              </DrawerDescription>
            </DrawerHeader>

            <div className="p-4 space-y-6">
              <div className="space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground">当前掌握度</span>
                  <span className="font-bold">{selectedNode?.score || 0}%</span>
                </div>
                <div className="h-3 w-full bg-muted rounded-full overflow-hidden">
                  <div
                    className={`h-full transition-all duration-1000 ${(selectedNode?.score || 0) < 60 ? "bg-red-500" :
                      (selectedNode?.score || 0) < 85 ? "bg-yellow-500" :
                        "bg-green-500"
                      }`}
                    style={{ width: `${selectedNode?.score || 0}%` }}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <Button
                  className="w-full gap-2"
                  onClick={() => {
                    if (selectedNode) {
                      router.push(`/practice?tag=${encodeURIComponent(selectedNode.id)}`);
                    }
                  }}
                >
                  <BookOpen className="h-4 w-4" />
                  针对性练习
                </Button>
                <DrawerClose asChild>
                  <Button variant="outline" className="w-full">
                    关闭
                  </Button>
                </DrawerClose>
              </div>
            </div>
          </div>
        </DrawerContent>
      </Drawer>
    </div>
  );
}

"use client";

import React, { useEffect, useRef } from 'react';
import { select, selectAll } from 'd3-selection';
import { scaleLinear } from 'd3-scale';
import { lineRadial, curveLinearClosed } from 'd3-shape';
import type { LineRadial } from 'd3-shape';

export interface RadarData {
  axis: string;
  value: number;
}

export interface RadarChartProps {
  data: RadarData[];
}

export default function RadarChart({ data }: RadarChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!data || !svgRef.current) return;

    const width = 300;
    const height = 300;
    const margin = 40;
    const radius = Math.min(width, height) / 2 - margin;
    
    // Clear
    select(svgRef.current).selectAll("*").remove();

    const svg = select(svgRef.current)
      .attr("viewBox", [0, 0, width, height] as any)
      .append("g")
      .attr("transform", `translate(${width/2},${height/2})`);

    const axes = data.map(d => d.axis);
    const angleSlice = (Math.PI * 2) / axes.length;

    // Scale
    const rScale = scaleLinear().range([0, radius]).domain([0, 100]);

    // Draw Axes
    const axisGrid = svg.append("g").attr("class", "axisWrapper");
    
    // Levels (circles)
    const levels = 5;
    for(let j=0; j<levels; j++){
      const levelFactor = radius * ((j+1)/levels);
      axisGrid.selectAll(".levels")
        .data([1]) // Dummy data
        .enter()
        .append("circle")
        .attr("r", levelFactor)
        .style("fill", "#CDCDCD")
        .style("stroke", "#CDCDCD")
        .style("fill-opacity", 0.1);
    }

    // Axis Lines
    const axis = axisGrid.selectAll(".axis")
      .data(axes)
      .enter()
      .append("g")
      .attr("class", "axis");

    axis.append("line")
      .attr("x1", 0)
      .attr("y1", 0)
      .attr("x2", (d, i) => rScale(100) * Math.cos(angleSlice * i - Math.PI/2))
      .attr("y2", (d, i) => rScale(100) * Math.sin(angleSlice * i - Math.PI/2))
      .attr("class", "line")
      .style("stroke", "white")
      .style("stroke-width", "2px");

    axis.append("text")
      .attr("class", "legend")
      .style("font-size", "11px")
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em")
      .attr("x", (d, i) => rScale(110) * Math.cos(angleSlice * i - Math.PI/2))
      .attr("y", (d, i) => rScale(110) * Math.sin(angleSlice * i - Math.PI/2))
      .text(d => d);

    // Draw The Area
    const radarLine = lineRadial<RadarData>()
      .curve(curveLinearClosed)
      .radius(d => rScale(d.value))
      .angle((d, i) => i * angleSlice);

    svg.append("path")
      .datum(data)
      .attr("d", radarLine)
      .style("stroke-width", 2)
      .style("stroke", "#22c55e")
      .style("fill", "#22c55e")
      .style("fill-opacity", 0.5);

    // Draw Circles
    svg.selectAll(".radarCircle")
        .data(data)
        .enter().append("circle")
        .attr("class", "radarCircle")
        .attr("r", 4)
        .attr("cx", (d, i) => rScale(d.value) * Math.cos(angleSlice * i - Math.PI/2))
        .attr("cy", (d, i) => rScale(d.value) * Math.sin(angleSlice * i - Math.PI/2))
        .style("fill", "#22c55e")
        .style("fill-opacity", 0.8);

  }, [data]);

  return <svg ref={svgRef} />;
}

// @vitest-environment node
import { describe, it, expect } from 'vitest';
import { createPracticeReducer, INITIAL_STATE } from '../use-practice-engine';
import { PracticeAction, PracticeState, Question } from "@/types";

const practiceReducer = createPracticeReducer(true);

describe('usePracticeEngine Reducer', () => {

    const mockQuestions: Question[] = [
        { id: 1, content: 'Q1', type: 'single', options: [], answer: 'A', tags: ['T1'], dimension: 'knowledge' } as any,
        { id: 2, content: 'Q2', type: 'single', options: [], answer: 'B', tags: ['T1'], dimension: 'knowledge' } as any,
        // ... need enough questions to trigger review if testing 25th question trigger, 
        // but can mock state directly to test transition logic.
    ];

    it('should initialize session correctly', () => {
        const action: PracticeAction = {
            type: 'INIT_SESSION',
            payload: { sessionId: 'sess-1', questions: mockQuestions, startIndex: 0 }
        };
        const newState = practiceReducer(INITIAL_STATE, action);

        expect(newState.status).toBe('practicing');
        expect(newState.sessionId).toBe('sess-1');
        expect(newState.sessionQueue).toHaveLength(2);
        expect(newState.currentIndex).toBe(0);
    });

    it('should handle correct answer progression', () => {
        const startState: PracticeState = {
            ...INITIAL_STATE,
            status: 'practicing',
            sessionQueue: mockQuestions,
            currentIndex: 0
        };

        const action: PracticeAction = {
            type: 'ANSWER_QUESTION',
            payload: { questionId: 1, answer: 'A', isCorrect: true, duration: 1000 }
        };

        const newState = practiceReducer(startState, action);

        expect(newState.answers[1]).toEqual({ answer: 'A', isCorrect: true, duration: 1000 });
        expect(newState.currentIndex).toBe(1);
        expect(newState.reviewQueue).toHaveLength(0); // Correct answer shouldn't add to review
    });

    it('should add wrong answer to review queue (conceptually) but not trigger mode change early', () => {
        const startState: PracticeState = {
            ...INITIAL_STATE,
            status: 'practicing',
            sessionQueue: mockQuestions,
            currentIndex: 0,
            reviewTriggeredAt: 25
        };

        const action: PracticeAction = {
            type: 'ANSWER_QUESTION',
            payload: { questionId: 1, answer: 'wrong', isCorrect: false, duration: 1000 }
        };

        const newState = practiceReducer(startState, action);

        expect(newState.answers[1].isCorrect).toBe(false);
        expect(newState.reviewQueue).toHaveLength(1);
        expect(newState.reviewQueue[0].originalQuestionId).toBe(1);
        expect(newState.status).toBe('practicing'); // Still practicing
        expect(newState.currentIndex).toBe(1);
    });

    it('should trigger review mode when threshold reached with errors', () => {
        // Mock state where we are at question 24, about to answer 25th (index 24)
        // And we have existing items in reviewQueue
        const startState: PracticeState = {
            ...INITIAL_STATE,
            status: 'practicing',
            sessionQueue: Array(30).fill({}).map((_, i) => ({ id: i, content: `Q${i}` } as any)),
            currentIndex: 24,
            reviewTriggeredAt: 25,
            reviewQueue: [{ originalQuestionId: 1 } as any], // Assume 1 error existed
            answers: {} // Populate dummy answers count logic if needed
        };

        // We need 24 answers already. Logic: questionsAnswered >= state.reviewTriggeredAt
        // Let's mock answers having 24 entries
        const mockAnswers: any = {};
        for (let i = 0; i < 24; i++) mockAnswers[i] = { isCorrect: true };
        startState.answers = mockAnswers;

        const action: PracticeAction = {
            type: 'ANSWER_QUESTION',
            payload: { questionId: 24, answer: 'wrong', isCorrect: false, duration: 1000 }
        };

        const newState = practiceReducer(startState, action);

        expect(newState.status).toBe('reviewing');
        expect(newState.currentReviewIndex).toBe(0);
    });

    it('should transition review steps: study -> quiz -> regression', () => {
        const startState: PracticeState = {
            ...INITIAL_STATE,
            status: 'reviewing',
            reviewQueue: [{
                originalQuestionId: 1,
                currentStep: 'study',
                regressionSubIndex: 0,
                failedAttempts: 0
            } as any],
            sessionQueue: [{}, {}] as any, // 2 items so index 0 is not finished
            currentReviewIndex: 0
        };

        // 1. Study -> Quiz
        let state = practiceReducer(startState, { type: 'COMPLETE_REVIEW_STEP', payload: { success: true } });
        expect(state.reviewQueue[0].currentStep).toBe('quiz');

        // 2. Quiz -> Regression
        state = practiceReducer(state, { type: 'COMPLETE_REVIEW_STEP', payload: { success: true } });
        expect(state.reviewQueue[0].currentStep).toBe('regression');
        expect(state.reviewQueue[0].regressionSubIndex).toBe(0);

        // 3. Regression Step 1 -> Step 2
        state = practiceReducer(state, { type: 'COMPLETE_REVIEW_STEP', payload: { success: true } });
        expect(state.reviewQueue[0].regressionSubIndex).toBe(1);

        // 4. Regression Step 3 -> Finish Item
        state.reviewQueue[0].regressionSubIndex = 2; // Jump to last sub-step
        state = practiceReducer(state, { type: 'COMPLETE_REVIEW_STEP', payload: { success: true } });
        // Should move to next item. If no next item, might RESUME_PRACTICE logic (depends on reducer handling recursion/return)

        // The reducer logic for 'NEXT_REVIEW_ITEM' when finished calls RESUME_PRACTICE.
        // But since we are calling COMPLETE_REVIEW_STEP, it calls NEXT_REVIEW_ITEM internally.
        // Let's check status.
        expect(state.status).toBe('practicing'); // Should resume to practicing if no more items
        expect(state.reviewTriggeredAt).toBe(35); // Threshold bumped
    });

    it('判断题：正确答案 A 应通过校验，答错应进入错题队列', () => {
        // 判断题模型：answer 为 "A"（正确），type 为 truefalse
        const trueFalseQuestion: Question = {
            id: 99,
            content: '行为主义认为学习是刺激-反应的联结。',
            type: 'truefalse',
            options: ['正确', '错误'],
            answer: 'A',
            tags: ['心理学'],
            dimension: 'knowledge',
            explanation: '正确，行为主义核心观点。'
        } as any;

        const startState: PracticeState = {
            ...INITIAL_STATE,
            status: 'practicing',
            sessionQueue: [trueFalseQuestion],
            currentIndex: 0,
            reviewTriggeredAt: 25,
        };

        // 答对
        const correctAction: PracticeAction = {
            type: 'ANSWER_QUESTION',
            payload: { questionId: 99, answer: 'A', isCorrect: true, duration: 500 }
        };
        const stateAfterCorrect = practiceReducer(startState, correctAction);
        expect(stateAfterCorrect.answers[99].isCorrect).toBe(true);
        expect(stateAfterCorrect.reviewQueue).toHaveLength(0);

        // 答错（选 B）
        const wrongAction: PracticeAction = {
            type: 'ANSWER_QUESTION',
            payload: { questionId: 99, answer: 'B', isCorrect: false, duration: 500 }
        };
        const stateAfterWrong = practiceReducer(startState, wrongAction);
        expect(stateAfterWrong.answers[99].isCorrect).toBe(false);
        expect(stateAfterWrong.reviewQueue).toHaveLength(1);
        expect(stateAfterWrong.reviewQueue[0].originalQuestionId).toBe(99);
    });
});

import { useRef, useEffect, useState } from 'react';

interface UseChatScrollProps {
    messagesLength: number;
}

export function useChatScroll({ messagesLength }: UseChatScrollProps) {
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const [targetMessageId, setTargetMessageId] = useState<number | null>(null);
    const ignoreScrollRef = useRef(false);

    // 自动滚动到底部或目标位置
    useEffect(() => {
        // 1. 如果有目标消息，优先跳转到目标消息
        if (targetMessageId) {
            const element = document.getElementById(`message-${targetMessageId}`);
            if (element) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                // 添加高亮动画
                element.classList.add('bg-blue-50/50', 'transition-colors', 'duration-1000');
                setTimeout(() => {
                    element.classList.remove('bg-blue-50/50');
                }, 2000);

                setTargetMessageId(null); // 清除目标状态
                ignoreScrollRef.current = true; // 标记下一次渲染忽略滚动到底部
                return;
            }
        }

        // 2. 如果标记了忽略滚动（通常是刚完成跳转），则重置标记并跳过
        if (ignoreScrollRef.current) {
            ignoreScrollRef.current = false;
            return;
        }

        // 3. 否则滚动到底部（默认行为：当消息列表长度变化时）
        if (messagesEndRef.current && !targetMessageId) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messagesLength, targetMessageId]);

    const scrollToBottom = () => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return {
        messagesEndRef,
        setTargetMessageId,
        scrollToBottom
    };
}

import { useState, useEffect, useCallback } from 'react';
import type { ChatSession } from '@/lib/services/chat';
import {
    getChatSessions,
    createChatSession,
    deleteChatSession,
    loadSessionMessages
} from '@/server/actions/chat';

export function useChatSessions() {
    const [sessions, setSessions] = useState<ChatSession[]>([]);
    const [currentSessionId, setCurrentSessionId] = useState<number | null>(null);
    const [isSessionsLoading, setIsSessionsLoading] = useState(true);

    // 加载会话列表
    useEffect(() => {
        loadSessions();
    }, []);

    // 自动清理：如果没有任何会话且当前没在新建状态，确保 currentSessionId 为 null
    useEffect(() => {
        if (!isSessionsLoading && sessions.length === 0 && currentSessionId !== null) {
            setCurrentSessionId(null);
        }
    }, [sessions, currentSessionId, isSessionsLoading]);

    const loadSessions = async () => {
        setIsSessionsLoading(true);
        try {
            const loadedSessions = await getChatSessions();
            setSessions(loadedSessions);
        } catch (error) {
            console.error('加载会话列表失败:', error);
        } finally {
            setIsSessionsLoading(false);
        }
    };

    const handleNewSession = useCallback(() => {
        setCurrentSessionId(null);
    }, []);

    const handleSessionSelect = useCallback(async (sessionId: number) => {
        setCurrentSessionId(sessionId);
        try {
            const history = await loadSessionMessages(sessionId);
            return history;
        } catch (error) {
            console.error('加载会话消息失败:', error);
            return [];
        }
    }, []);

    const handleDeleteSession = useCallback(async (sessionId: number) => {
        try {
            await deleteChatSession(sessionId);
            setSessions(prev => {
                const updated = prev.filter(s => s.id !== sessionId);
                // 如果删除的是当前会话，需要处理选中状态
                if (currentSessionId === sessionId) {
                    if (updated.length > 0) {
                        // 自动选中第一个，但这里我们只返回更新后的列表，
                        // 具体的选中逻辑交给组件或者在这里处理？
                        // 为了保持纯粹，这里只更新列表，但也需要重置 currentSessionId
                        // 这里的逻辑稍微复杂，稍微违背了"纯粹"原则，但实用。
                        // 让我们简单处理：如果删除的是当前，则设为null（新建）或者第一个
                    }
                }
                return updated;
            });

            // 重新计算 currentSessionId 的逻辑比较依赖 state 更新后的结果，
            // 简单起见，我们在组件层处理"删除后跳转"，
            // 或者在这里直接返回更新后的 sessions 供组件判断
            return true;
        } catch (error) {
            console.error('删除会话失败:', error);
            return false;
        }
    }, [currentSessionId]);

    // 用于在产生新会话时手动更新列表（例如发送第一条消息后）
    const addSession = useCallback((newSession: ChatSession) => {
        setSessions(prev => [newSession, ...prev]);
        setCurrentSessionId(newSession.id);
    }, []);

    const updateSessionTitle = useCallback((sessionId: number, title: string) => {
        setSessions(prev => prev.map(s => s.id === sessionId ? { ...s, title } : s));
    }, []);

    return {
        sessions,
        currentSessionId,
        setCurrentSessionId, // 暴露给需要手动控制的场景
        isSessionsLoading,
        loadSessions,
        handleNewSession,
        handleSessionSelect,
        handleDeleteSession,
        addSession,
        updateSessionTitle
    };
}

import { useState, useCallback, useRef } from 'react';
import { createChatSession, generateChatTitle } from '@/server/actions/chat';
import type { ChatSession } from '@/lib/services/chat';
import type { ChatMode } from '@/components/chat/ChatModeToggle';

export interface Message {
    id: string;
    role: 'user' | 'assistant' | 'system';
    content: string;
    is_favorite?: number;
}

interface UseChatStreamProps {
    currentSessionId: number | null;
    onNewSessionCreated: (session: ChatSession) => void;
    onTitleGenerated: (sessionId: number, title: string) => void;
}

export function useChatStream({
    currentSessionId,
    onNewSessionCreated,
    onTitleGenerated
}: UseChatStreamProps) {
    const [messages, setMessages] = useState<Message[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [lastFailedMessage, setLastFailedMessage] = useState<string | null>(null);
    const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
    const [enableRag, setEnableRag] = useState(false); // Default to false (User opt-in)
    const [mode, setMode] = useState<ChatMode>('standard');

    const abortControllerRef = useRef<AbortController | null>(null);

    // 核心：发送消息并处理流式响应
    const sendMessage = useCallback(async (content: string) => {
        if (!content.trim() || isLoading) return;

        setLastFailedMessage(null);

        const userMessage: Message = {
            id: `user-${Date.now()}`,
            role: 'user',
            content: content.trim(),
        };

        // 立即添加用户消息
        setMessages(prev => [...prev, userMessage]);
        setError(null);
        setIsLoading(true);

        let sessionIdToUse = currentSessionId;
        let isNewSession = false;

        // 如果没有当前会话，先创建一个
        if (sessionIdToUse === null) {
            try {
                const newId = await createChatSession();
                sessionIdToUse = newId;
                isNewSession = true;

                // 通知外部新会话创建
                onNewSessionCreated({
                    id: newId,
                    user_id: 0, // 将在服务端正确设置
                    title: '新对话',
                    created_at: new Date().toISOString(),
                    updated_at: new Date().toISOString(),
                    message_count: 0,
                });
            } catch (err) {
                console.error('创建会话失败:', err);
                setError('创建会话失败，请重试');
                setIsLoading(false);
                return;
            }
        }

        // 创建 AbortController 用于取消请求
        abortControllerRef.current = new AbortController();

        try {
            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    messages: [...messages, userMessage].map(m => ({ role: m.role, content: m.content })),
                    sessionId: sessionIdToUse,
                    enableRag,
                    mode
                }),
                signal: abortControllerRef.current.signal,
            });

            if (!response.ok) {
                // 尝试解析服务器返回的错误信息
                let errorMessage = `HTTP error! status: ${response.status}`;
                try {
                    const errorData = await response.json();
                    if (errorData.error) {
                        errorMessage = typeof errorData.error === 'string'
                            ? errorData.error
                            : errorData.error.message || errorData.message || errorMessage;
                    }
                } catch {
                    // 如果无法解析 JSON，使用默认错误消息
                }
                throw new Error(errorMessage);
            }

            if (!response.body) {
                throw new Error('No response body');
            }

            // 创建助手消息占位
            const assistantMessageId = `assistant-${Date.now()}`;
            const assistantMessage: Message = {
                id: assistantMessageId,
                role: 'assistant',
                content: '',
                is_favorite: 0,
            };
            setMessages(prev => [...prev, assistantMessage]);

            // 读取流式响应
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let accumulatedContent = '';

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                const chunk = decoder.decode(value, { stream: true });

                // 尝试解析 Vercel AI SDK 的文本协议 (0:"...")
                const lines = chunk.split('\n');
                for (const line of lines) {
                    if (!line.trim()) continue;

                    if (line.startsWith('0:')) {
                        try {
                            const jsonStr = line.slice(2);
                            const text = JSON.parse(jsonStr);
                            accumulatedContent += text;
                        } catch (e) {
                            accumulatedContent += line.slice(2);
                        }
                    } else if (line.startsWith('e:') || line.startsWith('d:')) {
                        continue;
                    } else {
                        accumulatedContent += line;
                    }
                }

                // 更新消息内容
                setMessages(prev => prev.map(m =>
                    m.id === assistantMessageId
                        ? { ...m, content: accumulatedContent }
                        : m
                ));
            }

            // ✅ 优化：标题生成改为非阻塞（fire-and-forget）
            // 用户可以立即继续对话，无需等待标题生成完成
            if (isNewSession && !isGeneratingTitle && sessionIdToUse) {
                const targetSessionId = sessionIdToUse;
                // 使用 setTimeout 确保不阻塞主流程
                setTimeout(async () => {
                    setIsGeneratingTitle(true);
                    try {
                        const newTitle = await generateChatTitle(targetSessionId);
                        onTitleGenerated(targetSessionId, newTitle);
                    } catch (e) {
                        console.error('生成标题失败:', e);
                    } finally {
                        setIsGeneratingTitle(false);
                    }
                }, 100); // 延迟 100ms，确保 UI 先响应
            }

        } catch (err: unknown) {
            if (err instanceof Error && err.name === 'AbortError') {
                console.log('Request aborted');
            } else {
                console.error('Chat error:', err);
                setError(err instanceof Error ? err.message : '发送消息失败');
                setLastFailedMessage(content);
            }
        } finally {
            setIsLoading(false);
            abortControllerRef.current = null;
        }
    }, [messages, currentSessionId, isLoading, isGeneratingTitle, onNewSessionCreated, onTitleGenerated]);

    // 停止生成
    const stopGeneration = useCallback(() => {
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
            abortControllerRef.current = null;
        }
        setIsLoading(false);
    }, []);

    // 重试上一条失败的消息
    const handleRetry = useCallback(() => {
        if (lastFailedMessage) {
            setError(null);
            // 移除失败时可能已添加的空助手消息
            setMessages(prev => prev.filter(m => !(m.role === 'assistant' && m.content === '')));
            sendMessage(lastFailedMessage);
        }
    }, [lastFailedMessage, sendMessage]);

    return {
        messages,
        setMessages,
        isLoading,
        error,
        sendMessage,
        stopGeneration,
        handleRetry,
        lastFailedMessage,
        setError,
        setLastFailedMessage,
        enableRag,
        setEnableRag,
        mode,
        setMode
    };
}

import React, { useReducer, useEffect, useCallback, useMemo } from 'react';
import { PracticeState, PracticeAction, ReviewItem } from '@/types';
import type { Question } from '@/types';
import { apiClient } from '@/lib/utils/api-client';
export const INITIAL_STATE: PracticeState = {
  status: 'loading',
  sessionId: null,
  sessionQueue: [],
  currentIndex: 0,
  startTime: Date.now(),
  answers: {},
  reviewQueue: [],
  currentReviewIndex: 0,
  reviewTriggeredAt: 25, // Hardcoded per PRD
};

export const createPracticeReducer = (enableIntelligentReview: boolean) => (state: PracticeState, action: PracticeAction): PracticeState => {
  switch (action.type) {
    case 'INIT_SESSION':
      return {
        ...INITIAL_STATE,
        status: 'practicing',
        sessionId: action.payload.sessionId,
        sessionQueue: action.payload.questions,
        currentIndex: action.payload.startIndex || 0,
        startTime: Date.now(),
      };

    case 'ANSWER_QUESTION': {
      const { questionId, answer, isCorrect, duration } = action.payload;
      const newAnswers = { ...state.answers, [questionId]: { answer, isCorrect, duration } };

      // Check for Review Trigger
      const questionsAnswered = Object.keys(newAnswers).length;

      // If wrong, add to temp review queue (conceptually). 
      // In this reducer, we just track state. We assume the queue is built when Trigger happens or incrementally.
      // Let's build reviewQueue incrementally to allow "Risk First" sort later.
      let updatedReviewQueue = state.reviewQueue;
      if (!isCorrect) {
        const q = state.sessionQueue.find((q: Question) => q.id === questionId);
        if (q) {
          const newItem: ReviewItem = {
            originalQuestionId: q.id,
            originalQuestionContent: q.content,
            wrongAnswer: answer,
            tags: q.tags,
            currentStep: 'study',
            regressionSubIndex: 0,
            failedAttempts: 0
          };
          updatedReviewQueue = [...updatedReviewQueue, newItem];
        }
      }

      // Transition Logic
      if (enableIntelligentReview && questionsAnswered >= state.reviewTriggeredAt && updatedReviewQueue.length > 0 && state.status === 'practicing') {
        // Sort Review Queue: Risk First (Placeholder logic)
        // In real app, we might sort by tag mastery score here.
        return {
          ...state,
          answers: newAnswers,
          reviewQueue: updatedReviewQueue,
          status: 'reviewing',
          currentReviewIndex: 0,
          startTime: Date.now(), // Reset timer for review
        };
      }

      // Normal Progression
      if (state.currentIndex < state.sessionQueue.length - 1) {
        return {
          ...state,
          answers: newAnswers,
          reviewQueue: updatedReviewQueue,
          currentIndex: state.currentIndex + 1,
          startTime: Date.now(), // Reset timer for next question
        };
      } else {
        // End of Queue
        if (enableIntelligentReview && updatedReviewQueue.length > 0) {
          return {
            ...state,
            answers: newAnswers,
            reviewQueue: updatedReviewQueue,
            status: 'reviewing',
            currentReviewIndex: 0
          };
        }
        return {
          ...state,
          answers: newAnswers,
          status: 'finished'
        };
      }
    }

    case 'TRIGGER_REVIEW':
      return {
        ...state,
        status: 'reviewing',
        currentReviewIndex: 0,
      };

    case 'LOAD_REVIEW_DATA': {
      const queue = [...state.reviewQueue];
      if (queue[action.payload.index]) {
        queue[action.payload.index] = { ...queue[action.payload.index], ...action.payload.data };
      }
      return { ...state, reviewQueue: queue };
    }

    case 'COMPLETE_REVIEW_STEP': {
      const queue = [...state.reviewQueue];
      const currentItem = { ...queue[state.currentReviewIndex] };

      if (!currentItem) return state;

      if (action.payload.success) {
        // Advance Step
        if (currentItem.currentStep === 'study') {
          currentItem.currentStep = 'quiz';
        } else if (currentItem.currentStep === 'quiz') {
          currentItem.currentStep = 'regression';
          currentItem.regressionSubIndex = 0;
        } else if (currentItem.currentStep === 'regression') {
          // Advance Sub-index for regression (Total 3 questions per PRD)
          if (currentItem.regressionSubIndex < 2) {
            currentItem.regressionSubIndex += 1;
          } else {
            // Done with all 3 regression questions
            const nextState = createPracticeReducer(enableIntelligentReview)(state, { type: 'NEXT_REVIEW_ITEM' });
            return nextState;
          }
        }
      } else {
        // Failed Step
        currentItem.failedAttempts += 1;
        if (currentItem.failedAttempts >= 3) {
          const nextState = createPracticeReducer(enableIntelligentReview)(state, { type: 'NEXT_REVIEW_ITEM' });
          return nextState;
        }
      }

      queue[state.currentReviewIndex] = currentItem;
      return { ...state, reviewQueue: queue };
    }

    case 'NEXT_REVIEW_ITEM': {
      const nextIndex = state.currentReviewIndex + 1;
      if (nextIndex < state.reviewQueue.length) {
        return { ...state, currentReviewIndex: nextIndex };
      }
      return createPracticeReducer(enableIntelligentReview)(state, { type: 'RESUME_PRACTICE' });
    }

    case 'RESUME_PRACTICE':
      if (state.currentIndex >= state.sessionQueue.length - 1) {
        return { ...state, status: 'finished' };
      }
      return {
        ...state,
        status: 'practicing',
        // "If all correct, extend to 35". 
        // If we are resuming, we clear the active review queue because we processed them.
        reviewQueue: [],
        // PRD says "25题后若出现错题即触发复盘". 
        // If we handled them, we continue.
        reviewTriggeredAt: 35 // Bump trigger to end
      };

    case 'FINISH_SESSION':
      return { ...state, status: 'finished' };

    default:
      return state;
  }
}

export function usePracticeEngine(enableIntelligentReview: boolean = false) {
  const reducer = useMemo(() => createPracticeReducer(enableIntelligentReview), [enableIntelligentReview]);
