/**
 * 使用 MuPDF (WASM) 将 PDF 转换为图片，然后调用 SiliconFlow DeepSeek-OCR
 */
export async function performOCR(pdfBuffer: Buffer): Promise<string> {
    try {

        const { apiKey, baseURL } = getAiConfig('premium');

        if (!apiKey) {
            throw new Error('Missing API Key for OCR');
        }

        // 1. 使用 MuPDF 打开 PDF
        const mupdf = await import('mupdf');
        console.log('[Debug] mupdf keys:', Object.keys(mupdf));
        console.log('[Debug] mupdf.Document is type:', typeof mupdf.Document);

        // Ensure Uint8Array
        const data = new Uint8Array(pdfBuffer);
        const doc = mupdf.Document.openDocument(data, "application/pdf");
        const pageCount = doc.countPages();

        console.log(`[OCR] PDF 共 ${pageCount} 页，开始逐页识别...`);

        let fullText = '';
        const DPI = 150; // 分辨率，150 DPI 足够 OCR
        const scale = DPI / 72; // PDF 默认 72 DPI

        for (let i = 0; i < pageCount; i++) {
            try {
                console.log(`[OCR] 处理第 ${i + 1}/${pageCount} 页...`);

                const page = doc.loadPage(i);
                const bounds = page.getBounds();

                // 创建 Pixmap (图像)
                const pixmap = page.toPixmap(
                    mupdf.Matrix.scale(scale, scale),
                    mupdf.ColorSpace.DeviceRGB,
                    false, // alpha
                    true   // annots
                );

                // 转换为 PNG Buffer
                const pngBuffer = pixmap.asPNG();
                const base64Image = Buffer.from(pngBuffer).toString('base64');

                // 2. 调用 SiliconFlow VLM API
                // 使用硬编码的 SiliconFlow 端点，因为 DeepSeek-OCR 模型仅在 SiliconFlow 可用
                const apiEndpoint = 'https://api.siliconflow.cn/v1/chat/completions';

                console.log(`[OCR] Calling API: ${apiEndpoint}`);

                const response = await fetch(apiEndpoint, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${apiKey}`
                    },
                    body: JSON.stringify({
                        model: "deepseek-ai/DeepSeek-OCR",
                        messages: [
                            {
                                role: "user",
                                content: [
                                    {
                                        type: "text",
                                        text: "请识别这张图片中的所有文字，按 Markdown 格式输出。保留原有的标题层级、表格结构和数学公式（使用 LaTeX）。"
                                    },
                                    {
                                        type: "image_url",
                                        image_url: {
                                            url: `data:image/png;base64,${base64Image}`
                                        }
                                    }
                                ]
                            }
                        ],
                        max_tokens: 4096,
                        temperature: 0.1
                    })
                });

                if (!response.ok) {
                    const errText = await response.text();
                    console.error(`[OCR] 第 ${i + 1} 页 API 错误:`, errText);
                    fullText += `\n\n[第 ${i + 1} 页识别失败]\n\n`;
                    continue;
                }

                const data = await response.json();
                const pageContent = data.choices?.[0]?.message?.content || '';
                fullText += `\n\n${pageContent}\n\n`;

            } catch (pageError) {
                console.error(`[OCR] 第 ${i + 1} 页处理失败:`, pageError);
                fullText += `\n\n[第 ${i + 1} 页处理出错]\n\n`;
            }
        }

        return fullText.trim();
    } catch (error) {
        console.error('[OCR] Fatal Error:', error);
        throw error;
    }
}

/**
 * API 调用统计服务
 * 记录和统计 AI API 的调用情况
 */

import db from './db';
import { getBeijingDateString } from './utils/datetime';

export interface ApiCallLog {
  id: number;
  user_id: number | null;
  config_id: number | null;
  model: string;
  endpoint: string | null;
  input_tokens: number;
  output_tokens: number;
  duration_ms: number | null;
  success: number;
  error_message: string | null;
  created_at: string;
}

/**
 * 模型的定价信息 (每百万 Token 的价格，单位：人民币元)
 */
export const MODEL_PRICES: Record<string, { input: number; output: number }> = {
  'deepseek-ai/deepseek-v3.2': { input: 2.0, output: 3.0 },
  'deepseek-ai/DeepSeek-V3.2': { input: 2.0, output: 3.0 },
  'DeepSeek-R1': { input: 2.0, output: 3.0 },
  'deepseek-chat': { input: 2.0, output: 3.0 },
  'gpt-4o-mini': { input: 1.0, output: 4.3 },
  'gpt-4o': { input: 36.0, output: 108.0 },
};

export interface ApiCallStats {
  today: {
    totalCalls: number;
    successCalls: number;
    errorCalls: number;
    totalTokens: number;
    totalCost: number; // 今日预估成本
  };
  total: {
    totalCalls: number;
    successCalls: number;
    errorCalls: number;
    totalTokens: number;
    totalCost: number; // 累计预估成本
  };
  byModel: { model: string; calls: number; tokens: number; cost: number }[];
  recentErrors: { model: string; error: string; time: string }[];
}

/**
 * 记录 API 调用
 */
export function logApiCall(params: {
  userId?: number | null;
  configId?: number | null;
  model: string;
  endpoint?: string;
  inputTokens?: number;
  outputTokens?: number;
  durationMs?: number;
  success?: boolean;
  errorMessage?: string;
}): void {
  try {
    const stmt = db.prepare(`
      INSERT INTO api_call_logs 
        (user_id, config_id, model, endpoint, input_tokens, output_tokens, duration_ms, success, error_message)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      params.userId ?? null,
      params.configId ?? null,
      params.model,
      params.endpoint ?? null,
      params.inputTokens ?? 0,
      params.outputTokens ?? 0,
      params.durationMs ?? null,
      params.success !== false ? 1 : 0,
      params.errorMessage ?? null
    );
  } catch (error) {
    console.error('Failed to log API call:', error);
  }
}

/**
 * 计算 API 调用成本 (人民币元)
 */
function calculateCost(model: string, inputTokens: number, outputTokens: number): number {
  // 尝试直接匹配或不区分大小写匹配
  const pricing = MODEL_PRICES[model] ||
    Object.entries(MODEL_PRICES).find(([key]) => key.toLowerCase() === model.toLowerCase())?.[1];

  if (!pricing) return 0;
  return (inputTokens * pricing.input + outputTokens * pricing.output) / 1000000;
}

/**
 * 获取 API 调用统计
 */
export function getApiCallStats(): ApiCallStats {
  // 基础查询：获取所有成功的调用记录
  const logs = db.prepare(`
    SELECT model, input_tokens, output_tokens, success, created_at
    FROM api_call_logs
  `).all() as any[];

  // 今日起始时间 (使用北京时间)
  const todayStr = getBeijingDateString();

  const stats: ApiCallStats = {
    today: { totalCalls: 0, successCalls: 0, errorCalls: 0, totalTokens: 0, totalCost: 0 },
    total: { totalCalls: 0, successCalls: 0, errorCalls: 0, totalTokens: 0, totalCost: 0 },
    byModel: [],
    recentErrors: []
  };

  const modelMap = new Map<string, { calls: number; tokens: number; cost: number }>();

  logs.forEach(log => {
    const isToday = log.created_at.startsWith(todayStr);
    const tokens = (log.input_tokens || 0) + (log.output_tokens || 0);
    const cost = calculateCost(log.model, log.input_tokens || 0, log.output_tokens || 0);

    // 更新总计
    stats.total.totalCalls++;
    if (log.success) {
      stats.total.successCalls++;
      stats.total.totalTokens += tokens;
      stats.total.totalCost += cost;
    } else {
      stats.total.errorCalls++;
    }

    // 更新今日
    if (isToday) {
      stats.today.totalCalls++;
      if (log.success) {
        stats.today.successCalls++;
        stats.today.totalTokens += tokens;
        stats.today.totalCost += cost;
      } else {
        stats.today.errorCalls++;
      }
    }

    // 更新按模型统计
    if (log.success) {
      const m = modelMap.get(log.model) || { calls: 0, tokens: 0, cost: 0 };
      m.calls++;
      m.tokens += tokens;
      m.cost += cost;
      modelMap.set(log.model, m);
    }
  });

  stats.byModel = Array.from(modelMap.entries()).map(([model, data]) => ({
    model,
    ...data
  })).sort((a, b) => b.calls - a.calls);

  // 获取最近错误 (维持数据库查询，减少全量处理错误信息的负担)
  stats.recentErrors = db.prepare(`
    SELECT model, error_message as error, created_at as time
    FROM api_call_logs
    WHERE success = 0 AND error_message IS NOT NULL
    ORDER BY created_at DESC
    LIMIT 5
  `).all() as any[];

  return stats;
}

/**
 * 格式化 Token 数量
 */
export function formatTokens(tokens: number): string {
  if (tokens >= 1000000) {
    return (tokens / 1000000).toFixed(2) + 'M';
  }
  if (tokens >= 1000) {
    return (tokens / 1000).toFixed(1) + 'K';
  }
  return tokens.toString();
}

import { createMiddleware } from 'hono/factory'
import { getCookie } from 'hono/cookie'
import { decode, verify } from 'hono/jwt'
import { COOKIE_NAME } from '@/lib/auth/auth-edge'
import { getUserById } from '@/lib/auth/user-service'

// 安全加固：生产环境建议配置 JWT_SECRET
// 移除文件顶层 throw，避免阻塞 Next.js 构建过程
const JWT_SECRET = process.env.JWT_SECRET;
const SAFE_SECRET = JWT_SECRET || 'fallback-secret-for-development-only';

import { Context } from 'hono'
import { User } from '@/lib/auth/user-service'

// --- 鉴权内存缓存机制 ---
interface CachedUser {
    exists: boolean;
    token_version?: number;
    expiresAt: number;
}
const authCache = new Map<number, CachedUser>();
const CACHE_TTL_MS = 60 * 1000; // 60秒过期

// ... (existing code)

export const authMiddleware = createMiddleware(async (c, next) => {
    // 强制运行时安全扫描：生产环境禁止缺乏密钥
    if (!JWT_SECRET && process.env.NODE_ENV === 'production') {
        console.error('[SECURITY FATAL] 生产环境缺少 JWT_SECRET，拒绝所有鉴权请求');
        return c.json({ error: '系统配置错误：生产环境未配置 JWT 密钥，拒绝验证凭证' }, 500);
    }

    // 灵活支持 Header 或 Cookie
    const token = c.req.header('Authorization')?.replace('Bearer ', '') || getCookie(c, COOKIE_NAME);

    if (!token) {
        return c.json({ error: 'Unauthorized: No token provided' }, 401);
    }

    try {
        // 1. JWT 签名与过期校验
        const payload = await verify(token, SAFE_SECRET, 'HS256');
        c.set('jwtPayload', payload);

        // 2. 数据库状态校验 (核心加固：Session 撤销检查)
        // 显式断言或解构以获得更好的类型提示
        const user = (payload.user || payload) as User;
        
        if (!user || !user.id) {
            return c.json({ error: 'Unauthorized: Invalid payload' }, 401);
        }

        // 核心加固：确保 ID 为数字类型
        const userId = Number(user.id);
        const now = Date.now();

        // 使用内存缓存，减轻 SQLite 库并发压力，避免每路由强制 DB 读取
        let cached = authCache.get(userId);
        if (!cached || cached.expiresAt < now) {
            const dbUser = getUserById(userId);
            cached = {
                exists: !!dbUser,
                token_version: dbUser?.token_version,
                expiresAt: now + CACHE_TTL_MS
            };
            authCache.set(userId, cached);
            
            // 被动防重：如果体积过大，实施被动 GC
            if (authCache.size > 5000) {
                for (const [k, v] of authCache.entries()) {
                    if (v.expiresAt < now) authCache.delete(k);
                }
            }
        }

        if (!cached.exists) {
            return c.json({ error: 'Unauthorized: User no longer exists' }, 401);
        }

        // 检查版本号是否一致
        if (cached.token_version !== (user.token_version || 0)) {
            console.warn(`[Auth] Session revoked for user ${user.id} due to version mismatch`);
            return c.json({ error: 'Unauthorized: Session revoked' }, 401);
        }

        await next();
    } catch (err) {
        console.error('[Auth] Token verification failed:', err);
        return c.json({ error: 'Unauthorized: Invalid or expired token' }, 401);
    }
});

export const getCurrentUser = (c: Context): User => {
    const payload = c.get('jwtPayload') as { user?: User } | undefined
    // 由于此函数仅在 authMiddleware 保护的路由中调用，
    // payload 必然存在，因此安全地强制返回 User
    return (payload?.user || payload) as User
}

