})

const StatsSchema = z.object({
    total: z.number(),
    byCategory: z.array(z.object({
        category: z.string(),
        count: z.number()
    }))
})

const ListResponseSchema = z.object({
    cards: z.array(KnowledgeCardSchema),
    categories: z.array(z.string()),
    stats: StatsSchema
})

// --- Routes ---

// GET /api/v1/knowledge/cards
