import { encrypt, decrypt, login, logout, getSession, requireUser, requireRole, updateSession, COOKIE_NAME } from '../auth';

describe('Auth Service', () => {
    const TEST_USER = { id: 1, email: 'test@example.com', role: 'user' };

    beforeEach(() => {
        vi.clearAllMocks();
    });

    describe('Encryption/Decryption', () => {
        it('should encrypt and decrypt payload correctly', async () => {
            const payload = { foo: 'bar' };
            const token = await encrypt(payload);

            expect(typeof token).toBe('string');

            const decrypted = await decrypt(token);
            expect(decrypted.foo).toBe('bar');
        });
    });

    describe('login', () => {
        it('should set httpOnly cookie with session', async () => {
            await login(TEST_USER as any);

            expect(mockCookieStore.set).toHaveBeenCalledWith(
                COOKIE_NAME,
                expect.any(String),
                expect.objectContaining({
                    httpOnly: true,
                    expires: expect.any(Date),
                })
            );
        });
    });

    describe('logout', () => {
        it('should clear authentication cookie', async () => {
            await logout();

            expect(mockCookieStore.set).toHaveBeenCalledWith(
                COOKIE_NAME,
                '',
                expect.objectContaining({
                    expires: new Date(0),
                })
            );
        });
    });

    describe('getSession', () => {
        it('should return null if no cookie', async () => {
            mockCookieStore.get.mockReturnValue(undefined);

            const session = await getSession();
            expect(session).toBeNull();
        });

        it('should return session if cookie is valid', async () => {
            const token = await encrypt({ user: TEST_USER, expires: new Date() });
            mockCookieStore.get.mockReturnValue({ value: token });

            const session = await getSession();
            expect(session).toEqual(expect.objectContaining({
                user: expect.objectContaining({ id: 1 }),
            }));
        });

        it('should return null if token invalid', async () => {
            mockCookieStore.get.mockReturnValue({ value: 'invalid-token' });

            const session = await getSession();
            expect(session).toBeNull();
        });
    });

    describe('requireUser', () => {
        it('should return user if session exists', async () => {
            const token = await encrypt({ user: TEST_USER, expires: new Date() });
            mockCookieStore.get.mockReturnValue({ value: token });
            // 模拟用户在数据库中存在，且 token_version 匹配
            mockGetUserById.mockReturnValue({ ...TEST_USER, token_version: 0 });

            const user = await requireUser();
            expect(user.id).toBe(1);
        });

        it('should throw Unauthorized if no session', async () => {
            mockCookieStore.get.mockReturnValue(undefined);

            await expect(requireUser()).rejects.toThrow('Unauthorized');
        });
    });

    describe('requireRole', () => {
        it('should return user if role matches', async () => {
            const token = await encrypt({ user: { ...TEST_USER, role: 'admin' }, expires: new Date() });
            mockCookieStore.get.mockReturnValue({ value: token });
            mockGetUserById.mockReturnValue({ ...TEST_USER, role: 'admin', token_version: 0 });

            const user = await requireRole(['admin']);
            expect(user.role).toBe('admin');
        });

        it('should throw Forbidden if role does not match', async () => {
            const token = await encrypt({ user: { ...TEST_USER, role: 'user' }, expires: new Date() });
            mockCookieStore.get.mockReturnValue({ value: token });
            mockGetUserById.mockReturnValue({ ...TEST_USER, role: 'user', token_version: 0 });

            await expect(requireRole(['admin'])).rejects.toThrow('Forbidden');
        });

        it('should throw Unauthorized if no session (via requireUser)', async () => {
            mockCookieStore.get.mockReturnValue(undefined);

            await expect(requireRole(['admin'])).rejects.toThrow('Unauthorized');
        });
    });

    describe('updateSession', () => {
        it('should refresh session expiration', async () => {
            const token = await encrypt({ user: TEST_USER, expires: new Date() });

            const mockRequest = {
                cookies: {
                    get: vi.fn().mockReturnValue({ value: token }),
                }
            } as any;

            const res = await updateSession(mockRequest);

            // Verify response cookie was set
            expect(res!.cookies.set).toHaveBeenCalledWith(expect.objectContaining({
                name: COOKIE_NAME,
                httpOnly: true,
                expires: expect.any(Date), // Should be extended
            }));
        });

        it('should do nothing if no session', async () => {
            const mockRequest = {
                cookies: {
                    get: vi.fn().mockReturnValue(undefined),
                }
            } as any;

            const res = await updateSession(mockRequest);

            expect(res).toBeUndefined();
        });
    });
});

/**
 * Edge Runtime 兼容的认证模块
 * 仅包含不依赖 Node.js 原生模块的 JWT 操作
 * 供 middleware.ts 使用
 */
import { SignJWT, jwtVerify } from 'jose';

const JWT_SECRET_ENV = process.env.JWT_SECRET;
const SECRET = new TextEncoder().encode(
    JWT_SECRET_ENV || 'fallback-secret-for-development-only'
);

export const COOKIE_NAME = 'auth_token';

/**
 * 加密 JWT payload
 */
export async function encrypt(payload: any) {
    if (!JWT_SECRET_ENV && process.env.NODE_ENV === 'production') {
        throw new Error('系统安全配置严重错误：生产环境缺少 JWT_SECRET，为防止伪造凭证已拒绝签发 Token！');
    }
    return await new SignJWT(payload)
        .setProtectedHeader({ alg: 'HS256' })
        .setIssuedAt()
        .setExpirationTime('7d')
        .sign(SECRET);
}

/**
 * 解密 JWT token
 */
export async function decrypt(input: string): Promise<any> {
    if (!JWT_SECRET_ENV && process.env.NODE_ENV === 'production') {
        throw new Error('系统安全配置严重错误：生产环境缺少 JWT_SECRET，无法安全地验证 Token！');
    }
    const { payload } = await jwtVerify(input, SECRET, {
        algorithms: ['HS256'],
    });
    return payload;
}

import { cookies, headers } from 'next/headers';
import { NextRequest, NextResponse } from 'next/server';
import { User, UserRole } from '@/types';
import { getUserById, revokeUserSessions } from './user-service';
import { cache } from 'react';

// 从 Edge 兼容模块重新导出 JWT 相关功能
export { encrypt, decrypt, COOKIE_NAME } from './auth-edge';
import { encrypt, decrypt, COOKIE_NAME } from './auth-edge';

export async function login(user: User) {
    // Create the session
    const expires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    // Include token_version in the session payload
    const session = await encrypt({ user, expires });

    // Save the session in a cookie
    (await cookies()).set(COOKIE_NAME, session, { expires, httpOnly: true, secure: process.env.NODE_ENV === 'production' });

    return session;
}

export async function logout() {
    const session = await getSession();
    if (session?.user?.id) {
        revokeUserSessions(session.user.id);
    }
    // Destroy the session in cookie
    (await cookies()).set(COOKIE_NAME, '', { expires: new Date(0) });
}

export const getSession = cache(async () => {
    let session = (await cookies()).get(COOKIE_NAME)?.value;

    // Support Bearer Token for Mobile
    if (!session) {
        const authHeader = (await headers()).get('Authorization');
        if (authHeader && authHeader.startsWith('Bearer ')) {
            session = authHeader.split(' ')[1];
        }
    }

    if (!session) return null;
    try {
        const decrypted = await decrypt(session);
        return decrypted as { user: User; expires: string };
    } catch (e) {
        return null;
    }
});

export async function requireUser(): Promise<User> {
    const session = await getSession();
    if (!session || !session.user) {
        throw new Error('Unauthorized');
    }

    // Strict Mode: Check if token_version matches DB
    // 安全加固：显式将 ID 转为数字，防止 JWT 序列化导致的类型不匹配
    const dbUser = getUserById(Number(session.user.id));
    if (!dbUser) {
        throw new Error('Unauthorized: User not found');
    }

    // If DB has a version but session doesn't, or they don't match
    if (dbUser.token_version !== (session.user.token_version || 0)) {
        throw new Error('Unauthorized: Session revoked');
    }

    return session.user;
}

export async function requireRole(allowedRoles: UserRole[]): Promise<User> {
    const user = await requireUser();
    if (!allowedRoles.includes(user.role)) {
        throw new Error('Forbidden: Insufficient permissions');
    }
    return user;
}

export async function updateSession(request: NextRequest) {
    const session = request.cookies.get(COOKIE_NAME)?.value;
    if (!session) return;

    // Refresh the session so it doesn't expire
    const parsed = await decrypt(session);
    parsed.expires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    const res = NextResponse.next();
    res.cookies.set({
        name: COOKIE_NAME,
        value: await encrypt(parsed),
        httpOnly: true,
        expires: parsed.expires,
        secure: process.env.NODE_ENV === 'production'
    });
    return res;
}

/**
 * 订阅服务
 * 核心订阅逻辑：套餐管理、用户订阅、用量统计
 */

import db from '../db';
import { getBeijingDateString } from '../utils/datetime';
import {
    SubscriptionPlan,
    UserSubscription,
    UserSubscriptionDetail,
    DailyUsage,
    UsageType,
    UsageCheckResult,
    USAGE_TYPE_LABELS
} from './subscription-types';

// ==================== 套餐管理 ====================

/**
 * 获取所有套餐 (可选只返回激活的)
 */
export function getAllPlans(activeOnly = true): SubscriptionPlan[] {
    const sql = activeOnly
        ? 'SELECT * FROM subscription_plans WHERE is_active = 1 ORDER BY sort_order ASC'
        : 'SELECT * FROM subscription_plans ORDER BY sort_order ASC';

    const rows = db.prepare(sql).all() as Record<string, unknown>[];
    return rows.map(parsePlanRow);
}

/**
 * 根据 ID 获取套餐
 */
export function getPlanById(planId: string): SubscriptionPlan | null {
    const row = db.prepare('SELECT * FROM subscription_plans WHERE id = ?').get(planId) as Record<string, unknown> | undefined;
    return row ? parsePlanRow(row) : null;
}

/**
 * 创建或更新套餐
 */
export function upsertPlan(plan: Omit<SubscriptionPlan, 'created_at'>): void {
    db.prepare(`
    INSERT INTO subscription_plans (id, name, tier, price_monthly, limits, features, is_active, sort_order)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      name = excluded.name,
      tier = excluded.tier,
      price_monthly = excluded.price_monthly,
      limits = excluded.limits,
      features = excluded.features,
      is_active = excluded.is_active,
      sort_order = excluded.sort_order
  `).run(
        plan.id,
        plan.name,
        plan.tier,
        plan.price_monthly,
        JSON.stringify(plan.limits),
        JSON.stringify(plan.features),
        plan.is_active ? 1 : 0,
        plan.sort_order ?? 0
    );
}

/**
 * 删除套餐 (不能删除有用户订阅的套餐)
 */
export function deletePlan(planId: string): { success: boolean; error?: string } {
    // 检查是否有用户订阅此套餐
    const subCount = db.prepare(
        'SELECT COUNT(*) as count FROM user_subscriptions WHERE plan_id = ?'
    ).get(planId) as { count: number };

    if (subCount.count > 0) {
        return { success: false, error: `该套餐下有 ${subCount.count} 个用户，无法删除` };
    }

    db.prepare('DELETE FROM subscription_plans WHERE id = ?').run(planId);
    return { success: true };
}

// ==================== 用户订阅管理 ====================

/**
 * 获取用户订阅状态
 */
export function getUserSubscription(userId: number): UserSubscription | null {
    const row = db.prepare(`
    SELECT * FROM user_subscriptions WHERE user_id = ?
  `).get(userId) as UserSubscription | undefined;
    return row || null;
}

/**
 * 获取用户订阅详情 (包含套餐信息和今日用量)
 */
export function getUserSubscriptionDetail(userId: number): UserSubscriptionDetail | null {
    const sub = getUserSubscription(userId);
    if (!sub) {
        // 自动为用户创建免费订阅
        createSubscription(userId, 'free');
        return getUserSubscriptionDetail(userId);
    }

    const plan = getPlanById(sub.plan_id);
    if (!plan) return null;

    // 检查订阅是否过期
    if (sub.expires_at && new Date(sub.expires_at) < new Date()) {
        // 订阅已过期，降级到免费版
        updateSubscription(userId, 'free', null);
        return getUserSubscriptionDetail(userId);
    }

    const usageToday = getDailyUsage(userId);

    return {
        ...sub,
        plan,
        usage_today: usageToday
    };
}

/**
 * 创建用户订阅
 */
export function createSubscription(
    userId: number,
    planId: string,
    expiresAt: string | null = null
): void {
    db.prepare(`
    INSERT INTO user_subscriptions (user_id, plan_id, status, expires_at)
    VALUES (?, ?, 'active', ?)
    ON CONFLICT(user_id) DO UPDATE SET
      plan_id = excluded.plan_id,
      status = 'active',
      started_at = CURRENT_TIMESTAMP,
      expires_at = excluded.expires_at
  `).run(userId, planId, expiresAt);
}

/**
 * 更新用户订阅
 */
export function updateSubscription(
    userId: number,
    planId: string,
    expiresAt: string | null
): void {
    db.prepare(`
    UPDATE user_subscriptions
    SET plan_id = ?, expires_at = ?, status = 'active', started_at = CURRENT_TIMESTAMP
    WHERE user_id = ?
  `).run(planId, expiresAt, userId);
}

/**
 * 取消用户订阅 (降级到免费版)
 */
export function cancelSubscription(userId: number): void {
    db.prepare(`
    UPDATE user_subscriptions
    SET plan_id = 'free', status = 'cancelled', expires_at = NULL
    WHERE user_id = ?
  `).run(userId);
}

// ==================== 用量管理 ====================

/**
 * 获取用户今日用量
 */
export function getDailyUsage(userId: number): Record<UsageType, number> {
    const today = getBeijingDateString();
    const rows = db.prepare(`
    SELECT usage_type, count FROM daily_usage
    WHERE user_id = ? AND usage_date = ?
  `).all(userId, today) as { usage_type: string; count: number }[];

    const result: Record<UsageType, number> = {
        ai_chat: 0,
        practice: 0,
        review: 0,
        rag: 0,
        mnemonic: 0,
        first_principles: 0
    };

    rows.forEach(row => {
        if (row.usage_type in result) {
            result[row.usage_type as UsageType] = row.count;
        }
    });

    return result;
}

/**
 * 增加用量计数
 */
export function incrementUsage(userId: number, usageType: UsageType, amount = 1): void {
    const today = getBeijingDateString();

    db.prepare(`
    INSERT INTO daily_usage (user_id, usage_date, usage_type, count)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(user_id, usage_date, usage_type) DO UPDATE SET
      count = count + ?
  `).run(userId, today, usageType, amount, amount);
}

/**
 * 检查用量配额
 */
export function checkUsageQuota(userId: number, usageType: UsageType): UsageCheckResult {
    const subDetail = getUserSubscriptionDetail(userId);
    if (!subDetail) {
        return {
            allowed: false,
            current: 0,
            limit: 0,
            remaining: 0,
            message: '无法获取订阅信息'
        };
    }

    const limit = subDetail.plan.limits[usageType];
    const current = subDetail.usage_today[usageType];

    // -1 表示无限
    if (limit === -1) {
        return {
            allowed: true,
            current,
            limit: -1,
            remaining: -1
        };
    }

    const remaining = Math.max(0, limit - current);
    const allowed = remaining > 0;

    return {
        allowed,
        current,
        limit,
        remaining,
        message: allowed
            ? undefined
            : `今日${USAGE_TYPE_LABELS[usageType]}次数已用完 (${current}/${limit})，升级套餐解锁更多`
    };
}

/**
 * 检查并消费配额 (原子操作)
 */
export function checkAndConsumeQuota(
    userId: number,
    usageType: UsageType
): UsageCheckResult {
    // 使用事务确保检查与扣费的原子性，防止并发下的配额绕过 (Race Condition)
    return db.transaction(() => {
        const result = checkUsageQuota(userId, usageType);

        if (result.allowed) {
            incrementUsage(userId, usageType);
            result.current += 1;
            if (result.remaining !== -1) {
                result.remaining -= 1;
            }
        }

        return result;
    })();
}

// ==================== 统计查询 ====================

/**
 * 获取订阅统计数据
 */
export function getSubscriptionStats(): {
    totalUsers: number;
    byPlan: { plan_id: string; plan_name: string; count: number }[];
} {
    const totalUsers = (db.prepare('SELECT COUNT(*) as count FROM user_subscriptions').get() as { count: number }).count;

    const byPlan = db.prepare(`
    SELECT us.plan_id, sp.name as plan_name, COUNT(*) as count
    FROM user_subscriptions us
    LEFT JOIN subscription_plans sp ON us.plan_id = sp.id
    GROUP BY us.plan_id
    ORDER BY count DESC
  `).all() as { plan_id: string; plan_name: string; count: number }[];

    return { totalUsers, byPlan };
}

// ==================== 辅助函数 ====================

function parsePlanRow(row: Record<string, unknown>): SubscriptionPlan {
    return {
        id: row.id as string,
        name: row.name as string,
        tier: row.tier as SubscriptionPlan['tier'],
        price_monthly: row.price_monthly as number,
        sort_order: row.sort_order as number | undefined,
        created_at: row.created_at as string | undefined,
        limits: JSON.parse(row.limits as string || '{}'),
        features: JSON.parse(row.features as string || '[]'),
        is_active: Boolean(row.is_active)
    };
}

