/**
 * 扩展选题服务
 * 支持多种练习模式的选题逻辑
 */

import db from '@/lib/db';
import { PracticeConfig, PracticeMode } from './practice-types';

export interface Question {
    id: number;
    content: string;
    options: string;
    answer: string;
    explanation: string;
    tags: string;
    dimension: string;
    type: string;
}

/**
 * 构建基础筛选条件
 */
function buildWhereClause(config: PracticeConfig): { where: string; params: any[] } {
    const conditions: string[] = [];
    const params: any[] = [];

    // 题目类型筛选
    if (config.types && config.types.length > 0) {
        conditions.push(`q.type IN (${config.types.map(() => '?').join(', ')})`);
        params.push(...config.types);
    }

    // 维度筛选
    if (config.dimensions && config.dimensions.length > 0) {
        conditions.push(`q.dimension IN (${config.dimensions.map(() => '?').join(', ')})`);
        params.push(...config.dimensions);
    }

    // 知识点筛选
    if (config.tags && config.tags.length > 0) {
        const tagConditions = config.tags.map(() =>
            `EXISTS (SELECT 1 FROM json_each(q.tags) WHERE value = ?)`
        ).join(' OR ');
        conditions.push(`(${tagConditions})`);
        params.push(...config.tags);
    }

    const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    return { where, params };
}

/**
 * 智能刷题模式 (40/40/20)
 * 40% 顽固题 + 40% 盲区 + 20% 随机
 */
function generateSmartSession(config: PracticeConfig, userId: number): Question[] {
    const { limit } = config;
    const stubbornCount = Math.floor(limit * 0.4);
    const blindCount = Math.floor(limit * 0.4);
    const regularCount = limit - stubbornCount - blindCount;

    const { where, params } = buildWhereClause(config);

    // 1. 顽固题：观察区知识点的题目
    const stubbornQuestions = db.prepare(`
    SELECT DISTINCT q.* FROM questions q
    JOIN observation_zone oz ON EXISTS (
      SELECT 1 FROM json_each(q.tags) WHERE value = oz.tag_name
    )
    ${where ? where + ' AND oz.status = ? AND oz.user_id = ?' : 'WHERE oz.status = ? AND oz.user_id = ?'}
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, 'active', userId, stubbornCount) as Question[];

    const usedIds = stubbornQuestions.map(q => q.id);

    // 2. 盲区题：从未练习过的题目
    const blindQuestions = db.prepare(`
    SELECT q.* FROM questions q
    ${where} ${where ? 'AND' : 'WHERE'} NOT EXISTS (
      SELECT 1 FROM practice_logs pl WHERE pl.question_id = q.id AND pl.user_id = ?
    )
    ${usedIds.length > 0 ? `AND q.id NOT IN (${usedIds.join(',')})` : ''}
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, userId, blindCount) as Question[];

    usedIds.push(...blindQuestions.map(q => q.id));

    // 3. 常规题：随机
    const regularQuestions = db.prepare(`
    SELECT q.* FROM questions q
    ${where} ${where ? 'AND' : 'WHERE'} q.id NOT IN (${usedIds.length > 0 ? usedIds.join(',') : '0'})
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, regularCount) as Question[];

    // 合并并打乱
    const session = [...stubbornQuestions, ...blindQuestions, ...regularQuestions];
    return session.sort(() => Math.random() - 0.5);
}

/**
 * 错题强化模式
 * 只练习历史错题，按错误次数排序
 */
function generateReviewSession(config: PracticeConfig, userId: number): Question[] {
    const { where, params } = buildWhereClause(config);

    const questions = db.prepare(`
    SELECT q.*, COUNT(pl.id) as error_count
    FROM questions q
    JOIN practice_logs pl ON pl.question_id = q.id
    ${where} ${where ? 'AND' : 'WHERE'} pl.user_id = ? AND pl.is_correct = 0
    GROUP BY q.id
    ORDER BY error_count DESC, RANDOM()
    LIMIT ?
  `).all(...params, userId, config.limit) as Question[];

    return questions;
}

/**
 * 专项突破模式
 * 按指定知识点或维度筛选
 */
function generateFocusSession(config: PracticeConfig, userId: number): Question[] {
    const { where, params } = buildWhereClause(config);

    if (!where) {
        // 如果没有筛选条件，回退到随机模式
        return generateRandomSession(config, userId);
    }

    const questions = db.prepare(`
    SELECT q.* FROM questions q
    ${where}
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, config.limit) as Question[];

    return questions;
}

/**
 * 模拟考试模式
 * 随机抽题，按 ID 顺序排列（模拟真实考试）
 */
function generateExamSession(config: PracticeConfig, userId: number): Question[] {
    const { where, params } = buildWhereClause(config);

    const questions = db.prepare(`
    SELECT q.* FROM questions q
    ${where}
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, config.limit) as Question[];

    // 模拟考试按 ID 排序，保持一致性
    return questions.sort((a, b) => a.id - b.id);
}

/**
 * 随机挑战模式
 * 完全随机
 */
function generateRandomSession(config: PracticeConfig, userId: number): Question[] {
    const { where, params } = buildWhereClause(config);

    const questions = db.prepare(`
    SELECT q.* FROM questions q
    ${where}
    ORDER BY RANDOM()
    LIMIT ?
  `).all(...params, config.limit) as Question[];

    return questions;
}

/**
 * 根据配置生成练习会话
 */
export function generateSessionByConfig(config: PracticeConfig, userId: number): Question[] {
    switch (config.mode) {
        case 'smart':
            return generateSmartSession(config, userId);
        case 'review':
            return generateReviewSession(config, userId);
        case 'focus':
            return generateFocusSession(config, userId);
        case 'exam':
            return generateExamSession(config, userId);
        case 'random':
            return generateRandomSession(config, userId);
        default:
            return generateSmartSession(config, userId);
    }
}

/**
 * 获取所有可用的知识点标签
 */
export function getAllTags(): string[] {
    const result = db.prepare(`
    SELECT DISTINCT value as tag
    FROM questions, json_each(questions.tags)
    ORDER BY value
  `).all() as { tag: string }[];

    return result.map(r => r.tag);
}

/**
 * 获取用户错题知识点统计
 */
export function getUserWrongTags(userId: number): { tag: string; count: number }[] {
    const result = db.prepare(`
    SELECT je.value as tag, COUNT(*) as count
    FROM practice_logs pl
    JOIN questions q ON q.id = pl.question_id
    JOIN json_each(q.tags) je
    WHERE pl.user_id = ? AND pl.is_correct = 0
    GROUP BY je.value
    ORDER BY count DESC
  `).all(userId) as { tag: string; count: number }[];

    return result;
}

import { z } from 'zod';

// --- Base Schemas ---

const BaseQuestionSchema = z.object({
  content: z.string().min(5, "题干长度至少为5个字符"),
  options: z.array(z.string().min(1, "选项内容不能为空")).min(2, "至少需要2个选项").max(10),
  answer: z.string().min(1, "必须指定正确答案"),
  explanation: z.string().min(5, "解析长度至少为5个字符"),
  tags: z.array(z.string().min(1, "标签内容不能为空")).min(1, "至少需要1个标签"),
  dimension: z.enum(['knowledge', 'understanding', 'application'], {
    message: "维度必须是 'knowledge'、'understanding' 或 'application'"
  }).or(z.string()), // Relax dimension as well just in case
  type: z.string().optional().default('single'), // Relax type to string to support legacy data
});

export const QuestionSchema = BaseQuestionSchema.refine((data) => {
  // 判断题：选项固定为 ["正确", "错误"]，答案只能是 "A" 或 "B"
  if (data.type === 'truefalse') {
    return (data.answer === 'A' || data.answer === 'B') && data.options.length === 2;
  }

  // 通用匹配逻辑：支持内容匹配标号 或 标号匹配内容
  const isMatch = (ans: string) => {
    if (data.options.includes(ans)) return true;
    if (ans.length === 1 && ans >= 'A' && ans <= 'Z') {
      const idx = ans.charCodeAt(0) - 65;
      return !!data.options[idx];
    }
    return false;
  };

  if (data.type === 'multi') {
    try {
      const answers = JSON.parse(data.answer);
      if (!Array.isArray(answers) || answers.length < 1) return false;
      return answers.every(a => isMatch(a));
    } catch {
      return false;
    }
  }
  return isMatch(data.answer);
}, {
  message: "正确答案必须是选项之一或有效的选项标号(A/B/C/D)",
  path: ["answer"]
});

// --- Phase 4 Specific Schemas ---

/**
 * Task 4.1: Correction Quiz (找茬对比题)
 * Requirements: Compare the wrong option with the correct one.
 */
export const CorrectionQuizSchema = z.object({
  analysis: z.string().describe("分析用户错误选项与正确选项的区别"),
  distinctionPoint: z.string().describe("区分这两个概念的核心逻辑点"),
  quiz: z.object({
    content: z.string().describe("针对该核心逻辑点生成的一个辨析题"),
    options: z.array(z.string()),
    answer: z.string(),
    explanation: z.string()
  })
});

/**
 * Task 4.2: Regression Challenge (逻辑逆向/补集测试)
 */
export const RegressionChallengeSchema = z.object({
  logicType: z.enum(['reverse', 'complement', 'boundary']).describe("逆向/补集/边界测试"),
  challenges: z.array(z.object({
    content: z.string(),
    options: z.array(z.string()),
    answer: z.string(),
    explanation: z.string()
  })).length(3) // PRD: 3 questions for recovery
});

export type CorrectionQuiz = z.infer<typeof CorrectionQuizSchema>;
export type RegressionChallenge = z.infer<typeof RegressionChallengeSchema>;

// --- Persistence Schemas (Database Rows) ---

export const PracticeSessionRowSchema = z.object({
  id: z.string(),
  user_id: z.number(),
  session_name: z.string().nullable().optional(),
  total_questions: z.number(),
  correct_count: z.number().default(0),
  review_count: z.number().default(0),
  created_at: z.string().optional(),
  questions_json: z.string().transform((str, ctx) => {
    try {
      if (!str) return [];
      return JSON.parse(str);
    } catch (e) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: "Invalid JSON in questions_json" });
      return [];
    }
  }),
  practice_mode: z.string().nullable().optional(),
});

export const PracticeLogRowSchema = z.object({
  id: z.number(),
  session_id: z.string().nullable(),
  user_id: z.number(),
  question_id: z.number(),
  user_answer: z.string(),
  is_correct: z.number().transform(val => Boolean(val)), // SQLite stores boolean as 0/1
  duration_ms: z.number(),
  timestamp: z.string().optional()
});

// 数据库行 Schema，包含自动 JSON 解析
export const QuestionRowSchema = BaseQuestionSchema.extend({
  id: z.number(), // 数据库都有 ID
  options: z.string().transform((str, ctx): string[] => {
    try {
      const parsed = JSON.parse(str);
      return z.array(z.string()).parse(parsed);
    } catch {
      return [];
    }
  }).or(z.array(z.string())), // 兼容已经是数组的情况（虽然 sqlite 通常返回 string）
  tags: z.string().transform((str, ctx): string[] => {
    try {
      const parsed = JSON.parse(str);
      return z.array(z.string()).parse(parsed);
    } catch {
      return [];
    }
  }).or(z.array(z.string())),
});

export type PracticeSessionRow = z.infer<typeof PracticeSessionRowSchema>;
export type PracticeLogRow = z.infer<typeof PracticeLogRowSchema>;
export type QuestionRow = z.infer<typeof QuestionRowSchema>;

