// Default Prompts imported from @/lib/ai/prompts

export async function generateCorrectionQuizAction(
  questionContent: string,
  wrongAnswer: string,
  correctAnswer: string,
  force: boolean = false
): Promise<CorrectionQuiz> {
  // 1. Ensure Table
  try {
    db.exec(`
      CREATE TABLE IF NOT EXISTS ai_quiz_cache (
        hash TEXT PRIMARY KEY,
        data TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
    `);
  } catch (e) {
    logger.error({ err: e }, '[QuizCache] Error creating table');
  }

  // 2. Check Cache
  const cacheKey = generateHash(questionContent + wrongAnswer + correctAnswer);
  if (!force) {
    const cached = db.prepare('SELECT data FROM ai_quiz_cache WHERE hash = ?').get(cacheKey) as { data: string } | undefined;
    if (cached) {
      logger.info('[QuizCache] 命中缓存');
      return JSON.parse(cached.data) as CorrectionQuiz;
    }
  }

  const dbTemplate = getPromptFromDbSync('correction_quiz');
  const template = dbTemplate || DEFAULT_CORRECTION_PROMPT;

  const prompt = buildPrompt(template, {
    questionContent,
    wrongAnswer,
    correctAnswer
  });

  try {
    const result = await generateStructuredData(CorrectionQuizSchema, prompt, 'premium');
    // 4. Save to Cache
    try {
      db.prepare('INSERT OR REPLACE INTO ai_quiz_cache (hash, data) VALUES (?, ?)').run(cacheKey, JSON.stringify(result));
    } catch (e) {
      logger.error({ err: e }, '[QuizCache] 保存失败');
    }
    return result;
  } catch (error) {
    logger.warn('Correction Quiz AI generation failed, using RAG fallback.');
    const similar = await questionService.searchSimilarQuestions(questionContent, 1);

    if (similar && similar.length > 0) {
      const q = similar[0];
      let options = [];
      try {
        options = typeof q.options === 'string' ? JSON.parse(q.options) : q.options;
        if (!Array.isArray(options)) options = [];
      } catch (e) {
        options = [];
      }

      return {
        analysis: "AI 生成暂时不可用，我们为您检索了一道相关的强化训练题。",
        distinctionPoint: "知识点辨析",
        quiz: {
          content: q.content,
          options: options,
          answer: q.answer,
          explanation: q.explanation || '库内相似真题解析'
        }
      };
    }
    throw error;
  }
}

export async function generateRegressionChallengeAction(
  questionContent: string,
  tags: string[],
  force: boolean = false
): Promise<RegressionChallenge> {
  // 1. Ensure Table
  try {
    db.exec(`
      CREATE TABLE IF NOT EXISTS ai_challenge_cache (
        hash TEXT PRIMARY KEY,
        data TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
    `);
  } catch (e) {
    logger.error({ err: e }, '[ChallengeCache] Error creating table');
  }

  // 2. Check Cache
  const cacheKey = generateHash(questionContent + tags.join('|'));
  if (!force) {
    const cached = db.prepare('SELECT data FROM ai_challenge_cache WHERE hash = ?').get(cacheKey) as { data: string } | undefined;
    if (cached) {
      logger.info('[ChallengeCache] 命中缓存');
      return JSON.parse(cached.data) as RegressionChallenge;
    }
  }

  const dbTemplate = getPromptFromDbSync('regression_challenge');
  const template = dbTemplate || DEFAULT_REGRESSION_PROMPT;

  const prompt = buildPrompt(template, {
    questionContent,
    tags: tags.join(', ')
  });

  try {
    // API A: Generate
    const challenge = await generateStructuredData(RegressionChallengeSchema, prompt, 'premium');

    // API B: Validate
    const validationPrompt = `
      作为质量审计专家，请评估以下回归挑战题目的质量。
      
      原题背景: "${questionContent}"
      生成的挑战题目: ${JSON.stringify(challenge)}
      
      这些题目是否逻辑严密、无歧义，且真正考察了原题知识点的对立面或深度变式？
      请仅回答 "YES" 或 "NO"。
    `;

    const { text: validationResult } = await generateTextWrapper(validationPrompt, 'premium');

    if (validationResult.includes('YES')) {
      // 4. Save Cache only if valid
      try {
        db.prepare('INSERT OR REPLACE INTO ai_challenge_cache (hash, data) VALUES (?, ?)').run(cacheKey, JSON.stringify(challenge));
      } catch (e) {
        logger.error({ err: e }, '[ChallengeCache] 保存失败');
      }
      return challenge;
    } else {
      logger.warn('Double Insurance failed: API B rejected API A. Falling back to library retrieval.');
      throw new Error('Double Insurance rejected');
    }

  } catch (error) {
    logger.warn({ err: error }, 'AI Generation failed or rejected, falling back to RAG similarity search');

    // Fallback: Retrieve similar real questions from the database
    const similarQuestions = await questionService.searchSimilarQuestions(questionContent, 5);

    if (similarQuestions && similarQuestions.length > 0) {
      // 提取并填充，确保满足 Schema 要求的 3 道题
      const mappedChallenges = similarQuestions.map(q => {
        let options = [];
        try {
          options = typeof q.options === 'string' ? JSON.parse(q.options) : q.options;
          if (!Array.isArray(options)) options = [];
        } catch (e) {
          options = [];
        }

        return {
          content: q.content,
          options: options,
          answer: q.answer,
          explanation: q.explanation || '库内相似真题解析，建议巩固相关知识点。'
        };
      });

      // 填充补齐 3 道题
      while (mappedChallenges.length < 3) {
        mappedChallenges.push({ ...mappedChallenges[0] });
      }

      return {
        logicType: 'complement',
        challenges: mappedChallenges.slice(0, 3)
      } as RegressionChallenge;
    }

    // 最终兜底
    logger.error('Final fallback failed: AI and RAG both unavailable.');
    throw new Error('无法生成挑战且本地题库检索失败，请检查 AI 配置');
  }
}


// 确保缓存表存在
function ensureFirstPrinciplesCacheTable() {
  try {
    db.exec(`
          CREATE TABLE IF NOT EXISTS first_principles_cache (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              question_hash TEXT UNIQUE NOT NULL,
              analysis TEXT NOT NULL,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP
          );
          CREATE INDEX IF NOT EXISTS idx_fp_cache_hash ON first_principles_cache(question_hash);
      `);
  } catch (e) {
    logger.error({ err: e }, '[FirstPrinciples] 创建缓存表失败');
  }
}

// 生成内容哈希
function generateHash(content: string): string {
  const normalized = content.trim().slice(0, 100) + content.length;
  let hash = 0;
  for (let i = 0; i < normalized.length; i++) {
    const char = normalized.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return hash.toString(36);
}

export async function generateFirstPrinciplesAction(
  questionContent: string,
  explanation: string,
  correctAnswer: string,
  wrongAnswer?: string,
  force: boolean = false
): Promise<{ analysis: string; cached?: boolean }> {
  const user = await requireUser();

  if (!questionContent) {
    throw new Error('缺少题目内容');
  }

  ensureFirstPrinciplesCacheTable();

  // 1. Check Cache (skip if force=true)
  const cacheKey = generateHash(questionContent + correctAnswer + (wrongAnswer || ''));

  if (!force) {
    const cached = db.prepare(
      'SELECT analysis FROM first_principles_cache WHERE question_hash = ?'
    ).get(cacheKey) as { analysis: string } | undefined;

    if (cached) {
      logger.info('[FirstPrinciples] 命中缓存');
      return { analysis: cached.analysis, cached: true };
    }
  }

  // 2. Check Quota
  // Note: Cast user.id to number as checkAndConsumeQuota expects number
  const userIdNum = typeof user.id === 'string' ? parseInt(user.id, 10) : user.id;
  if (!isNaN(userIdNum)) {
    const quotaResult = checkAndConsumeQuota(userIdNum, 'first_principles');
    if (!quotaResult.allowed) {
      throw new Error(quotaResult.message || '今日第一性原理分析次数已用完，请升级套餐解锁更多。');
    }
  }

  // 3. Build Prompt (User's original prompt logic)
  // Use DB template if exists, otherwise use hardcoded logic from user request to ensure fidelity
  const dbTemplate = getPromptFromDbSync('first_principles');

  let prompt: string;
  if (dbTemplate) {
    prompt = buildPrompt(dbTemplate, {
      questionContent,
      explanation: explanation || '略',
      correctAnswer,
      wrongAnswer: wrongAnswer || '无'
    });
  } else {
    // User's requested specific prompt format
    prompt = `请用"第一性原理"解析这道题。要求：
1. 直接给答案，只说底层逻辑，不超过200字
2. 不要使用黑话，用通俗易懂的语言
3. 严格基于提供的题目内容和选项进行分析，禁止引用题目中未提及的观点，禁止编造不存在的选项。

题目：${questionContent}
正确答案：${correctAnswer}
${wrongAnswer ? `用户选择：${wrongAnswer}` : ''}
${explanation ? `参考解析：${explanation}` : ''}

回复格式：
【答案】X
【核心逻辑】...`;
  }

  try {
    logger.info('[FirstPrinciples] 开始调用 AI...');
    // User requested 'economy' model with specific timeout
    const result = await generateTextWrapper(prompt, 'economy', undefined, undefined, {
      timeout: 30000,
      retries: 1,
    });
    const text = result.text;
    logger.info({ value: text.length }, '[FirstPrinciples] AI 调用成功，长度');

    // 4. Save to Cache
    try {
      db.prepare(
        'INSERT OR REPLACE INTO first_principles_cache (question_hash, analysis) VALUES (?, ?)'
      ).run(cacheKey, text);
    } catch (cacheError) {
      logger.error({ err: cacheError }, '[FirstPrinciples] 缓存保存失败');
    }

    return { analysis: text, cached: false };
  } catch (error: unknown) {
    logger.error({ err: error }, 'First Principles analysis failed');
    throw new Error(`AI 分析失败: ${getErrorMessage(error, '请稍后重试')}`);
  }
}

'use server';
import logger from '@/lib/logger';

import db from '@/lib/db';
import { calculateCultivation } from '@/lib/cultivation/engine';
import { CultivationState, LeaderboardEntry } from '@/lib/cultivation/types';

/**
 * 获取封神榜数据 (前 20 名)
 */
export async function getLeaderboardAction(): Promise<LeaderboardEntry[]> {
  try {
    // 聚合统计全员数据
    // 注意：SQLite 的聚合查询
    const rows = db.prepare(`
      SELECT 
        u.id, 
        u.username, 
        COUNT(DISTINCT p.id) as total_practiced,
        (SELECT AVG(score) FROM user_mastery WHERE user_id = u.id) as avg_mastery
      FROM users u
      LEFT JOIN practice_logs p ON u.id = p.user_id
      GROUP BY u.id
      ORDER BY total_practiced DESC
      LIMIT 20
    `).all() as { id: number; username: string; total_practiced: number; avg_mastery: number | null }[];

    // 映射境界数据
    const leaderboard = rows.map(row => {
      const mastery = Math.round(row.avg_mastery || 0);
      return {
        userId: row.id,
        username: row.username,
        totalPracticed: row.total_practiced,
        averageMastery: mastery,
        cultivation: calculateCultivation(row.total_practiced, mastery)
      };
    });

    return leaderboard;
  } catch (error) {
    logger.error({ err: error }, 'Failed to fetch leaderboard');
    return [];
  }
}

'use server';
import logger from '@/lib/logger';

import db from '@/lib/db';
import { z } from 'zod';
import { requireUser } from '@/lib/auth/auth';

// --- Types ---

/** user_mastery 表行 */
interface UserMasteryRow {
    tag_name: string;
    score: number;
    history: string;
    last_updated: string;
}

/** practice_logs 表行（备份相关字段） */
interface PracticeLogBackupRow {
    session_id: string;
    question_id: number;
    user_answer: string;
    is_correct: number;
    is_monitored_correct: number;
    duration_ms: number;
    timestamp: string;
}

/** observation_zone 表行 */
interface ObservationZoneRow {
    tag_name: string;
    reason: string;
    entered_at: string;
    status: string;
}

export interface BackupData {
    version: number;
    timestamp: string;
    user_mastery: UserMasteryRow[];
    practice_logs: PracticeLogBackupRow[];
    observation_zone: ObservationZoneRow[];
}

// --- Actions ---

export async function exportUserDataAction(): Promise<BackupData> {
  try {
    const user = await requireUser();
    const user_mastery = db.prepare('SELECT * FROM user_mastery WHERE user_id = ?').all(user.id) as UserMasteryRow[];
    const practice_logs = db.prepare('SELECT * FROM practice_logs WHERE user_id = ?').all(user.id) as PracticeLogBackupRow[];
    const observation_zone = db.prepare('SELECT * FROM observation_zone WHERE user_id = ?').all(user.id) as ObservationZoneRow[];

    return {
      version: 1,
      timestamp: new Date().toISOString(),
      user_mastery,
      practice_logs,
      observation_zone
    };
  } catch (error) {
    logger.error({ err: error }, "Export failed");
    throw new Error("Failed to export data");
  }
}

export async function importUserDataAction(data: BackupData): Promise<{ success: boolean; message: string }> {
  if (!data || data.version !== 1) {
    return { success: false, message: "Invalid backup format or version mismatch." };
  }

  try {
    const user = await requireUser();

    const transaction = db.transaction(() => {
      // 1. Clear existing user data
      db.prepare('DELETE FROM user_mastery WHERE user_id = ?').run(user.id);
      db.prepare('DELETE FROM practice_logs WHERE user_id = ?').run(user.id);
      db.prepare('DELETE FROM observation_zone WHERE user_id = ?').run(user.id);

      // 2. Insert User Mastery
      const insertMastery = db.prepare(`
        INSERT INTO user_mastery (user_id, tag_name, score, history, last_updated)
        VALUES (?, @tag_name, @score, @history, @last_updated)
      `);
      for (const row of data.user_mastery) {
        insertMastery.run(user.id, row);
      }

      // 3. Insert Practice Logs
      const insertLog = db.prepare(`
        INSERT INTO practice_logs (user_id, session_id, question_id, user_answer, is_correct, is_monitored_correct, duration_ms, timestamp)
        VALUES (?, @session_id, @question_id, @user_answer, @is_correct, @is_monitored_correct, @duration_ms, @timestamp)
      `);
      for (const row of data.practice_logs) {
        insertLog.run(user.id, row);
      }

      // 4. Insert Observation Zone
      const insertObs = db.prepare(`
        INSERT INTO observation_zone (user_id, tag_name, reason, entered_at, status)
        VALUES (?, @tag_name, @reason, @entered_at, @status)
      `);
      for (const row of data.observation_zone) {
        insertObs.run(user.id, row);
      }
    });

    transaction();
    return { success: true, message: "Data imported successfully." };
  } catch (error) {
    logger.error({ err: error }, "Import failed");
    return { success: false, message: `Import failed: ${error instanceof Error ? error.message : String(error)}` };
  }
}

'use server';
import logger from '@/lib/logger';

import db from '@/lib/db';
import { requireUser } from '@/lib/auth/auth';
import { parseFenbiData, validateFenbiJson, ParsedQuestion, ParsedRecord } from '@/lib/import/fenbi-parser';
import { masteryService } from '@/lib/services/mastery';
import { sanitizeHtml } from '@/lib/utils/security';
import { cookies } from 'next/headers';
import { COOKIE_NAME } from '@/lib/auth/auth-edge';

/**
 * 导入结果
 */
export interface ImportResult {
    success: boolean;
    sessionId?: string;
    importedCount: number;
    newQuestionsCount: number;
    skippedQuestionsCount: number;
    message: string;
}

/**
 * 获取当前用户的导入鉴权 Token
 */
export async function getImportTokenAction(): Promise<string | null> {
    const sessionCookie = (await cookies()).get(COOKIE_NAME)?.value;
    return sessionCookie || null;
}

/**
 * 导入粉笔 APP 数据
 */
export async function importFenbiDataAction(
    exerciseJson: string,
    solutionsJson: string,
    statsJson?: string
): Promise<ImportResult> {
    try {
        const user = await requireUser();

        // 1. 验证 JSON 格式
        const validation = validateFenbiJson(exerciseJson, solutionsJson);
        if (!validation.valid) {
            return {
                success: false,
                importedCount: 0,
                newQuestionsCount: 0,
                skippedQuestionsCount: 0,
                message: validation.error || 'JSON 格式无效'
            };
        }

        // 2. 解析数据
        const parsed = parseFenbiData(exerciseJson, solutionsJson, statsJson);

        if (parsed.questions.length === 0) {
            return {
                success: false,
                importedCount: 0,
                newQuestionsCount: 0,
                skippedQuestionsCount: 0,
                message: '解析结果为空，请检查数据格式'
            };
        }

        // 3. 准备导入上下文
        const sessionId = `fenbi_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
        let newQuestionsCount = 0;
        let skippedQuestionsCount = 0;
        const questionIdMap = new Map<string, number>(); // externalId -> 内部 id

        // 5. 使用事务执行所有数据库操作
        const executeTransaction = db.transaction(() => {
            // 3. 创建练习会话
            db.prepare(`
              INSERT INTO practice_sessions (id, user_id, session_name, total_questions, correct_count, practice_mode, questions_json)
              VALUES (?, ?, ?, ?, ?, ?, ?)
            `).run(
                sessionId,
                user.id,
                parsed.sessionName,
                parsed.totalCount,
                parsed.correctCount,
                'import',
                JSON.stringify(parsed.questions.map(q => ({
                    externalId: q.externalId,
                    content: q.content,
                    type: q.type
                })))
            );

            // 4. 处理题目
            const insertQuestion = db.prepare(`
              INSERT INTO questions (content, options, answer, explanation, tags, dimension, type, external_id, source, correct_ratio, most_wrong_answer, material, material_html)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `);

            const findQuestion = db.prepare(`
              SELECT id FROM questions WHERE external_id = ?
            `);

            const updateQuestionStats = db.prepare(`
                UPDATE questions 
                SET correct_ratio = ?, most_wrong_answer = ?
                WHERE id = ?
            `);

            const updateFullQuestion = db.prepare(`
                UPDATE questions 
                SET material = ?, material_html = ?, content = ?, explanation = ?,
                    type = ?, answer = ?, options = ?
                WHERE id = ?
            `);

            const ALLOWED_DIMENSIONS = ['knowledge', 'understanding', 'application'];

            for (const question of parsed.questions) {
                const existing = findQuestion.get(question.externalId) as { id: number } | undefined;
                
                // 维度合法性校验：如果维度不在白名单内，回退到 'knowledge'
                const safeDimension = ALLOWED_DIMENSIONS.includes(question.dimension) ? question.dimension : 'knowledge';

                if (existing) {
                    questionIdMap.set(question.externalId, existing.id);
                    if (question.stats?.correctRatio != null || question.stats?.mostWrongAnswer != null) {
                        updateQuestionStats.run(
                            question.stats?.correctRatio ?? null,
                            question.stats?.mostWrongAnswer ?? null,
                            existing.id
                        );
                    }

                    const typeMap: Record<string, string> = {
                        'single': 'single', 'multi': 'multi', 'truefalse': 'truefalse', 'fill_blank': 'single'
                    };

                    updateFullQuestion.run(
                        question.material ? sanitizeHtml(question.material) : null,
                        question.materialHtml ? sanitizeHtml(question.materialHtml) : null,
                        sanitizeHtml(question.content),
                        sanitizeHtml(question.explanation),
                        typeMap[question.type] || 'single',
                        question.answer,
                        JSON.stringify(question.options),
                        existing.id
                    );
                    skippedQuestionsCount++;
                } else {
                    const typeMap: Record<string, string> = {
                        'single': 'single', 'multi': 'multi', 'truefalse': 'truefalse', 'fill_blank': 'single'
                    };

                    const result = insertQuestion.run(
                        sanitizeHtml(question.content),
                        JSON.stringify(question.options),
                        question.answer,
                        sanitizeHtml(question.explanation),
                        JSON.stringify(question.tags),
                        safeDimension,
                        typeMap[question.type] || 'single',
                        question.externalId,
                        question.source || 'fenbi_import', // 取题目真实的来源，无则降级为fenbi_import
                        question.stats?.correctRatio ?? null,
                        question.stats?.mostWrongAnswer ?? null,
                        question.material ? sanitizeHtml(question.material) : null,
                        question.materialHtml ? sanitizeHtml(question.materialHtml) : null
                    );

                    questionIdMap.set(question.externalId, result.lastInsertRowid as number);
                    newQuestionsCount++;
                }
            }

            // 5. 记录日志并累计 Mastery 变化
            const insertLog = db.prepare(`
              INSERT INTO practice_logs (session_id, user_id, question_id, user_answer, is_correct, duration_ms)
              VALUES (?, ?, ?, ?, ?, ?)
            `);

            // 维护一个内存中的 tag 计数器以减少数据库写入
            const masteryChanges = new Map<string, { correct: number; total: number; dimension: string }>();

            for (const record of parsed.records) {
                const questionId = questionIdMap.get(record.externalId);
                if (questionId) {
                    insertLog.run(
                        sessionId,
                        user.id,
                        questionId,
                        record.userAnswer,
                        record.isCorrect ? 1 : 0,
                        record.durationMs
                    );

                    const question = parsed.questions.find(q => q.externalId === record.externalId);
                    if (question && question.tags.length > 0) {
                        for (const tag of question.tags) {
                            const current = masteryChanges.get(tag) || { correct: 0, total: 0, dimension: question.dimension };
                            current.total += 1;
                            if (record.isCorrect) current.correct += 1;
                            masteryChanges.set(tag, current);
                        }
                    }
                }
            }

            // 批量应用 Mastery 变化 (显著减少数据库 IO)
            for (const [tag, stats] of masteryChanges.entries()) {
                // 这里我们稍微修改逻辑：如果导入量很大，这样能节省大量事务内开销
                // 我们调用一个新的批量更新方法或模拟它
                const currentEntry = db.prepare(
                    'SELECT score, correct_count, total_count FROM user_mastery WHERE user_id = ? AND tag_name = ?'
                ).get(user.id, tag) as { score: number; correct_count: number; total_count: number } | undefined;

                const newCorrect = (currentEntry?.correct_count ?? 0) + stats.correct;
                const newTotal = (currentEntry?.total_count ?? 0) + stats.total;
                const newScore = newTotal > 0 ? (newCorrect / newTotal) * 100 : 0;

                db.prepare(`
                    INSERT INTO user_mastery (user_id, tag_name, score, correct_count, total_count, last_updated) 
                    VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                    ON CONFLICT(user_id, tag_name) DO UPDATE SET 
                      score = excluded.score,
                      correct_count = excluded.correct_count,
                      total_count = excluded.total_count,
                      last_updated = CURRENT_TIMESTAMP
                `).run(user.id, tag, newScore, newCorrect, newTotal);
            }
        });

        executeTransaction();

        return {
            success: true,
            sessionId,
            importedCount: parsed.records.length,
            newQuestionsCount,
            skippedQuestionsCount,
            message: `成功导入 ${parsed.records.length} 条作答记录，新增 ${newQuestionsCount} 道题目`
        };

    } catch (error) {
        logger.error({ err: error }, '粉笔数据导入失败');
        return {
            success: false,
            importedCount: 0,
            newQuestionsCount: 0,
            skippedQuestionsCount: 0,
            message: `导入失败: ${(error as Error).message}`
        };
    }
}

