export interface KnowledgeParams {
  name: string;
  path: string; // Full path for querying
  children: KnowledgeParams[];
  count: number; // Number of questions under this node (recursive)
}

/**
 * 获取知识点树形结构
 * Tags format: "Subject/Chapter/Topic"
 */
export async function getKnowledgeTreeAction(): Promise<KnowledgeParams[]> {
  try {
    const result = db.prepare(`
      SELECT DISTINCT value as tag, COUNT(*) as count
      FROM questions, json_each(questions.tags)
      GROUP BY value
      ORDER BY value
    `).all() as { tag: string; count: number }[];

    const root: KnowledgeParams[] = [];

    result.forEach(({ tag, count }) => {
      const parts = tag.split('/');
      let currentLevel = root;
      let currentPath = "";

      parts.forEach((part, index) => {
        currentPath = currentPath ? `${currentPath}/${part}` : part;
        let existingNode = currentLevel.find(n => n.name === part);

        if (!existingNode) {
          existingNode = {
            name: part,
            path: currentPath,
            children: [],
            count: 0 // Will accumulate later or simplified here
          };
          currentLevel.push(existingNode);
        }

        // Simple addition: add the count of this specific tag occurrence to the node
        // Note: multiple tags might share parents. Ideally we sum them up.
        // For simplicity, we just ensure the node exists. The count logic can be refined if needed.
        if (index === parts.length - 1) {
          existingNode.count += count;
        }

        currentLevel = existingNode.children;
      });
    });

    // Helper to sum up counts recursively
    const calculateCounts = (nodes: KnowledgeParams[]): number => {
      let sum = 0;
      for (const node of nodes) {
        const childrenSum = calculateCounts(node.children);
        node.count = (node.count || 0) + childrenSum;
        sum += node.count;
      }
      return sum;
    }
    // Note: The above count logic is imperfect because a parent might not have its own direct questions
    // but we want to show how many questions are under it.
    // Let's refine: leaf nodes have accurate counts from SQL. 
    // Parent nodes should sum their children's counts + their own direct count (if any).

    // Re-implement accumulation correctly
    const recalculateTreeCounts = (nodes: KnowledgeParams[]): number => {
      let total = 0;
      for (const node of nodes) {
        // Find the original count from result if this path matches exactly?
        // Actually the 'result' loop already set count for exact matches.
        // Now we just add up children.
        const myTotal = node.count;
        if (node.children.length > 0) {
          // For intermediate nodes, their 'count' is purely from children in this simple model 
          // unless they are also tagged directly (which the loop handles).
          // However, we want 'count' to represent "total available questions under this branch".
          // So we sum up children.
          const childrenTotal = recalculateTreeCounts(node.children);
          node.count += childrenTotal;
        }
        total += node.count;
      }
      return total;
    }

    recalculateTreeCounts(root);

    return root;
  } catch (error) {
    logger.error({ err: error }, '获取知识树失败');
    return [];
  }
}

/**
 * 根据配置创建练习会话
 */
export async function getPracticeSessionByConfigAction(config: {
  mode: string;
  limit: number;
  types?: string[];
  tags?: string[];
  dimensions?: string[];
  enableReview?: boolean;
  enableTimer?: boolean;
}): Promise<{
  questions: Question[];
  sessionId: string;
  config: typeof config;
}> {
  try {
    const user = await requireUser();

    // 演示模式拦截
    if (isDemoModeEnabled()) {
      const demoResult = await getDemoSession(user.id);
      if (demoResult) return { ...demoResult, config };
    }

    const { generateSessionByConfig } = await import('@/lib/practice/practice-scheduling');

    // 构建配置
    const practiceConfig = {
      mode: config.mode as PracticeMode,
      limit: config.limit,
      types: config.types as ('single' | 'multi' | 'truefalse')[] | undefined,
      tags: config.tags,
      dimensions: config.dimensions as import('@/types').Dimension[] | undefined,
      enableReview: config.enableReview ?? true,
      enableTimer: config.enableTimer ?? false
    };

    // 生成题目
    const rawQuestions = generateSessionByConfig(practiceConfig, user.id);

    if (!rawQuestions || rawQuestions.length === 0) {
      return { questions: [], sessionId: '', config };
    }

    // 解析 JSON 字段
    const questions = rawQuestions.map(q => ({
      ...q,
      options: typeof q.options === 'string' ? JSON.parse(q.options) : q.options,
      tags: typeof q.tags === 'string' ? JSON.parse(q.tags) : q.tags
    })) as Question[];

    // 创建会话
    const sessionId = Math.random().toString(36).substring(2, 15);

    // 确保 questions_json 列存在
    try {
      db.prepare("ALTER TABLE practice_sessions ADD COLUMN questions_json TEXT").run();
    } catch (e) { /* ignore if exists */ }

    try {
      db.prepare("ALTER TABLE practice_sessions ADD COLUMN practice_mode TEXT").run();
    } catch (e) { /* ignore if exists */ }

    db.prepare(`
      INSERT INTO practice_sessions (id, user_id, total_questions, questions_json, practice_mode) 
      VALUES (?, ?, ?, ?, ?)
    `).run(sessionId, user.id, questions.length, JSON.stringify(questions), config.mode);

    return { questions, sessionId, config };
  } catch (error) {
    logger.error({ err: error }, '创建练习会话失败');
    throw new Error('无法创建练习会话，请稍后重试。');
  }
}

/**
 * 根据 sessionId 获取已创建的练习会话
 * 用于错题本等场景：先创建会话，再跳转到练习页面
 */
export async function getSessionByIdAction(sessionId: string): Promise<{
  questions: Question[];
  sessionId: string;
  completedCount: number;
  practiceMode?: string;
} | null> {
  try {
    const user = await requireUser();

    // 查询会话
    const session = safeGet(
      db.prepare(`
        SELECT * FROM practice_sessions 
        WHERE id = ? AND user_id = ?
      `),
      [sessionId, user.id],
      PracticeSessionRowSchema
    );

    if (!session || !session.questions_json) {
      return null;
    }

    // 解析 questions_json (already parsed by Schema)
    let questionsData = session.questions_json as unknown[];

    // 检查是 ID 数组还是完整题目对象数组
    if (questionsData.length > 0 && typeof questionsData[0] === 'string') {
      // 是字符串 ID 数组，需要查询完整题目
      const placeholders = questionsData.map(() => '?').join(',');
      const rawQuestions = safeAll(
        db.prepare(`SELECT * FROM questions WHERE id IN (${placeholders})`),
        questionsData,
        QuestionRowSchema
      );
      questionsData = rawQuestions;
    } else if (questionsData.length > 0 && typeof questionsData[0] === 'number') {
      // 是数字 ID 数组
      const placeholders = questionsData.map(() => '?').join(',');
      const rawQuestions = safeAll(
        db.prepare(`SELECT * FROM questions WHERE id IN (${placeholders})`),
        questionsData,
        QuestionRowSchema
      );
      questionsData = rawQuestions;
    } else {
      // 已经是完整题目对象，通过 Zod 校验
      // questionsData is already parsed Question[] mostly, but we can re-validate if needed.
      // Assuming trust logic from Schema transform.
    }

    // 获取已完成题目数
    const logResult = safeGet(
      db.prepare('SELECT count(*) as count FROM practice_logs WHERE session_id = ?'),
      [sessionId],
      z.object({ count: z.number() })
    );

    return {
      questions: questionsData as Question[],
      sessionId: session.id,
      completedCount: logResult?.count || 0,
      practiceMode: session.practice_mode || undefined // Handle null
    };
  } catch (error) {
    logger.error({ err: error }, '获取会话失败');
    return null;
  }
}

'use server';
import logger from '@/lib/logger';

import db from '@/lib/db';
import { generateStructuredData, generateTextWrapper, AiRawResponseError } from '@/lib/ai/client';
import { CorrectionQuizSchema, RegressionChallengeSchema } from '@/lib/schemas';
import { z } from 'zod';
import { buildPrompt, DEFAULT_CORRECTION_PROMPT, DEFAULT_REGRESSION_PROMPT, DEFAULT_KNOWLEDGE_EXTRACT_PROMPT, DEFAULT_CHAT_SYSTEM_PROMPT, PROMPT_VARIABLE_EXAMPLES } from '@/lib/ai/prompts';
import { requireRole } from '@/lib/auth/auth';
import { logAdminAction } from '@/lib/admin/audit';
import { getErrorMessage } from '@/lib/utils/error';

export interface PromptTemplate {
    key: string;
    template: string;
    description: string;
    variables: string[];
    updated_at: string;
    systemDefault?: string;
    variableExamples?: Record<string, string>; // New field for examples
}

export async function getPromptTemplatesAction(): Promise<PromptTemplate[]> {
    try {
        const rows = db.prepare('SELECT * FROM prompt_templates ORDER BY key').all() as Partial<PromptTemplate>[];

        // Let's first cast rows to partial objects
        const dbRows = rows.map(row => ({
            ...row,
            variables: JSON.parse((row.variables as string | undefined) || '[]')
        }));

        const existingKeys = new Set(dbRows.map(r => r.key));
        const defaults = [
            {
                key: 'correction_quiz',
                template: DEFAULT_CORRECTION_PROMPT,
                description: '纠偏找茬 (Correction Quiz)',
                variables: ['questionContent', 'wrongAnswer', 'correctAnswer']
            },
            {
                key: 'regression_challenge',
                template: DEFAULT_REGRESSION_PROMPT,
                description: '回归挑战 (Regression Challenge)',
                variables: ['questionContent', 'tags']
            },
            {
                key: 'knowledge_extract',
                template: DEFAULT_KNOWLEDGE_EXTRACT_PROMPT,
                description: '知识卡片提取 (Knowledge Card Extraction)',
                variables: ['content']
            },
            {
                key: 'chat_system',
                template: DEFAULT_CHAT_SYSTEM_PROMPT,
                description: 'AI 聊天辅助 (Chat System)',
                variables: []
            }
        ];

        const combined = [...dbRows];

        for (const def of defaults) {
            if (!existingKeys.has(def.key)) {
                combined.push({
                    key: def.key,
                    template: '',
                    description: def.description,
                    variables: def.variables,
                    updated_at: new Date().toISOString(),
                    systemDefault: def.template,
                    variableExamples: PROMPT_VARIABLE_EXAMPLES[def.key] || {}
                });
            } else {
                // Attach system default to existing row too
                const row = combined.find(r => r.key === def.key);
                if (row) {
                    row.systemDefault = def.template;
                    row.variableExamples = PROMPT_VARIABLE_EXAMPLES[def.key] || {};
                }
            }
        }

        return combined as PromptTemplate[];
    } catch (error) {
        logger.error({ err: error }, 'Failed to get prompt templates');
        return [];
    }
}

export async function savePromptTemplateAction(
    key: string,
    template: string,
    description: string,
    variables: string[]
): Promise<{ success: boolean; error?: string }> {
    const user = await requireRole(['admin']);
    try {
        db.prepare(`
      INSERT INTO prompt_templates (key, template, description, variables, updated_at)
      VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
      ON CONFLICT(key) DO UPDATE SET
        template = excluded.template,
        description = excluded.description,
        variables = excluded.variables,
        updated_at = CURRENT_TIMESTAMP
    `).run(key, template, description, JSON.stringify(variables));

        // 记录日志
        logAdminAction(user.id, user.username, 'UPDATE_PROMPT', 'prompt', key, { description });

        return { success: true };
    } catch (error: unknown) {
        logger.error({ err: error }, 'Failed to save prompt template');
        return { success: false, error: getErrorMessage(error) };
    }
}

export async function resetPromptTemplateAction(key: string): Promise<{ success: boolean; error?: string }> {
    const user = await requireRole(['admin']);
    try {
        db.prepare('DELETE FROM prompt_templates WHERE key = ?').run(key);

        // 记录日志
        logAdminAction(user.id, user.username, 'UPDATE_PROMPT', 'prompt', key, { action: 'reset_to_default' });

        return { success: true };
    } catch (error: unknown) {
        return { success: false, error: getErrorMessage(error) };
    }
}

// Debug Action
export async function debugPromptTemplateAction(
    key: string,
    template: string,
    inputVariables: Record<string, string>
): Promise<{ success: boolean; result?: unknown; error?: string }> {
    try {
        // 1. Interpolate variables
        const interpolatedPrompt = buildPrompt(template, inputVariables);

        logger.info(`[DebugPrompt] Running for ${key} with prompt length ${interpolatedPrompt.length}`);

        // 2. Select Schema based on key
        let result;
        if (key === 'correction_quiz') {
            result = await generateStructuredData(CorrectionQuizSchema, interpolatedPrompt, 'premium', { retries: 0 });
        } else if (key === 'regression_challenge') {
            result = await generateStructuredData(RegressionChallengeSchema, interpolatedPrompt, 'premium', { retries: 0 });
        } else {
            // Default to text if unknown key
            const { text } = await generateTextWrapper(interpolatedPrompt, 'premium', undefined, undefined, { retries: 0 });
            result = text;
        }

        return { success: true, result };
    } catch (error: unknown) {
        logger.error({ err: error }, 'Debug prompt failed');
        const rawResponse = error instanceof AiRawResponseError ? error.rawResponse : undefined;
        return {
            success: false,
            error: getErrorMessage(error),
            result: rawResponse ? `[RAW RESPONSE]\n${rawResponse}` : undefined,
        };
    }
}

