    test('C-01 聊天页面基础渲染', async ({ loggedInPage }) => {
        await loggedInPage.goto('/chat');

        // 输入框可见（≤15s）
        await expect(loggedInPage.locator('textarea')).toBeVisible({ timeout: 15000 });

